(window.GIM_TS=window.GIM_TS||{})["Yevamot.8"]={"from":192,"a":[["\u0003הא איסורא איכא\u0004 \u0005[הרי\u0006 ש\u0005איסור\u0006 מדברי סופרים \u0005יש]\u0006 וקשה לרב אחא! ודוחים: \u0003הוא הדין\u0004 ש\u0003אפילו איסורא נמי ליכא\u0004 \u0005[איסור גם כן אין],\u0006 \u0003ואיידי דבעי למיתני סיפא\u0004 \u0005[ומתוך שרצה\u0006 התנא \u0005לשנות\u0006 ב\u0005סוף]\u0006 \u0003\"אבל חייבין\",\u0004 ולשון \"חייב\" מדוייקת שם, \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005תחילה]\u0006 בלשון \u0003\"אין חייבין\"\u0004 שאינה מדוייקת, שהרי הם מותרים לגמרי.","\u0003אמר רבא: הא דאמור רבנן\u0004 \u0005[זה שאמרו חכמים]\u0006 בתור כלל: \u0003אין\u0004 ייחוס \u0003אב לגוי, לא תימא\u0004 \u0005[אל תאמר]\u0006 שהטעם הוא \u0003משום דשטופי\u0004 \u0005[ששטופים]\u0006 \u0003בזמה,\u0004 ש\u0003לא ידיע\u0004 \u0005[ידוע]\u0006 בוודאות שזה אביו, \u0003אבל\u0004 אם \u0003ידיע\u0004 \u0005[ידוע]\u0006 בבירור שזה אביו \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 גם למשפחת האב, \u0003אלא אפילו דידיע נמי לא חיישינן\u0004 \u0005[\u0006כ\u0005שידוע גם כן איננו חוששים].\u0006","וראיה לדבר \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שני אחין תאומים,\u0004 ש\u0003טפה אחת\u0004 (של זרע) \u0003היה ונחלקה לשתים\u0004 וממנה נוצרו התאומים (תאומים זהים), \u0003וקתני סיפא\u0004 \u0005[ושנה\u0006 ב\u0005סוף]\u0006 המשנה גם באלה: \u0003לא חולצין ולא מייבמין,\u0004 אף שבוודאי יש להם אב אחד, על כן, \u0003שמע מינה, אפקורי אפקריה רחמנא לזרעיה\u0004 \u0005[למד מכאן\u0006 כי \u0005הפקירה התורה את זרעו]\u0006 שלא יתייחסו בניו אחריו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במצרים: \u0003\"בשר חמורים בשרם וזרמת סוסים זרמתם\"\u0004 (יחזקאל כג, כ).","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, לענין איסור אשת אח בגרים, ש\u0003אמר ר' יוסי: מעשה בניפטיים הגר שנשא אשת אחיו מאמו, ובא מעשה לפני חכמים, ואמרו: אין אישות לגר.\u0004 על לשון זו תוהים: כיצד אפשר לומר כך? \u0003ואלא גר דקדיש\u0004 \u0005[שקידש]\u0006 אשה \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה\u0004 ה\u0003קדושין?! אלא\u0004 יש לתקן את הלשון \u0003אימא\u0004 \u0005[\u0006ו\u0005אמור]:\u0006 \u0003אין איסור אשת אח לגר. מאי לאו\u0004 \u0005[האם לא\u0006 מדובר\u0005]\u0006 \u0003דנסבא\u0004 \u0005[שנשאה]\u0006 ה\u0003אח\u0004 (שמת) את אשתו \u0003כשהוא גר!\u0004 ומשמע שאין באחים גרים מן האם איסורי אשת אח!","ודוחים: \u0003לא, דנסבא\u0004 \u0005[שנשאה]\u0006 \u0003כשהוא גוי.\u0004 ומקשים: אם מדובר שנשאה \u0003כשהוא גוי, מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר],\u0006 כלומר, מה החידוש בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליגזור\u0004 \u0005[שיגזרו]\u0006 חכמים במקרה שנשא האח אשה \u0003כשהוא גוי אטו\u0004 \u0005[משום]\u0006 המקרה הדומה אם ישא אותה \u0003כשהוא גר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה, ש\u0003אמר\u0004 החכם \u0003בן יאסיין: כשהלכתי לכרכי הים מצאתי גר אחד שנשא אשת אחיו מאמו. אמרתי לו: בני, מי הרשך? אמר לי: הרי אשה\u0004 שהותר לה הדבר לפני זמן רב מצויה כאן, היא \u0003ושבעה בניה\u0004, כש\u0003על ספסל זה ישב ר' עקיבא ואמר שני דברים: גר נושא אשת אחיו מאמו, ואמר\u0004 גם דבר אגדה: \u0003\"ויהי דבר ה' אל יונה שנית לאמר\"\u0004 (יונה ג, א) — \u0003שנית דברה עמו שכינה, שלישית לא דברה עמו שכינה\u0004 ולא זכה עוד לנבואה. \u0003קתני מיהת\u0004 \u0005[שנינו בכל אופן]\u0006 \u0003גר נושא אשת אחיו מאמו, מאי לאו דנסבא\u0004 \u0005[האם לא\u0006 מדובר \u0005שנשאה]\u0006 \u0003אחיו כשהוא גר?\u0004","ודוחים: \u0003לא, דנסבא\u0004 \u0005[שנשאה]\u0006 \u0003כשהוא גוי.\u0004 ושואלים: אם כן \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר]\u0006 בזה, מה חידש לנו? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003נגזור כשהוא גוי אטו\u0004 \u0005[משום]\u0006 המקרה שישא \u0003כשהוא גר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים.","לעצם המעשה הזה שואלים: \u0003ומי מהימן\u0004 \u0005[והאם נאמן]\u0006 האיש, אותו גר, שסיפר הלכה חדשה זו בשם ר' עקיבא, הלא הוא מספר על דבר הנוגע לעצמו, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא אמר רב הונא אמר רב: כל תלמיד חכם שמורה הלכה ובא, אם קודם מעשה\u0004 הנוגע לו עצמו \u0003אמרה — שומעין לו, ואם לאו\u0004 \u0005[לא],\u0006 שמורה הלכה זו רק בשעת מעשה כזה או לאחר מכן — \u0003אין שומעין לו!\u0004","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003מורה ובא היה,\u0004 שהיה מוסר הלכה זו עוד קודם שהגיע מעשה לידו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003משום דקאמר\u0004 \u0005[שאמר]\u0006 \u0003הרי אשה ושבעה בניה,\u0004 והרי זו עדות על מעשה שהיה זמן רב לפני שהתעוררה השאלה לגביו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003שאני הכא, דקאמר\u0004 \u0005[שונה כאן, שאמר]\u0006 \u0003מעשה אחרינא בהדה\u0004 \u0005[אחר אתו],\u0006 שכיון שאמר דבר אחר בשם ר' עקיבא שאותו אנו מקבלים, הרי אגב כך מקבלים גם הוראה זו.","אגב אותו ענין מביאים: \u0003אמר מר\u0004 \u0005[החכם],\u0006 נאמר: \u0003\"ויהי דבר ה' אל יונה שנית לאמר\",\u0004 ואמר על כך ר' עקיבא: \u0003שנית דברה עמו שכינה, שלישית לא דברה עמו.\u0004 ותוהים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 על ירבעם בן יואש: \u0003\"הוא השיב את גבול ישראל מלבוא חמת עד ים הערבה כדבר ה'\u0004 אלהי ישראל \u0003אשר דבר ביד עבדו יונה בן אמתי הנביא\"\u0004 (מלכים ב' יד, כה), משמע שניבא יונה עוד נבואה אחת לפחות!","\u0003אמר רבינא: על עסקי נינוה קאמר\u0004 \u0005[אמר]\u0006 שלא ניבא נבואה שלישית על נינוה, אף שאכן נתנבא עוד בנושאים אחרים. \u0003רב נחמן בר יצחק אמר: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הפסוק: \u0003\"כדבר ה' אשר דבר ביד עבדו הנביא\"\u0004 אינו תוכן הנבואה, אלא סימן הוא — \u0003כשם שנהפך\u0004 בנבואת יונה \u0003לנינוה מרעה לטובה, כך בימי ירבעם בן יואש נהפך להם לישראל מרעה לטובה.\u0004","וחוזרים לבעיה העיקרית, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003גר שהיה לידתו בקדושה והורתו שלא בקדושה — יש לו שאר האם,\u0004 שקרוביו מצד האם נחשבים כקרובים \u0003ואין לו שאר האב. כיצד? נשא אחותו מן האם\u0004 שנתגיירה יחד עם אמו — \u0003יוציא,\u0004 שאם כי בעצם אינה נחשבת כקרובתו בהיותה בעצמה גיורת, בכל זאת גזרו חכמים בה, שלא יבוא לשאת את אחותו מאמו שנולדה לאחר שנתגיירה אמו. נשא את אחותו \u0003מן האב — יקיים.\u0004 נשא \u0003אחות האב מן האם — יוציא,\u0004"],["\u0003מן האב — יקיים. אחות האם מן האם — יוציא,\u0004 אחות האם \u0003מן האב — ר' מאיר אומר: יוציא, וחכמים אומרים: יקיים. שהיה ר' מאיר אומר: כל ערוה שהיא משום שאר האם\u0004 — בין בקירבה של צד האב (כגון אחות האב) או מצד האם — \u0003יוציא, משום\u0004 שאר \u0003האב — יקיים.\u0004","\u0003ומותר באשת אחיו מאמו, ובאשת אחי אביו, ושאר כל העריות מותרות לו\u0004 כאשר נתגיירו. \u0003ו\u0004בא משפט זה \u0003לאיתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003אשת האב.\u0004","אם \u0003נשא אשה ובתה\u0004 בגויותן ולאחר מכן נתגיירו עמו — \u0003כונס אחת, ומוציא אחת, לכתחלה לא יכנוס. מתה אשתו — מותר בחמותו\u0004 אם נתגיירו שתיהן. \u0003ואיכא דתני\u0004 \u0005[ויש ששנה]:\u0006 \u0003אסור בחמותו.\u0004","\u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003מותר באשת אחיו, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003דנסבה\u0004 \u0005[שנשאה]\u0006 \u0003אחיו כשהוא גר?\u0004 ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דנסבה\u0004 \u0005[שנשאה]\u0006 \u0003כשהוא גוי.\u0004 ותוהים: אם כן \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר,\u0006 לחדש\u0005]\u0006 בכך? שודאי אין זה נחשב לערוה מכיון שאף לנישואין אין תוקף לאחר שנתגיירה. ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליגזור\u0004 \u0005[\u0006שיש \u0005לגזור]\u0006 בנשא \u0003כשהוא גוי אטו\u0004 \u0005[משום]\u0006 הנושא \u0003כשהוא גר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","כיון שהבאנו ברייתא זו לענייננו, מבררים אותה לעצמה: \u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003נשא אשה ובתה — כונס אחת ומוציא אחת, לכתחלה לא יכנוס.\u0004 ותוהים: \u0003השתא אפוקי מפיק\u0004 \u0005[\u0006הרי, \u0005עכשיו\u0006 למדנו ש\u0005מוציא\u0006 את זו שנשא\u0005]\u0006 — שלא ישאנה \u0003לכתחלה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006 ומשיבים: \u0003התם קאי\u0004 \u0005[שם,\u0006 התנא \u0005עומד,\u0006 מתייחס\u0005],\u0006 כלומר, מילים אלה מתייחסות למה שקדם להן, \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין: \u0003הך דאמור רבנן\u0004 \u0005[זה שאמרו חכמים]\u0006 \u0003יקיים,\u0004 שהם קרובים מן האב, בכל זאת \u0003לכתחלה לא יכנוס.\u0004","שנינו בברייתא: \u0003מתה אשתו — מותר בחמותו. ואיכא דתני\u0004 \u0005[ויש ששנה]:\u0006 \u0003אסור בחמותו.\u0004 ומעירים: \u0003חדא\u0004 \u0005[\u0006ברייתא \u0005אחת]\u0006 \u0003כ\u0004שיטת \u0003ר' ישמעאל, וחדא\u0004 \u0005[ואחת]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא.\u0004","\u0003מאן דאסר\u0004 \u0005[מי שאסר]\u0006 סבור \u0003כ\u0004דעת \u0003ר' ישמעאל,\u0004 שכיון ש\u0003אמר: חמותו לאחר מיתה\u0004 של אשתו \u0003באיסורא קיימא\u0004 \u0005[באיסור\u0006 תורה היא \u0005עומדת]\u0006 \u0003ו\u0004לכן גם ל\u0003גבי גר גזרו ביה רבנן\u0004 \u0005[בו חכמים],\u0006 \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר]\u0006 סבור \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר: חמותו לאחר מיתה\u0004 של אשתו \u0003קלש\u0004 (פחת) \u0003ליה איסורא\u0004 \u0005[לו האיסור],\u0006 ואין חייב עליה מיתה, \u0003ו\u0004לכן ל\u0003גבי גר לא גזרו ביה רבנן\u0004 \u0005[בו חכמים],\u0006 משום איסור שאף בישראל איננו חמור כל כך.","\u0003חמש נשים שנתערבו ולדותיהן\u0004 ואין יודעים מי הוא בנו של מי והיו לנשים אלה גם בנים אחרים, ידועים, ו\u0003הגדילו\u0004 (גדלו) אותם ילדי \u0003התערובות ונשאו נשים, ומתו\u0004 — \u0003ארבעה\u0004 מן האחים הוודאיים \u0003חולצין לאחת\u0004 מן הנשים הללו, שהרי ייתכן שהיא אשת אחיו של כל אחד מהם, \u0003ואחד\u0004 מן האחים הוודאיים \u0003מייבם אותה\u0004 אם רוצה, שאפילו אינה אשת אחיו, הרי חלצו לה האחרים ומותרת לו, שודאי הותרה לכול על ידי החליצה.","\u0003הוא,\u0004 זה שייבם \u0003ושלשה\u0004 אחרים \u0003חולצין לאחת\u0004 הנשים האחרות \u0003ואחד מייבם\u0004 אותה. וכך עושים לגבי כל הנשים הללו. \u0003נמצאו\u0004 בסך הכל \u0003ארבע חליצות וייבום לכל אחת ואחת.\u0004","מדייקים: \u0003ודוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ\u0006 תחילה \u0005ואחר כך לייבם],\u0006 \u0003אבל יבומי ברישא\u0004 \u0005[לייבם בתחילה] —\u0006 \u0003לא,\u0004 שהרי יש ספק שמא \u0003קפגע\u0004 \u0005[פוגע\u0006 \u0005הוא]\u0006 \u0003ביבמה לשוק.\u0004 שהרי ייתכן שזו שייבם תחילה לא אשת אחיו היתה, ושמא היא יבמתו של אחר, ועדיין לא נחלצה.","ועוד מסבירים: \u0003מאי\u0004 \u0005[מה\u0006 טעם נאמר במשנה\u0005]\u0006 \u0003הוא ושלשה חולצין לאחת,\u0004 ומדוע שלא יחלצו אחרים והוא מייבם עוד אחת? — ש\u0003לא תימא\u0004 \u0005[תאמר]\u0006 \u0003ליבמינהו חד לכולהו\u0004 \u0005[שייבם אחד את כולן],\u0006 שכיון שכל האחרים חלצו, רשאי הוא לייבם את כולן, \u0003אלא כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003מייבם חדא\u0004 \u0005[אחת],\u0006 \u0003דלמא מתרמיא ליה דידיה\u0004 \u0005[שמא תזדמן לו שלו],\u0006 שהרי ייתכן מקרה שכל אחד (או חלק מהם) ייבם את אשת אחיו, ואם ייבם אחד את כולם תתבטל ודאי מצות ייבום מחלק מהן.","שנינו בתוספתא בהמשך למקרה המתואר במשנה: \u0003מקצתן אחין ומקצתן שאין\u0004 (אינם) \u0003אחין — האחין חולצין, ושאין אחין מייבמין.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמרה]\u0006 ברייתא זו? \u0003אמר רב ספרא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבינה: \u0003מקצתן אחין מן האב\u0004 בלבד לאותם ולדות שנתערבו \u0003ומקצתן\u0004 מלבד היותם אחים מן האב הם גם \u0003אחין מן האם.\u0004 לחלק מן התערובות, \u0003אחין מן האם — חולצין,\u0004 שהרי אפילו אם אחת הנשים אינה אשת אח מן האב, מכל מקום שמא היא רק אשת אחיו מאמו, ואסור בה לעולם (שהרי אין מצות ייבום חלה עליה), \u0003ואחין מן האב מייבמין.\u0004","היו \u0003מקצתן כהנים ומקצתן שאינן כהנים — כהנים חולצין,\u0004 ו\u0003שאינן כהנים\u0004 — \u0003מייבמין,\u0004 שהרי חלוצה אסורה לכהן, ושמא היתה אחת החליצות חליצה ראויה ונאסרה לכהנים, ואין האח הכהן יכול לייבמה מפני הספק. \u0003מקצתן כהנים ומקצתן אחין מן האם — אלו ואלו חולצין ולא מייבמין.\u0004"],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש\u0004 מקרה שבו בן \u0003חולץ לאמו מספק,\u0004 או חולץ \u0003לאחותו מספק,\u0004 או חולץ \u0003לבתו מספק,\u0004 אף שבדרך כלל נשים אלה אינן חייבות כלל במצות ייבום.","\u0003כיצד? אמו ואשה אחרת, ולהן שני זכרים,\u0004 בן לכל אחת, \u0003וחזרו וילדו שני זכרים במחבא\u0004 ונתערבו שני הילדים זה בזה, \u0003ובא בנה\u0004 הוודאי \u0003של זו ונשא\u0004 את \u0003אמו של זה, ובנה\u0004 הוודאי \u0003של זו נשא\u0004 את \u0003אמו של זה, ומתו\u0004 אלו \u0003בלא בנים\u0004 — במקרה כזה, \u0003זה,\u0004 אחד מן התערובות, \u0003חולץ לשתיהן\u0004 שאינו יודע מי אמו ומי יבמתו, \u0003וזה חולץ לשתיהן. נמצא כל אחד ואחד\u0004 מהם \u0003חולץ לאמו מספק.\u0004","חולץ \u0003לאחותו מספק כיצד?\u0004 אדם שהיה נשוי לאשה ונולדו לו שני בנים ומתה אשתו ונשא אשה אחרת ונולד לו ממנה בן (ואותו בן הוא אחיהם מן האב של הראשונים) ומת האב ונישאה אשתו בשנית לאחר שהיה בעבר נשוי לאחרת והיו לו שני בנים ממנה, והלכה \u0003אמו\u0004 של אותו בן שלישי \u0003ואשה אחרת\u0004 ו\u0003ילדו שתי\u0004 בנות \u0003נקבות במחבא,\u0004 ונתערבו אותן הבנות זו בזו, \u0003ובאו אחיהן\u0004 מן האב של אותן בנות ו\u0003שלא מאותה האם ונשאום, ומתו\u0004 אותם אחים \u0003בלא בנים\u0004 — אותו בן ודאי, שהוא אח מהאם לאחת מהן, \u0003חולץ לשתיהן, נמצא חולץ לאחותו מספק.\u0004","חולץ \u0003לבתו מספק כיצד? אשתו ואשה אחרת שילדו שתי נקבות במחבא,\u0004 ונתערבו אותן הבנות, \u0003ובאו אחיהן\u0004 של הבעלים הללו \u0003ונשאום\u0004 את הבנות הללו \u0003ומתו בלא בנים,\u0004 במקרה כזה — \u0003זה חולץ לבתו מספק, וזה חולץ לבתו מספק.\u0004","אגב הדיון במקרים מוזרים אלה מביאים ברייתא העוסקת גם היא בצירוף מוזר, אם כי מסוג אחר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: איש ואשה פעמים שמולידין חמש אומות.\u0004 כלומר, ילדים שהם חמישה סוגים שונים מבחינת ייחוסם.","\u0003כיצד? ישראל שלקח\u0004 (קנה) \u0003עבד ושפחה מן השוק, ולהן\u0004 לעבד ולשפחה \u0003שני בנים, ונתגייר אחד מהן\u0004 מן הבנים הללו — \u0003נמצא\u0004 בן \u0003אחד גר ו\u0004בן \u0003אחד גוי. הטבילן\u0004 את העבד והשפחה \u0003לשם עבדות ונזקקו זה לזה\u0004 והולידו בן, \u0003הרי כאן\u0004 לזוג בן אחד \u0003גר, ו\u0004בן שני \u0003גוי, ו\u0004בן שלישי \u0003עבד. שחרר\u0004 האדון \u0003את השפחה\u0004 הזו \u0003ובא עליה העבד,\u0004 שהיה בעלה והוליד ממנה בן, \u0003הרי כאן גר וגוי ועבד וממזר,\u0004 שלדעתו בן שנולד מישראלית (ושפחה משוחררת דינה כישראלית לענין זה) ועבד — ממזר הוא. \u0003שחרר\u0004 האדון את \u0003שניהם, והשיאן זה לזה\u0004 והולידו בן — \u0003הרי כאן גר וגוי ועבד וממזר וישראל.\u0004","שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 דבר חידוש בכל הסיפור הזה — ש\u0003גוי ועבד הבא על בת ישראל הולד ממזר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש מוכר את אביו\u0004 כדי \u0003להגבות\u0004 ל\u0003אמו\u0004 את \u0003כתובתה. כיצד? ישראל לקח עבד ושפחה מן השוק ולהם בן. ושחרר את השפחה ונשאה, ועמד וכתב כל נכסיו לבנה\u0004 ובתוכם גם את אביו העבד, ואחר כך מת האדון, \u0003נמצא זה\u0004 הבן שירש כל הנכסים \u0003מוכר את אביו\u0004 העבד שזכה בו כדי \u0003להגבות לאמו כתובתה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 חידוש הלכה \u0005השמיע לנו]\u0006 בכך? ומשיבים: כל הברייתא \u0003כולה\u0004 כשיטת \u0003ר' מאיר היא, ו\u0004בא להשמיע לנו ש\u0003עבדא מטלטלי\u0004 \u0005[העבד\u0006 נחשב כמו \u0005מטלטלים],\u0006 \u0003ומטלטלי משתעבדי\u0004 \u0005[ומטלטלים משתעבדים]\u0006 \u0003לכתובה.\u0004 וזהו החידוש: שאף מטלטלים משתעבדים לכתובה, ולא רק קרקעות, ולכן אפשר למכור את העבד לצורך הכתובה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא קמשמע לן\u0004 \u0005[זה השמיע לנו]\u0006 ש\u0003עבדא כמקרקע דמי\u0004 \u0005[העבד כמקרקעין נחשב]\u0006 ולכן הוא נמכר כשאר הקרקעות לצורך גביית הכתובה.","\u0003האשה שנתערב ולדה בולד כלתה, הגדילו התערובות ונשאו נשים, ומתו\u0004 אחר כך, \u0003בני הכלה\u0004 הוודאיים \u0003חולצין ולא מייבמין\u0004 לנשים הללו, \u0003ש\u0004כן כל אחת מהן \u0003הוא ספק\u0004 שהיא \u0003אשת אחיו, ספק\u0004 שהיא \u0003אשת אחי אביו\u0004 ואסורה בייבום,","\u0003בני הזקנה,\u0004 כלומר, בני האם הוודאיים, \u0003או חולצין או מייבמין, ש\u0004כן יש פה \u0003ספק,\u0004 או שהיא \u0003אשת אחיו\u0004 או \u0003אשת בן אחיו\u0004 ושתיהן מותרות.","\u0003מתו\u0004 האחים \u0003הכשרים\u0004 (הוודאיים), אותם ילדי \u0003התערובות\u0004 לנשים שנותרו \u0003לבני הזקנה — חולצין ולא מייבמין, ש\u0004כן \u0003הוא ספק אשת אחיו ו\u0004ספק \u0003אשת אחי אביו. לבני הכלה — אחד חולץ,\u0004 כי שמא אשת אחיו היא וצריכה חליצה ממנו \u0003ואחד מייבם,\u0004 שאפילו אם היא אשת אחיו של הספק השני, הרי כבר קיבלה חליצה ממנו ומותרת לאחד הזה.","\u0003כהנת שנתערב ולדה בולד שפחתה — הרי אלו,\u0004 הוולדות, \u0003אוכלים בתרומה\u0004 בכל מקרה, שכן אם עבד הוא — הרי הוא עבד כהן, ואם בן הכהנת הוא — הרי הוא כהן, \u0003וחולקין חלק אחד בגורן,\u0004"],["\u0003ואינן מטמאין למתים,\u0004 שכל אחד מהם הוא ספק כהן. \u0003ואינן נושאין נשים, בין\u0004 היו הנשים \u0003כשרות\u0004 — שמא הוא עבד ואסור בכשרה, \u0003בין פסולות\u0004 — שמא כהן הוא ואסורה לו. \u0003הגדילו התערובות ושחררו זה את זה — נושאין נשים ראויות לכהונה,\u0004 שאם עבד משוחרר הוא — מותר בה, שאמנם עבד משוחרר מותר אף בפסולה לכהונה, אבל אם הוא כהן — אסור באשה פסולה לכהונה.","\u0003ואינן מטמאין למתים,\u0004 משום ספק כהן, \u0003ואם נטמאו\u0004 למתים — \u0003אינן סופגין\u0004 (מקבלים) את \u0003הארבעים\u0004 מלקות שהרי אין להזהיר אף אחד מהם בוודאות, שמא אינו כהן. \u0003ואינן אוכלין בתרומה,\u0004 שהרי אחד מהם הוא עבד משוחרר, \u0003ואם אכלו\u0004 בשוגג — \u0003אינן משלמין קרן וחומש,\u0004 שהרי לא ברור שהאוכל הוא זר. \u0003ואינן חולקין על הגורן\u0004 לקבל תרומה, שאין אחד מהם יכול להוכיח שכהן הוא. \u0003ומוכרין את התרומה\u0004 שהם מפרישים מתבואתם, \u0003ו\u0004אף שאינם אוכלים אותה \u0003הדמים שלהן\u0004 שאין דרך להוציא מידם.","\u0003ואינן חולקין בקדשי המקדש,\u0004 שהרי לא ברור מי מהם כהן, \u0003ואין נותנים להם קדשים,\u0004 קרבנות להקריב כמו שנותנים לכהנים. \u0003ואין מוציאין\u0004 קדשים \u0003שלהם מידיהם\u0004 — שעורות הקדשים שייכים להם, שהרי אי אפשר להוכיח כי אחד מהם אינו כהן.","\u0003ופטורין\u0004 לתת לכהן \u0003מן הזרוע ומן הלחיים ומן הקיבה\u0004 של בהמות חולין שלהם, \u0003ובכורו\u0004 (בכור בהמה טהורה) של כל אחד מהם \u0003יהא רועה עד שיסתאב\u0004 (עד שיפול בו מום) שבהיותו תמים אינו רוצה להקריבו ולתת את בשרו לכהן — שהרי בעל הבכור ספק כהן הוא. וכשנופל בו מום יכולים הם לאוכלו, שהרי הוא ממון של כהן בלבד, ואין מוציאים מידם. \u0003ו\u0004בכלל: \u0003נותנין עליו חומרי כהנים וחומרי ישראלים.\u0004","שנינו במשנה: \u0003\"מתו הכשרים וכו'\".\u0004 ותוהים על הלשון: \u0003אלא הנך\u0004 \u0005[הללו],\u0006 וכי \u0003משום דאיערוב להו\u0004 \u0005[שהתערבו להם]\u0006 \u0003הוו להו\u0004 \u0005[נהיו]\u0006 \u0003פסולין?\u0004 אמנם, ספק הוא בני מי הם, אבל אינם פסולים! \u0003אמר רב פפא: אימא\u0004 \u0005[אמור]\u0006 כך: \u0003ומתו הודאין.\u0004","עוד שנינו במשנה: \u0003לבני הכלה אחד חולץ\u0004 ואחד מייבם. ומעירים: \u0003דוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ\u0006 תחילה \u0005ואחר כך לייבם],\u0006 \u0003אבל יבומי ברישא\u0004 \u0005[לייבם בתחילה] —\u0006 \u0003לא,\u0004 מחשש \u0003דקפגע\u0004 \u0005[שפוגע הוא]\u0006 \u0003ביבמה לשוק,\u0004 שהרי ייתכן שזו איננה יבמתו אלא כלת אחיו הזקוקה לייבום.","שנינו במשנה: \u0003כהנת שנתערב\u0004 וולדה בוולד שפחתה, שבין השאר גם חולקים להם חלק אחד בגורן. ותוהים: \u0003חלק אחד פשיטא\u0004 \u0005[פשוט]\u0006 שלא יתנו להם יותר מזה! אלא \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003חלק כאחד,\u0004 כלומר, חולקים להם רק כשהם באים יחד.","ומעירים: \u0003תנן כמאן דאמר\u0004 \u0005[שנינו\u0006 איפוא במשנתנו \u0005כ\u0006דעת \u0005מי שאומר]\u0006 \u0003אין חולקין תרומה לעבד אלא אם כן רבו עמו. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין חולקין תרומה ל\u0004מי שהוא ספק \u0003עבד\u0004 כהן ספק בן כהן, \u0003אלא אם כן רבו עמו,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: יכול\u0004 זה שבא לחלוק \u0003שיאמר: אם כהן אני — תנו לי בשביל עצמי, ואם עבד כהן אני — תנו לי בשביל רבי\u0004 (אדוני).","ומסבירים את טעם המחלוקת: \u0003במקומו של ר' יהודה היו מעלין מתרומה ליוחסין,\u0004 שאם היו רואים שאדם קיבל חלק בתרומה, היו מניחים שהוא כהן, ומעידים עליו שהוא כהן לגבי קביעת ייחוסו, ולכן אין לתת תרומה לעבד כשרבו אינו עמו. \u0003במקומו של ר' יוסי לא היו מעלין מתרומה ליוחסין,\u0004 ולכן אפשר היה לתת תרומה גם אם הוא עבדו של כהן בלא חשש.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר צדוק: מימי לא העדתי,\u0004 לא נזדמן לי להעיד בבית דין, \u0003אלא עדות אחד, והעלו עבד לכהונה על פי\u0004 באותה עדות, אף שמן הסתם דקדק בדבר, מכל מקום קרה מכשול כזה.","ותוהים: \u0003העלו\u0004 ממש \u0003סלקא דעתך\u0004 \u0005[עולה בדעתך]?!\u0006 \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 מקובל עלינו ככלל שאפילו \u0003בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידן, צדיקים עצמן לא כל שכן!\u0004","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 בשינוי: \u0003בקשו להעלות עבד לכהונה על פי.\u0004 כיצד היה הדבר? \u0003חזא באתריה\u0004 \u0005[ראה במקומו]\u0006 של \u0003ר' יוסי\u0004 שחלקו בתרומה לאדם אחד ושם לא דקדקו אם עבד כהן הוא — או שהוא עצמו כהן, \u0003ואזל ואסהיד באתריה\u0004 \u0005[והלך והעיד במקומו]\u0006 של \u0003ר' יהודה\u0004 שראה שחלקו לו תרומה, וכיון ששם לא חילקו בתרומה אלא לכהן, ולכן כמעט שהעלו אותו עבד לכהונה על סמך עדות זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשרה אין חולקין להם תרומה בבית הגרנות, ואלו הן: חרש, שוטה, וקטן, טומטום, ואנדרוגינוס, והעבד, והאשה, והערל, והטמא, ונושא אשה שאינה הוגנת לו\u0004 (כלומר, אשה פסולה לכהונה), \u0003וכולן משגרין\u0004 (שולחים) \u0003להם\u0004 תרומה \u0003לבתיהם, חוץ מ\u0004ל\u0003טמא ו\u0004ל\u0003נושא אשה שאינה הוגנת לו.\u0004","ומבררים את הברייתא: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003חרש שוטה וקטן\u0004 אין חולקים להם — כי \u0003לאו בני דיעה נינהו\u0004 \u0005[לא בני דעת הם]\u0006 והרי זה פחיתות־כבוד לתרומה שיתנוה להם ברבים. \u0003טומטום ואנדרוגינוס נמי\u0004 \u0005[גם כן]\u0006 —"],["\u0003בריה בפני עצמה נינהו\u0004 \u0005[הם]\u0006 וזילזול הוא בקדשים שיינתנו לאנשים מוזרים שכאלה. \u0003עבד נמי\u0004 \u0005[גם כן] —\u0006 \u0003דלמא אתי לאסוקי\u0004 \u0005[שמא יבואו להעלותו]\u0006 \u0003מתרומה ליוחסין. ערל וטמא — משום דמאיסי\u0004 \u0005[ש\u0006הם \u0005מאוסים]\u0006 שיש משום מאיסות בפסולים אלה, ואין זה נאה לתת להם קדשים בפרהסיא. \u0003נושא אשה שאינה הוגנת לו\u0004 הטעם הוא — \u0003משום קנסא\u0004 \u0005[קנס]\u0006 שקנסוהו שלא ייהנה מזכויות כהונה כל עוד הוא עובר עבירה. \u0003אלא אשה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יחלקו לה?","\u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משום גרושה\u0004 שאם היתה בת ישראל הנשואה לכהן, שמא תתגרש אותה אשה וימשיכו לתת לה, אף כשהיא זרה עכשיו, ולכן אין נותנים לאשה בעצמה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: משום\u0004 חשש \u0003יחוד,\u0004 שאם תבוא אשה לגורן, עלולה היא להימצא ביחידות עם גבר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה? ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי \u0003בי דרי דמקרב למתא ולא שכיחי בהו אינשי\u0004 \u0005[בית הגרנות שקרוב לעיר אבל אין מצויים בו אנשים],\u0006 שכיון שהוא קרוב לעיר, יודעים אם גרושה היא, אבל כיון שאין אנשים מצויים שם יש חשש ייחוד. \u0003אי נמי דמרחק ושכיחי בה אינשי\u0004 \u0005[או גם כן\u0006 בגורן \u0005ש\u0006היא \u0005מרוחקת ומצויים בה אנשים]\u0006 שבמקום כזה יש חשש גרושה, ואין חשש ייחוד.","שנינו בברייתא: \u0003וכולן משגרין\u0004 (שולחים) \u0003להם\u0004 תרומה \u0003לבתיהן, חוץ מ\u0004ל\u0003טמא ו\u0004ל\u0003נושא אשה שאינה הוגנת לו.\u0004 ומעירים: \u0003אבל ערל משגרינן ליה\u0004 \u0005[שולחים לו],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, במה הוא שונה מטמא?","— \u0003משום דאניס\u0004 \u0005[ש\u0006הוא \u0005אנוס].\u0006 ותוהים: \u0003טמא נמי\u0004 \u0005[גם כן]\u0006 \u0003הא אניס\u0004 \u0005[הרי אנוס\u0006 הוא\u0005]\u0006 ומדוע אין משגרים לו? ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 הערל \u0003נפיש אונסיה\u0004 \u0005[אונסו מרובה],\u0006 שהרי הוא נשאר ערל בגלל הסכנה שיש לחייו אם נמול, \u0003והאי\u0004 \u0005[וזה]\u0006 הטמא \u0003לא נפיש אונסיה\u0004 \u0005[אין אונסו מרובה],\u0006 שיכול אדם להיזהר מן הטומאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003העבד והאשה אין חולקים להם תרומה בבית הגרנות. ובמקום שחולקין\u0004 להם — \u0003נותנין לאשה תחלה ופוטרין אותה מיד.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 שכיון שאמר תחילה שאין חולקים להם, איך זה אמר אחר כך \"במקום שחולקים\"!","ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 לא לענין תרומה אלא \u0003במקום שחולקין מעשר עני\u0004 בזמנים שמחלקים אותו לעניים בבית הנותן — \u0003נותנין לאשה תחלה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003משום זילותא\u0004 \u0005[זילזול],\u0006 שלא תזדלזל האשה אם תימצא שוהה זמן מרובה בין הבריות.","\u0003אמר רבא: מרישא, כי הוו אתו גברא ואתתא לדינא קמאי\u0004 \u0005[מתחילה, כאשר היו באים איש ואשה לדין לפני],\u0006 בשני דינים נפרדים, \u0003הוה שרינא תיגרא דגברא ברישא\u0004 \u0005[הייתי מתיר,\u0006 פותר, את \u0005הסכסוך של הגבר בתחילה],\u0006 והטעם — \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003דמיחייב\u0004 \u0005[ש\u0006הוא \u0005מחויב]\u0006 \u0003במצות,\u0004 ולא אשהה אותו לבטל זמנו בהמתנה. \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי\u0006 את הברייתא \u0005הזו],\u0006 \u0003שרינא תיגרא דאתתא ברישא\u0004 \u0005[\u0006הייתי \u0005מתיר,\u0006 פותר, \u0005הסכסוך של האשה בתחילה].\u0006 \u0003ומאי טעמא\u0004 \u0005[ומה טעם]?\u0006 \u0003משום זילותא\u0004 \u0005[זלזול],\u0006 שלא תזדלזל בהמתנה.","שנינו במשנה שאם \u0003הגדילו התערובות\u0004 ושיחררו זה את זה \u0003וכו'.\u0004 ומדייקים: \u0003שיחררו,\u0004 משמע בדיעבד אם שיחררו — כך הוא הדין. ומשמע: \u0003אי בעי\u0004 \u0005[אם רוצים] —\u0006 \u0003אין\u0004 \u0005[כן]\u0006 משחררים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעי\u0004 \u0005[רוצים] —\u0006 \u0003לא, ואמאי\u0004 \u0005[ומדוע]\u0006 לא יכריחו אותם לשחרר? והלא כל אחד מהם \u0003לישא שפחה אינו יכול\u0004 שמא כהן הוא, ולישא \u0003בת חורין אינו יכול\u0004 שמא עבד הוא, ונמצא בטל ממצות פריה ורביה! \u0003אמר רבא: אימא\u0004 \u0005[אמור]\u0006 שכוונת המשנה לומר: \u0003כופין אותן, ומשחררין זה את זה.\u0004","שנינו במשנה כי \u0003נותנין עליהן חומרי\u0004 כהנים וחומרי ישראל. ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה\u0006 נוספת נאמר כלל זה\u0005]\u0006 שהרי לכאורה מנינו את כל פרטי הדינים! ומשיבים: \u0003אמר רב פפא: למנחתם,\u0004 לענין קרבן מנחה שהם מביאים, שהיא \u0003נקמצת כמנחת ישראל\u0004 שכן מחמירים שמנחתם תיקמץ, שלא כמנחת כהנים שאינה נקמצת וכולה נשרפת, \u0003ו\u0004מצד שני מנחתם \u0003אינה נאכלת — כמנחת כהנים. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 עושים? \u0003הקומץ קרב\u0004 ונשרף \u0003בעצמו, והשירים קריבין בעצמן.\u0004","ומקשים: איך אפשר לעשות כך? \u0003איקרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 את ההלכה הנובעת מן המקרא: \u0003כל\u0004 דבר \u0003ש\u0004חלק \u0003ממנו\u0004 קרב \u0003לאישים\u0004 (שעולה למזבח, כגון קומץ המנחה) \u0003הרי הוא ב\"בל תקטירו\".\u0004 שכל קרבן שמקריבים חלק ממנו כגון דם או קומץ למזבח — אסור להקטיר את השאר, ואיך, בענייננו, מקטירים את שיירי המנחה!","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: דמסיק להו\u0004 \u0005[שמעלה אותם]\u0006 את השיירים \u0003לשום\u0004 (לשם) \u0003עצים,\u0004 כלומר, לא בתורת קרבן אלא כחומר דלק סתם, ו\u0003כ\u0004שיטת \u0003ר' אלעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: \"לריח ניחוח\" אי אתה מעלה\u0004 שיירי מנחה, \u0003אבל אתה מעלה לשום עצים.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' אלעזר. אלא לרבנן מאי איכא למימר\u0004 \u0005[ל\u0006דעת \u0005חכמים מה יש לומר]\u0006 כיצד עושים? ומשיבים: \u0003דעביד לה\u0004 \u0005[שעושה בזה]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר בר' שמעון אומר: הקומץ קרב לעצמו, והשירים\u0004 אינם נקטרים אלא \u0003מתפזרין על בית הדשן\u0004 עם האפר. \u0003ו\u0004מעירים: \u0003אפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא פליגי עליה\u0004 \u0005[חלקו עליו]\u0006 על \u0003ר' אלעזר בר' שמעון\u0004 ואמרו שהשיריים קרבים \u0003אלא במנחת חוטא של כהנים,\u0004 ש\u0003בת הקרבה היא,\u0004 שהיא עשויה שיקריבו אותה, והשאלה היתה אם יש להקטיר את הנשאר או לא, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במקרה שלנו, אין ספק בדבר, שאין דרך אחרת לעשות, שאי אפשר להקטיר שמא הוא ישראל, \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שהשיריים מתפזרים.","\u0003מי שלא שהתה אחר\u0004 פרידתה מ\u0003בעלה שלשה חדשים, ונשאת, וילדה\u0004 ילד, \u0003ואין ידוע אם\u0004 הוא \u0003בן תשעה\u0004 חודשים מהריונה \u0003ל\u0004בעלה ה\u0003ראשון, אם בן שבעה לאחרון,\u0004 ו\u0003היו לה בנים\u0004 ודאיים \u0003מן הראשון, ובנים\u0004 ודאיים \u0003מן השני.\u0004 אם נשא אותו ספק אשה ומת בלא בנים, האחים, בין מן הבעל הראשון ובין מן השני, \u0003חולצין\u0004 לה, שהרי הוא ספק אחיהם מן האב, \u0003ולא מייבמין\u0004 שמא הוא רק אחיהם מן האם, ואשתו אסורה משום ערוה. \u0003וכן הוא להם,\u0004 אם מת אחד מהם — \u0003חולץ ולא מייבם.\u0004"],["\u0003היו לו אחים מן הראשון ואחים מן השני, שלא מאותה האם\u0004 אלא מאב אחד — \u0003הוא חולץ\u0004 או \u0003מייבם\u0004 לנשותיהם, שאם אחיו מן האב הוא — הריהו יבם, ואם לאו — הרי היא כאשת אדם זר ומותר לו לישא אותה. \u0003והם\u0004 לגבי אשתו — \u0003אחד חולץ ואחד מייבם.\u0004","\u0003היה אחד\u0004 מן הבעלים שכל אחד מהם ספק אביו \u0003ישראל ואחד כהן — נושא אשה ראויה לכהן\u0004 בלבד, שמא כהן הוא, \u0003ואין מטמא למתים\u0004 שמא כהן הוא. \u0003ואם נטמא — אינו סופג את הארבעים\u0004 — שמא ישראל הוא. \u0003אינו אוכל בתרומה\u0004 שמא הוא ישראל, \u0003ואם אכל — אינו משלם קרן וחומש\u0004 כזר שאכל תרומה, שמא הוא כהן. \u0003ואינו חולק על הגורן\u0004 לקבל תרומה, שמא הוא ישראל. \u0003ומוכר התרומה,\u0004 שהוא מפריש מתרומתו \u0003ו\u0004אף שאינו אוכל אותה — \u0003הדמים שלו,\u0004 שהרי יתכן שהוא כהן ואי אפשר להוציא ממנו מספק כסף שהוא מוחזק בו.","\u0003ואינו חולק בקדשי הקדשים,\u0004 שהרי לא ברור אם הוא כהן, \u0003ואין נותנין לו\u0004 להקריב את \u0003את הקדשים, ואין מוציאין את שלו מידו,\u0004 שעורות הקדשים ושאר חלקי הקרבן הניתנים כמתנה לכהן, כשהקרבן שלו — אין מוציאים אותם מידו. \u0003ופטור מן הזרוע והלחיים והקיבה\u0004 שכל ישראל נותן מבהמות החולין לכהן. \u0003ובכורו\u0004 (בכור בהמה טהורה) \u0003יהא רועה עד שיסתאב\u0004 (שיפול בו מום) ודמיו יהיו לו. \u0003ונותנין עליו חומרי כהנים וחומרי ישראלים.\u0004","\u0003היו שניהם\u0004 (שני הבעלים, שכל אחד מהם הוא ספק אביו) \u0003כהנים — הוא אונן עליהם\u0004 כשמתו, שמא אחד מהם הוא אביו, \u0003והם אוננים עליו,\u0004 שמא הוא בנו של אחד מהם. \u0003הוא אינו מטמא להם\u0004 — שהרי אחד מהם אינו קרובו, \u0003והם אינן מטמאים לו\u0004 — שמא אינם קרוביו, \u0003הוא אינו יורש אותן,\u0004 שיורשיו הוודאים של כל אחד מהם דוחים אותו, \u0003אבל הם יורשין אותו\u0004 אם לא היו לו בנים, ומחלקים את ממונו ביניהם.","\u0003ופטור על מכתו ועל קללתו של זה ושל זה.\u0004 שאף שמכה ומקלל אביו ואמו חייב מיתה, כיון שלא ברור מי הוא אביו, אי אפשר לדון אותו. ולענין זמן עבודתו במקדש, \u0003עולה במשמרו של זה ושל זה,\u0004 שהרי ספק הוא, ושמא הוא שייך לכל אחד מהמשמרות הללו וחייב לעבוד עמהם, \u0003ואינו חולק\u0004 עמהם בקרבנות הנאכלים, שכן בני כל משמר דוחים אותו למשמר האחר. \u0003אם היו שניהם,\u0004 שני האנשים שכל אחד מהם הוא ספק אביו \u0003במשמר אחד — נוטל חלק אחד,\u0004 שהרי מכל מקום שייך הוא למשמר זה.","ומעירים: \u0003דוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ ואחר כך לייבם],\u0006 \u0003אבל יבומי ברישא\u0004 \u0005[לייבם בתחילה] —\u0006 \u0003לא,\u0004 משום \u0003דקא פגע\u0004 \u0005[ש\u0006הוא \u0005פוגע]\u0006 \u0003ביבמה לשוק,\u0004 שהרי ייתכן שהיה הספק בן של השני, והיא יבמה של אחיו מהשני, וליבמה הזו לא חלצו.","\u0003אמר שמואל:\u0004 היו \u0003עשרה כהנים עומדים\u0004 במקום אחד, \u0003ופירש אחד מהם\u0004 ואין יודעים מי הוא, \u0003ובעל\u0004 אשה, ונולד ילד — \u0003הולד שתוקי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שתוקי\"\u0004 לענין זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שמשתקים אותו מ\u0004תביעה על חלק ב\u0003נכסי אביו\u0004 ואין נותנים לו חלק בנכסים — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא! \u0003מי ידעינן אבוה מנו\u0004 \u0005[האם יודעים אנו אביו מי הוא]?\u0006 \u0003אלא שמשתקין אותו\u0004 גם \u0003מדין כהונה,\u0004 ואין נוהגים בו ככהן גמור, אף שבוודאי אחד מן הכהנים הוא אביו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיתה לו ולזרעו אחריו\u0004 ברית כהונת עולם\u0003\"\u0004 (במדבר כה, יג) — \"אחריו\" בא ללמד כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003זרעו מיוחס אחריו, וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אין ידוע למי הוא מתייחס.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: אלא מעתה גבי\u0004 (אצל) \u0003אברהם, דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 אותו ביטוי: \u0003\"להיות לך לאלהים ולזרעך אחריך\"\u0004 (בראשית יז, ז), \u0003התם מאי קא מזהר ליה רחמנא\u0004 \u0005[שם מה מזהירה אותו התורה],\u0006 האם הכוונה שמי שאינו מיוחס איננו חייב בעבודת ה' כישראלי? ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לא תנסב\u0004 \u0005[תישא]\u0006 \u0003גויה ושפחה,\u0004 ש\u0003לא ליזיל\u0004 \u0005[ילך,\u0006 יתייחס\u0005]\u0006 \u0003זרעך בתרה\u0004 \u0005[אחריה]\u0006 ויעזוב את עבודת ה'.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי שמואל: שנינו בברייתא שכהן שייבם את אשת אחיו ונולד בן, ואין יודעים אם הוא בנו של הראשון שמת או של היבם — הבן ה\u0003ראשון\u0004 שנולד מייבום זה \u0003ראוי להיות\u0004 אפילו \u0003כהן גדול!\u0004 ומקשים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה \u0003זרעו מיוחס אחריו וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 שהרי אין ידוע של מי הבן! ומשיבים: \u0003\"זרעו מיוחס אחריו\"\u0004 הוא רק תקנה \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 שהבאנו רק \u0005סמך בלבד]\u0006 הוא, ולא מקור הלכתי אמיתי, \u0003וכי גזור רבנן\u0004 \u0005[וכאשר גזרו חכמים]\u0006 שלא לייחס ככהן מי שאינו יודע בוודאות מי אביו — הרי זה \u0003בזנות,\u0004 ואילו \u0003בנשואין\u0004 כאשר האשה נישאה כדין \u0003לא גזור רבנן\u0004 \u0005[גזרו חכמים].\u0006","ושואלים: \u0003ובזנות מי גזור רבנן\u0004 \u0005[האם גזרו חכמים]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 את דין הנולד מ\u0003מי שלא שהתה אחר בעלה שלשה חדשים ונשאת וילדה.\u0004","ונברר \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אחר בעלה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אחר מיתת בעלה — אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003הוא אונן עליהם\u0004 על ספק אבותיו \u0003והם אוננים עליו. בשלמא\u0004 \u0005[נניח]\u0006 \u0003הוא אונן עליהם — משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא זאת]\u0006 אפילו \u0003בנשואין\u0004 שלה ל\u0003שנית,\u0004 כלומר, ספק־אביו מן הנישואין השניים של אמו מת, והוא אונן עליו מספק, \u0003ו\u0004לגבי הראשון שמת לפני שנולד הבן — מדובר ב\u0003ליקוט עצמות דקמא\u0004 \u0005[של הראשון],\u0006 שכאשר מלקטים עצמותיו של אדם לאחר שנקבר, כדי להעביר אותו למקום קבורת המשפחה — מתאבלים עליו שנית. \u0003אלא הם אוננים עליו היכי משכחת לה\u0004 \u0005[איך אתה\u0006 יכול \u0005למצוא זאת]?\u0006 \u0003קמא הא מית ליה\u0004 \u0005[הראשון הרי מת לו]!\u0006","\u0003ואלא\u0004 חייב אתה לומר שמדובר \u0003בגרושה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003אחר בעלה — אחר גט בעלה.\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003הוא אין מטמא להם והם אינן מטמאין לו. בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003הן אין מטמאין לו — לחומרא\u0004 \u0005[להחמיר]\u0006 ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהם ספק \u0003דלמא לאו בריה\u0004 \u0005[שמא לא בנו]\u0006 \u0003הוא, אלא הוא אין מטמא להם אמאי\u0004 \u0005[מדוע]?\u0006","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לשני לא ליטמי ליה\u0004 \u0005[אינו נטמא לו]\u0006 שהרי לא ברור שהוא בנו, ולכן אסור לו להיטמא לו, \u0003אלא לראשון ליטמי ליה\u0004 \u0005[שייטמא לו]\u0006 \u0003ממה נפשך,\u0004 כיצד? — \u0003אי בריה\u0004 \u0005[אם בנו]\u0006 \u0003הוא שפיר קא מטמא ליה\u0004 \u0005[יפה,\u0006 ראוי, שהוא \u0005מיטמא לו]\u0006 שהרי הבן, אף שהוא כהן, מיטמא לאביו, \u0003ואי בר בתרא\u0004 \u0005[ואם\u0006 ה\u0005בן\u0006 של \u0005האחרון]\u0006 \u0003הוא שפיר קא\u0004 \u0005[יפה הוא]\u0006 \u0003מטמא ליה\u0004 \u0005[לו]\u0006 שהרי \u0003חלל הוא.\u0004 שאם היתה אמו גרושה מבעלה, נמצא שהבעל הוא כהן שנשא גרושה, ובן כהן מגרושה — חלל הוא, ואין עליו קדושת כהונה.","\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר כאן שלא נישאה כלל אלא שנבעלה \u0003בזנות\u0004 בהיותה פנויה, גם לראשון וגם לשני. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אחר בעלה\"\u0004 — לא בעלה ממש, אלא \u0003אחר בועלה.\u0004 שכיון שלא היה הפסק בין בועל ראשון לשני, איננה יודעת ממי הילד. \u0003וקתני סיפא\u0004 \u0005[ושנינו\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003עולה במשמר של זה ושל זה.\u0004 משמע שיש לו דין כהן לכל דבר, למרות שנולד מזנות ולא ברור מי אביו, \u0003ו\u0004הרי זו \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 על דברי \u0003שמואל!\u0004","\u0003אמר רב שמעיא:\u0004 מדובר פה \u0003בממאנת.\u0004 כלומר, קטנה שהיתה יתומה מאב והשיאוה אחיה, ולפני שבגרה מיאנה בבעלה, וכיון שהמיאון מבטל את הנישואין מעיקרם — רשאית היא להינשא גם לכהן אחר, אלא שלא שהתה אחר המיאון בבעלה הראשון שלושה חדשים, ולכן איננה יודעת למי הילד.","ושואלים: \u0003ממאנת מי קא ילדה\u0004 \u0005[האם\u0006 היא \u0005יולדת]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן: שלש נשים משמשות במוך\u0004 כדי שלא תתעברנה: \u0003קטנה, מעוברת, ומניקה. קטנה — שמא תתעבר ותמות,\u0004 שכיון שקטנה היא עלולה הלידה לסכן אותה, \u0003מעוברת — שמא\u0004 תתעבר שנית ו\u0003תעשה עוברה\u0004 הקודם \u0003סנדל,\u0004 שיתמעך כתוצאה מהעובר השני, \u0003מניקה — שמא תגמול את בנה\u0004 בזמן ההריון וייפסק חלבה \u0003וימות\u0004 הבן ברעב. \u0003ואיזו היא קטנה — מבת אחת עשרה שנה ויום אחד עד בת שתים עשרה שנה ויום אחד. פחות מיכן או יתר על כן — משמשת כדרכה והולכת,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אחת זו ואחת זו משמשת כדרכה והולכת, ומן השמים ירחמו\u0004 שלא תתעבר. \u0003שנאמר: \"שומר פתאים ה'\"\u0004 (תהלים קטז, ו), ואם כן לא ייתכן שממאנת, שלפי הגדרתה היא פחות מבת שתים עשרה שנה, תהיה מעוברת ולא תמות!","ומשיבים: \u0003משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא זאת]\u0006 \u0003בקידושי טעות,\u0004 כגון שקידש אותה הראשון קידושין על תנאי, והתבטל התנאי, ונמצאו נישואיה הראשונים בטלים לגמרי, ובמקרה כזה רשאית להינשא לכהן. ואם לא המתינה שלושה חדשים אחר בעלה הראשון נוצר ספק של מי הילד, \u0003וכ\u0004דברי \u0003רב יהודה אמר שמואל.\u0004 ש\u0003אמר רב יהודה אמר שמואל משום\u0004 (משמו של) \u0003ר' ישמעאל,\u0004 נאמר בסוטה: \u0003\"והיא לא נתפשה\"\u0004 (במדבר ה, יג), כלומר, הסוטה היא זו שלא נתפסה (נאנסה), והיא \u0003אסורה\u0004 לבעלה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נתפשה\u0004 (נאנסה) — \u0003מותרת\u0004 לבעלה.","\u0003ו\u0004ההדגשה בלשון \"היא\" באה לומר כי \u0003יש לך אחרת, שאף על פי שלא נתפשה\u0004 אלא נבעלה מרצון, \u0003מותרת,\u0004 כיון שביאתה נחשבת כאונס. \u0003ואי זו — זו שקדושיה קידושי טעות, שאפילו בנה מורכב לה על כתפה ממאנת\u0004 בבעלה \u0003והולכת לה.\u0004 ואם זנתה בהיותה נשואה — אינה נאסרת והרי היא כפנויה ומותרת לו, ואם כן אפשר להסביר את המשנה במקרה זה בלי שתהא בה סתירה לדברי שמואל."],["שנינו במשנה: \u0003היו שניהם כהנים וכו'\u0004 ובהמשך המשנה נאמר שאם הבן־הספק הכה או קילל את כל אחד משני הבעלים אינו חייב כמקלל ומכה אביו, משום הספק. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכה\u0004 את \u0003זה\u0004 שהוא ספק אביו ראשון \u0003וחזר והכה\u0004 את \u0003זה; קלל\u0004 את \u0003זה וחזר וקלל\u0004 את \u0003זה; קלל\u0004 את \u0003שניהם בבת אחת\u0004 או \u0003הכה\u0004 את \u0003שניהם בבת אחת\u0004 — בכל אחד מאלה \u0003חייב,\u0004 שהרי בודאי אחד מהם הוא אביו. \u0003ר' יהודה אומר:\u0004 אם היכה או קילל את שניהם \u0003בבת אחת — חייב, בזה אחר זה — פטור.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר פטור\u0004 אפילו \u0003בבת אחת!\u0004 ומשיבים: \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 נחלקו בכך \u0005על פי שיטתו]\u0006 של \u0003ר' יהודה.\u0004","ושואלים: \u0003מאי טעמא דמאן\u0004 \u0005[מה הטעם של מי]\u0006 ש\u0003פטר? אמר ר' חנינא: נאמר ברכה\u0004 (כלומר, קללה, בלשון סגי נהור, שלא לדבר בלשון בלתי נקיה) \u0003למטה\u0004 (כלומר, ביחס ליושבי מטה — בני אדם), בקללת אביו ואמו (\"כי איש איש אשר יקלל את אביו ואת אמו מות יומת אביו ואמו קילל דמיו בו\". ויקרא כ, ט), \u0003ונאמר ברכה למעלה\u0004 (כלומר, כלפי מעלה — הקדוש ברוך הוא) לגבי מקלל את ה' (\"איש איש כי יקלל אלהיו ונשא חטאו\". שם כד, טו). \u0003מה למעלה\u0004 לגבי קללת ה' הרי זו קללה \u0003שאין בה שותפות\u0004 שהוא אחד ויחיד — \u0003אף למטה\u0004 הכוונה דווקא לקללת אבהות \u0003שאין בה שותפות.\u0004 וכאן, כיון שיש שותפות, כלומר, ספק בדבר, אינו מתחייב אפילו כאשר ודאי שאחד מהם הוא אביו. \u0003ואיתקש\u0004 \u0005[והוקשה,\u0006 הושוותה\u0005]\u0006 \u0003הכאה לקללה,\u0004 וכיון שבקללה אינו נידון כשלא ברור מי הוא אביו — גם בהכאה כך.","שנינו במשנה: \u0003ועולה\u0004 לעבודה ככהן \u0003במשמרו\u0004 של זה ושל זה, ואינו חולק בשני המשמרות. ושואלים: \u0003וכי מאחר\u0004 ש\u0003אינו חולק, למה עולה?\u0004 ותוהים: \u0003למה עולה?!\u0004 מה השאלה, \u0003האמר\u0004 \u0005[הרי אומר]\u0006 הוא: \u0003בעינא דניעביד\u0004 \u0005[רוצה אני לעשות]\u0006 \u0003מצוה\u0004 ולשמש ככהן! ומסבירים: \u0003אלא\u0004 כך היתה משמעות ההערה על לשון המשנה: \u0003\"עלה\" לא קתני\u0004 \u0005[שנה]\u0006 \u0003אלא\u0004 שנה בלשון הווה: \u0003\"עולה\",\u0004 והכוונה — שעולה \u0003בעל כרחו,\u0004","ועל כך שואלים: מפני מה מחייבים אותו לעלות. \u0003אמר רב אחא בר חנינא אמר אביי אמר ר' אסי אמר ר' יוחנן: משום פגם משפחה.\u0004 שאם לא יעבוד עם משמרו, יאמרו לבני המשפחה: אחד מבניכם פסול הוא, ונמצאת המשפחה נפגעת בשל ילד זה שלפי האמת אינו פסול, אף שהוא ספק.","עוד שנינו במשנה: \u0003ואם היו שניהם במשמר\u0004 אחד — נוטל חלק אחד. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 אם היו \u0003שני משמרות\u0004 שהוא \u0003לא\u0004 מקבל כלל — \u0003דאזיל להא משמרה ומדחו ליה\u0004 \u0005[שהולך למשמרת זו ודוחים אותו]\u0006 מלקבל, שאומרים לו: אתה שייך למשמרת אחרת, \u0003ואזיל להא משמרה ומדחו ליה\u0004 \u0005[והולך למשמרת זו ודוחים אותו]\u0006 באותה דרך, אם כן ב\u0003משמר אחד נמי\u0004 \u0005[גם כן]:\u0006 \u0003אזיל להאי בית אב\u0004 \u0005[הולך לבית אב זה]\u0006 המשמש ביום אחד בשבוע \u0003ומדחו ליה\u0004 \u0005[ודוחים אותו]\u0006 וכן הולך הוא לבית אב אחר ודוחים אותו, שהרי אין יודעים לאיזה בית אב הוא שייך!","\u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם היו שניהם\u0004 בני \u0003משמר אחד ובית אב אחד,\u0004 שאז אי אפשר לדחותו — \u0003נוטל חלק אחד.\u0004","","\u0003מצות חליצה\u0004 נעשית \u0003בשלשה דיינין, ו\u0004לאו דווקא דיינים מומחים להוראה אלא \u0003אפילו שלשתן הדיוטות.\u0004 אם \u0003חלצה במנעל\u0004 (נעל, המכסה את הרגל) — \u0003חליצתה כשרה, באנפיליא\u0004 של בגד — \u0003חליצתה פסולה,\u0004 שאינה קרויה נעל. \u0003בסנדל שיש לו עקב — כשר, ושאין לו עקב — פסול.\u0004","אם היתה רגלו של היבם חתוכה \u0003מן הארכובה\u0004 (הברך) \u0003ולמטה\u0004 והיה מנעל על הגדם, וחלצה — ה\u0003חליצה כשרה.\u0004 אם היתה הרגל חתוכה \u0003מן הארכובה ולמעלה\u0004 — ה\u0003חליצה פסולה. חלצה בסנדל שאין שלו, או בסנדל של עץ, או\u0004 שחלצה \u0003ב\u0004סנדל \u0003של\u0004 רגל \u0003שמאל\u0004 שהיה נעול על רגל \u0003ימין\u0004 — ה\u0003חליצה כשרה. חלצה ב\u0004סנדל \u0003גדול שהוא יכול\u0004 עדיין \u0003להלוך בו או ב\u0004סנדל \u0003קטן שהוא חופה\u0004 (מכסה) \u0003את רוב רגלו — חליצתה כשרה.\u0004","ושואלים: \u0003ומאחר\u0004 שאמרנו במשנה ש\u0003אפילו שלשה הדיוטות\u0004 כשרים לחליצה, \u0003דיינין למה לי\u0004 לומר במשנה? די היה לומר שמצוותה בשלושה! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003בשלשה שיודעים\u0004 לפחות \u0003להקרות\u0004 ליבם וליבמה את מה שהם צריכים לומר \u0003כעין דינים,\u0004 ולא הדיוטות גמורים. ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 איפוא במשנתנו \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מצות חליצה בשלשה שיודעין להקרות כעין דינים. ר' יהודה אומר: בחמשה\u0004 עושים חליצה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שצריך שלושה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בענין חליצה: \u0003\"\u0004... ועלתה יבמתו השערה אל ה\u0003זקנים...\"\u0004(דברים כה, ז) — הרי מיעוט רבים \u0003שנים. ו\u0004מאחר ש\u0003אין\u0004 עושים \u0003בית דין\u0004 שיהיה מנין חבריו \u0003שקול\u0004 (זוגי), כדי שאם ייחלקו בדעותיהם יהיה מי שמכריע, לכן \u0003מוסיפין עליהן עוד אחד — הרי כאן שלשה. ור' יהודה\u0004 דורש, נאמר בפסוק אחד: \"וקראו לו \u0003זקני\u0004 עירו...\" (שם שם ח) — הרי \u0003שנים,\u0004 ונאמר בפסוק שלאחריו \u0003\"זקנים\"\u0004 — הרי \u0003שנים\u0004 נוספים, \u0003ו\u0004כיון ש\u0003אין בית דין שקול, מוסיפין עליהן עוד אחד — הרי כאן חמשה.\u0004 ושואלים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003האי\u0004 \u0005[\u0006מלה \u0005זו]\u0006 \u0003\"זקני\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בה]\u0006 כיצד הוא דורש אותה? ומסבירים: \u0003מיבעי ליה לרבויי\u0004 \u0005[נצרכת לו לרבות]\u0006 \u0003אפילו שלשה הדיוטות,\u0004 ש\"זקנים\" בא לצמצם ולהדגיש דווקא זקנים, כלומר, חכמים, אבל כיון שכתוב מיעוט אחר מיעוט, \"זקנים\" ו\"זקני\", אין מיעוט אחר מיעוט אלא לרבות, ומרבים אפילו הדיוטות.","ושואלים: \u0003ור' יהודה,\u0004 שחליצה כשרה ב\u0003הדיוטות, מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 הדבר \u0003מ\u0004מה שכתוב \u0003\"לעיני\u0004 הזקנים\u0003\"\u0004 (שם שם ט) ובדרך זו, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"לעיני\" — פרט לסומים\u0004 (עיוורים) שאינם יכולים לראות,","","","\u0003ומדאיצטריך\u0004 \u0005[ומ\u0006כיון \u0005שהוצרך]\u0006 \u0003\"לעיני\" למעוטי\u0004 \u0005[למעט]\u0006 דיינים \u0003סומים, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אפילו הדיוטות\u0004 כשרים בחליצה. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003סנהדרין,\u0004 דיינים מומחים, דווקא \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 אם כן \u0003למה לי למעוטי\u0004 \u0005[למעט]\u0006 \u0003סומין?\u0004 הרי \u0003מדתני\u0004 \u0005[מ\u0006ברייתא \u0005ששנה]\u0006 \u0003רב יוסף נפקא\u0004 \u0005[יוצא,\u0006 נלמד הדבר\u0005],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף: כשם שבית דין מנוקים בצדק,\u0004 שצריכים להיות נקיים מכל אשמה ומכל חשד, \u0003כך בית דין\u0004 צריכים להיות \u0003מנוקים מכל מום\u0004 גופני,"],["\u0003שנאמר \"כלך יפה רעיתי ומום אין בך\"\u0004 (שיר השירים ד, ז), ואם הוצרכו לומר שהזקנים בחליצה לא יהיו סומים, משמע שאינם דיינים ממש, אלא אף הדיוטות, שבהם לא נאמרה כרגיל הגבלה זו. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 את הכתוב \u0003ההוא\u0004 שנאמר \u0003\"לעיני\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו,\u0006 בו\u0005]?\u0006 ומשיבים: הכתוב \u0003ההוא לכ\u0004 מו שאמר \u0003רבא הוא דאתא\u0004 \u0005[שבא].\u0006 ש\u0003אמר רבא: צריכי דייני למיחזי רוקא דקא נפיק מפומא\u0004 \u0005[צריכים\u0006 ה\u0005דיינים לראות\u0006 את ה\u0005רוק שהוא\u0006 \u0005יוצא מפי]\u0006 ה\u0003יבמה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לעיני הזקנים... וירקה\"\u0004 (דברים כה, ט).","ושואלים: אם כן \u0003ואידך נמי מיבעי ליה\u0004 \u0005[והאחר,\u0006 ר' יהודה, \u0005גם כן\u0006 הרי \u0005צריך אותו\u0006 \"לעיני\"\u0005]\u0006 \u0003לכ\u0004 מו שאמר \u0003רבא?!\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 זה \u0005גם כן],\u0006 שהפסוק \"לעיני\" לענין זה נאמר, \u0003ואלא\u0004 שדי לחליצה שתהיה ב\u0003הדיוטות מנא ליה\u0004 \u0005[מניין לו]?\u0006 \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 לו הדבר \u0003מ\u0004מה שנאמר \u0003\"בישראל\",\u0004 שכוונתו — \u0003ישראל כל דהו\u0004 \u0005[שהוא].\u0006","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005],\u0006 \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"ישראל\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו,\u0006 בו\u0005]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לכדתני\u0004 \u0005[לכ\u0006 פי \u0005ששנה]\u0006 \u0003רב שמואל בר יהודה:\u0004 מה שנאמר \u0003\"בישראל\"\u0004 (שם ז) — כוונתו \u0003בבית דין של ישראל, ולא בבית דין של גרים,\u0004 שמצות חליצה חייבת להיעשות בפני ישראל מיוחסים, ולא בגרים שמבחינה זו אינם שייכים לישראל.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהודה\u0005]\u0006 הלכה זו מניין לו? ומשיבים: \u0003\"בישראל\" אחרינא כתיב\u0004 \u0005[אחר,\u0006 נוסף, \u0005נאמר]\u0006 שם, פעם שניה (שם י). \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מה עושה הוא בביטוי מיותר זה? ומסבירים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכ\u0006 פי \u0005ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: פעם אחת היינו יושבין לפני ר' טרפון, ובאה יבמה לחלוץ, ואמר לנו: ענו כולכם\u0004 אחר המעשה: \u0003\"חלוץ הנעל\".\u0004 שכך הוא מפרש את הכתוב \"ונקרא שמו בישראל חלוץ הנעל\" (שם י).","ושואלים: \u0003ואידך\u0004 \u0005[האחר,\u0006 ר' יהודה\u0005],\u0006 מהיכן למד הוא הלכה זו? ומשיבים: \u0003מ\"ונקרא\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר, שצריך בפועל לקרוא כך.","ואף במחלוקת בענין מספר הדיינים שואלים: \u0003אלא מעתה,\u0004 שאנו דורשים כל לשון רבים הכתובה בפרשה שבא להוסיף דיינים נוספים, אם כן מה שנאמר \"וקראו לו זקני עירו ודברו אליו\" (שם ח), \u0003\"וקראו\"\u0004 — הרי \u0003שנים, \"ודברו\" — שנים, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003ל\u0004שיטת \u0003ר' יהודה — הרי כאן תשעה\u0004 דיינים, ו\u0003לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003הרי כאן שבעה!\u0004","ומשיבים: הכתוב \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו ל\u0006דבר אחר \u0005כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"וקראו לו\"\u0004 כוונתו — הם עצמם, \u0003ולא שלוחם, \"ודברו אליו\" — מלמד שמשיאין\u0004 (נותנים) \u0003לו עצה ההוגנת לו\u0004 לענין הנישואין. כגון \u0003שאם היה הוא ילד\u0004 (צעיר) \u0003והיא זקנה,\u0004 או \u0003הוא זקן והיא ילדה — אומרים לו\u0004 שלא ייבם, כי: \u0003מה לך אצל ילדה\u0004 אם זקן אתה, \u0003מה לך אצל זקנה\u0004 אם צעיר אתה, \u0003כלך\u0004 (לך-לך) \u0003אצל שכמותך\u0004 קרובה לגילך, \u0003ואל תכניס קטטה לתוך ביתך,\u0004 שהשוני בגיל בוודאי יגרום אחר כך לחוסר הסכמה ולקטטה.","\u0003אמר רבא אמר רב נחמן: הלכה\u0004 היא בענין זה \u0003חליצה בשלשה, הואיל וסתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא כוותיה\u0004 \u0005[כשיטתו]\u0006 של תנא קמא, והלכה כסתם משנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן\u0004 לאחר ששמע דבר זה מפיו: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מיאון נמי\u0004 \u0005[גם כן]\u0006 נעשה אותו בשלושה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המיאון והחליצה — בשלשה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 זה \u0005גם כן],\u0006 שחייבים להיות שלושה בעת המיאון, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מיאון, בית שמאי אומרים\u0004 שהוא נעשה רק על ידי \u0003בית דין מומחין, ובית הלל אומרים: בבית דין\u0004 של מומחים, \u0003ו\u0004גם \u0003שלא בבית דין. אלו ואלו מודים שצריך\u0004 על כל פנים שיהיו בשעת המיאון \u0003שלשה. ר' יוסי בר' יהודה ור' אלעזר בר' יוסי מכשירין\u0004 גם \u0003בשנים,\u0004 שלענין מיאון אין צורך בבית דין, אלא די בשני עדים. \u0003ואמר רב יוסף בר מניומי אמר רב נחמן: הלכה כאותו הזוג.\u0004 הרי יש סתם משנה, ומכל מקום אין אנחנו פוסקים כמותה.","ומשיבים: \u0003התם חד סתמא\u0004 \u0005[שם\u0006 בענין מיאון יש רק \u0005סתם אחד],\u0006 שאומר שהמיאון בשלושה, \u0003והכא תרי סתמי\u0004 \u0005[וכאן\u0006 יש \u0005שני סתמים],\u0006 כי דין זה של חליצה בשלושה נאמר כסתם משנה פעמיים, גם כאן וגם באותה משנה במסכת סנהדרין. ומקשים: \u0003התם נמי תרי סתמי נינהו\u0004 \u0005[שם גם כן\u0006 בענין מיאון \u0005שני סתמים הם].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מיאנה או שחלצה בפניו\u0004 של חכם \u0003ישאנה\u0004 חכם זה אם רצונו בכך, ואין חושדים בו, \u0003מפני שהוא בית דין.\u0004 משמע שאין מיאון אלא בבית דין!","\u0003אלא, התם תרי סתמי\u0004 \u0005[שם\u0006 יש \u0005שני סתמים]\u0006 ו\u0003הכא\u0004 \u0005[כאן]\u0006 יש \u0003תלתא סתמי\u0004 \u0005[שלושה סתמים],\u0006 יש עוד סתם האומר שחליצה בשלושה.","ושואלים: \u0003מכדי הא סתמא והא סתמא\u0004 \u0005[\u0006הרי \u0005זהו סתם וזהו סתם],\u0006 \u0003מה לי\u0004 אם זהו \u0003חד סתם\u0004 \u0005[סתם אחד]\u0006 \u0003מה לי\u0004 אם זה \u0003תרי\u0004 \u0005[שני]\u0006 \u0003סתם מה לי\u0004 או זה \u0003תלתא\u0004 \u0005[שלוש\u0006 פעמים\u0005]?\u0006 \u0003אלא אמר רב נחמן בר יצחק:\u0004 הטעם הוא \u0003הואיל וסתם\u0004 זה, שחליצה בשלושה, נאמר \u0003במקום מחלוקת,\u0004 כלומר, בענין שנחלקו בו, שר' יהודה חולק בה,","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003סמיכת זקנים ועגלה ערופה בשלשה,\u0004 אלו \u0003דברי ר' יוסי. ר' יהודה אומר: בחמשה. החליצה והמיאונין בשלשה. ולא קפליג\u0004 \u0005[חלק]\u0006 \u0003ר' יהודה\u0004 בענין זה — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003ר' יהודה\u0004 מדעתו בענין חליצה בחמישה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שחזר בו, וסיכום ההלכה שדי בשלושה.","ובפרטי הלכות חליצה \u0003אמר רבא: צריכי דייני למיקבע דוכתא\u0004 \u0005[צריכים\u0006 ה\u0005דיינים לקבוע מקום]\u0006 מראש, לעשות בו את החליצה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועלתה יבמתו השערה אל הזקנים\"\u0004 (דברים כה, ז), שמובן שיש מקום קבוע וידוע (\"השער\") למושב בית הדין. מסופר: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עבדי עובדא\u0004 \u0005[עשו מעשה]\u0006 \u0003בחמשה\u0004 דיינים שבפניהם חלצו. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 עשו זאת — \u0003כ\u0004דעת \u0003ר' יהודה, והא הדר ביה\u0004 \u0005[והרי\u0006 הוכחנו כבר ש\u0005חזר בו]\u0006 ר' יהודה! ומשיבים: עשו זאת רק \u0003לפרסומי מילתא\u0004 \u0005[לפרסם\u0006 את \u0005הדבר]\u0006 ולא מפני שמספר זה של דיינים נחוץ.","עוד מסופר: \u0003רב אשי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב כהנא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סליק מר לגבן למלויי בי\u0004 \u0005[יעלה אדוני אלינו למלא\u0006 מספר\u0005]\u0006 \u0003חמשה\u0004 שבפניהם יחלצו. \u0003אמר רב כהנא: הוה קאימנא\u0004 \u0005[הייתי עומד]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה, ואמר לי: תא סק לזירזא דקני\u0004 \u0005[בוא עלה לחבילה של קנים],\u0006 שעשו שם מקום מוגבה למושב בית דין, \u0003לאיצטרופי בי\u0004 \u0005[להצטרף\u0006 למנין\u0005]\u0006 \u0003חמשה\u0004 שיחלצו בפניהם. \u0003אמרו לו: למה לי\u0004 שיהיו \u0003חמשה?\u0004 והלא די בשלושה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כי היכי דליפרסם מילתא\u0004 \u0005[כדי שיתפרסם הדבר],\u0006 ולא מפני שהוא חובה מצד הדין.","מסופר: \u0003רב שמואל בר יהודה הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב יהודה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סק תא לזירזא דקני לאצטרופי בי\u0004 \u0005[עלה, בוא לחבילת הקנים להצטרף ל\u0006מנין\u0005]\u0006 \u0003חמשה לפרסומי מילתא\u0004 \u0005[\u0006כדי \u0005לפרסם\u0006 את \u0005הדבר\u0006 של החליצה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שמואל בר יהודה: \u0003תנינא\u0004 \u0005[שנינו],\u0006 נאמר \u0003\"בישראל\"\u0004 (שם י) — וכוונתו \u0003בבית דין\u0004 של \u0003ישראל\u0004 גמורים \u0003ולא בבית דין של גרים, ואנא\u0004 \u0005[ואני]\u0006 \u0003גר אנא\u0004 \u0005[אני],\u0006 שגם הוא וגם אביו התגיירו.","\u0003אמר רב יהודה: כגון\u0004 אדם הגון כמו \u0003רב שמואל בר יהודה,\u0004 הגם שמספר דבר כזה על עצמו, \u0003מפיקנא ממונא אפומיה\u0004 \u0005[אני מוציא ממון על פיו]\u0006 כי בטוחני בו שהוא נאמן בכל דבר. ותוהים: \u0003מפיקנא סלקא דעתך\u0004 \u0005[מוציא אני עולה על דעתך\u0006 לומר\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"על פי שנים עדים\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 (שם יז, ו), ובפחות משני עדים אין זו עדות! \u0003אלא\u0004 הכוונה היא \u0003מרענא שטרא אפומיה\u0004 \u0005[מרע אני\u0006 כוחו של \u0005שטר על פיו],\u0006 שאם יבוא הוא לבדו ויאמר ששטר מסויים פרוע, שוב אין אני נזקק לדון בו, שאני מאמין לו, אף שהשטר עומד לפנינו.","אגב הזכרת דינו של גר בענייננו, \u0003אמר רבא:\u0004"],["\u0003גר דן את חבירו\u0004 מ\u0003דבר תורה, שנאמר: \"שום תשים עליך מלך אשר יבחר ה' אלהיך בו מקרב אחיך תשים עליך מלך\"\u0004 (דברים יז, טו). ומדייקים: \u0003עליך,\u0004 על בן ישראל \u0003הוא דבעינן\u0004 \u0005[שאנו צריכים]\u0006 שיהא השר והדיין (ולאו דווקא מלך) \u0003מקרב אחיך\u0004 ישראלי כמותך, \u0003אבל גר דן את חבירו גר,\u0004 שלגביו לא נאמרה הגבלה זו.","\u0003ואם היתה אמו\u0004 של הגר \u0003מישראל — דן אפילו ישראל. ולענין חליצה עד שיהא\u0004 גם \u0003אביו ו\u0004גם \u0003אמו מישראל, שנאמר\u0004 בסדר החליצה: \u0003\"ונקרא שמו בישראל\u0004 בית חלוץ הנעל\u0003\"\u0004 (דברים כה, י), משמע שצריך שיהא בתוך ישראל, מכל צד.","\u0003אמר רבה, אמר רב כהנא אמר רב: אם יבא אליהו\u0004 הנביא \u0003ויאמר: \"חולצין במנעל\" — שומעין לו,\u0004 אבל אם יאמר: \u0003\"אין חולצין בסנדל\" — אין שומעין לו, שכבר נהגו העם\u0004 לחלוץ \u0003בסנדל.\u0004","\u0003ורב יוסף אמר\u0004 בשם \u0003רב כהנא, אמר רב: אם יבא אליהו ויאמר: אין חולצין במנעל — שומעין לו,\u0004 אם יאמר: \u0003אין חולצין בסנדל — אין שומעין לו, שכבר נהגו העם בסנדל.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה, שלכאורה אמרו שניהם אותו דבר? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין חליצה ב\u0003מנעל לכתחלה.\u0004 שלדעת רבה אין חולצים במנעל לכתחילה, שהרי אמר שאם יבוא אליהו ויתיר — נשמע לו, משמע שעד שיבוא אין חולצים לכתחילה, ולדעת רב יוסף חולצים לכתחילה במנעל, עד שיבוא אליהו ויאמר להיפך.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אפילו לכתחלה\u0004 חולצים במנעל, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלצה במנעל — חליצתה כשרה.\u0004 ומן הלשון המנוסחת בלשון עבר נדקדק: \u0003דיעבד — אין\u0004 \u0005[כן],\u0006 \u0003לכתחלה — לא!\u0004","ומשיבים: \u0003הוא הדין\u0004 ש\u0003אפילו לכתחלה\u0004 חולצים במנעל, \u0003ואיידי דבעי למיתני סיפא\u0004 \u0005[ומתוך שרצה לשנות\u0006 ב\u0005סוף]\u0006 שאם חלצה \u0003באנפיליא חליצתה פסולה,\u0004 ש\u0003אפילו דיעבד\u0004 פסול, \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005תחילתה]\u0006 של המשנה בלשון \u0003דיעבד.\u0004","ומעירים: \u0003ו\u0004חליצה ב\u0003מנעל לכתחלה — תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: פעם אחת הלכתי לנציבין\u0004 שבבבל, ו\u0003מצאתי זקן אחד. אמרתי לו: כלום אתה בקי\u0004 (מכיר) \u0003בר' יהודה בן בתירא,\u0004 שהיה מנציבין? \u0003אמר לי: הן\u0004 (כן), \u0003ועל שולחני הוא תדיר.\u0004 שאלתי את הזקן: \u0003כלום ראית שחלץ ביבמה\u0004, כדיין?","\u0003אמר לי: ראיתי שחלץ הרבה פעמים.\u0004 שאלתיו: \u0003במנעל או בסנדל? אמר לי: וכי חולצין במנעל? והתורה\u0004 הרי \u0003אמרה \"\u0004וחלצה \u0003נעלו\"\u0004 (שם ט) ומשמע — בכל דבר שהוא נעול, בין בסנדל, בין במנעל, \u0003ולא\u0004 אמרה \u0003\"\u0004וחלצה \u0003מנעלו\". אמרתי לו: אם כן, מה ראה ר' מאיר לומר חלצה במנעל חליצתה כשירה?!\u0004","\u0003ר' יעקב אומר משמו\u0004 של ר' מאיר: \u0003חולצין במנעל לכתחלה\u0004. ומסבירים: \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כי \u0003לכתחלה לא\u0004 חולצים במנעל, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דהויא פנתא\u0004 \u0005[שהצד העליון של הנעל]\u0006 הוא \u0003מעל\u0004 רגלו ומכסהו \u0003וארקתא\u0004 \u0005[והשרוכים]\u0006 הם \u0003מעל\u0004 ל\u0003מעל, והתורה אמרה \"מעל\" ו\u0004דיוקו — \u0003לא מעל\u0004 ל\u0003מעל, אי הכי\u0004 \u0005[אם כך]\u0006 אנו מפרשים, \u0003אפילו דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יחלצו בו!","אלא ודאי לא מצד זה החשש, כי אם \u0003גזירה משום מנעל מרופט\u0004 (קרוע) שאיננו מכסה את רגלו, ואילו סנדל מרופט כזה אינו ראוי לנעלו כלל, ולכן בחליצה בסנדל אין מקום לחשש.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 גזירה \u0003משום חצי מנעל\u0004 שבסנדל אי אפשר לנעול מחציתו, אבל בנעל אפשר לנעול בדוחק.","\u0003אמר רב: אי לאו דחמיתיה לחביבי\u0004 \u0005[אם לא שראיתי את דודי,\u0006 ר' חייא\u0005]\u0006 ש\u0003חלץ בסנדל דאית לה שינצין\u0004 \u0005[שיש לו שרוכים],\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא הואי חליצנא\u0004 \u0005[הייתי חולץ]\u0006 \u0003אלא בסנדלא דטייעא דמיהדק טפי\u0004 \u0005[בסנדל של ערבים שהוא מהודק יותר].\u0006 ומסבירים: \u0003והאי דידן\u0004 \u0005[וזה\u0006 הסנדל \u0005שלנו],\u0006 \u0003אף על גב דאית ביה חומרתא\u0004 \u0005[אף על פי שיש בו קשר]\u0006 בראשו שלא יישמט מן הרגל, \u0003קטרינן ביה מיתנא\u0004 \u0005[קושרים בו חבל]\u0006 מעליו בשעת החליצה כדי להדקו, \u0003כי היכי דתהוי חליצתה מעלייתא\u0004 \u0005[כדי שתהא חליצתה מעולה],\u0006 שאם יוכלו לחולצו בקלות, אין זה נקרא חליצה.","\u0003סימן\u0004 להלכות הבאות שאמר רב יהודה בשם רב: \u0003התרת יבמה סנדל. אמר רב יהודה אמר רב: התרת יבמה לשוק — בשמיטת\u0004 הסנדל מ\u0003רוב העקב\u0004 של הרגל, שאף על פי שלא נחלץ כולו, מותרת להינשא.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003הותרו רצועות\u0004 ה\u0003מנעל\u0004 או ה\u0003סנדל\u0004 מעצמם, \u0003או ששמט\u0004 הוא את הסנדל מ\u0003רוב הרגל — חליצתה פסולה,\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום ש\u0003שמט הוא\u0004 את רוב הרגל והיא רק גמרה את החליצה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003שמטה היא — חליצתה כשרה.\u0004 ונדייק עוד: \u0003רוב הרגל — אין\u0004 \u0005[כן],\u0006 \u0003רוב העקב — לא!\u0004","ודוחים: \u0003לא,\u0004 יש לומר כי \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003רוב הרגל, היינו\u0004 \u0005[זהו]\u0006 \u0003רוב העקב. ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לו]\u0006 \u0003רוב הרגל — דכולא חיילא דכרעא עליה דחיס\u0004 \u0005[שכל כוחה של הרגל על\u0006 העקב הוא \u0005לוחץ].\u0006","ומעירים: \u0003מסייע ליה\u0004 \u0005[מסייעת לו]\u0006 ברייתא זו \u0003לר' ינאי.\u0004 ש\u0003אמר ר' ינאי: בין שהתיר הוא\u0004 את סנדלו \u0003ושמטה היא\u0004 ממנו, \u0003בין שהתירה היא ושמט הוא — חליצתה פסולה, עד שתתיר היא ותשמיט\u0004 (ותשמוט) \u0003היא.\u0004 ובאותו ענין \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ינאי:\u0004 אם לא חלצה את הסנדל אלא \u0003קרעתהו, מהו?\u0004 וכן אם \u0003שרפתהו\u0004 על ידי גחלת, \u0003מהו?\u0004 וצדדי השאלה: האם \u0003גלויי כרעא בעינן\u0004 \u0005[גילוי הרגל אנחנו צריכים],\u0006 שזוהי מהות החליצה, \u0003והאיכא\u0004 \u0005[והרי יש\u0006 כאן\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003חליצה\u0004 מעל הרגל \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005]?\u0006 לשאלה זו לא נמצאה תשובה, והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' נחמיה מרבה:\u0004 אם היה נעול \u0003שני מנעלים זה על גב זה מהו?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר],\u0006 \u0003אילימא דשלפתיה לעילאי\u0004 \u0005[אם תאמר ששלפה את\u0006 המנעל \u0005העליון]\u0006 \u0003וקאי תתאי\u0004 \u0005[ועומד\u0006 המנעל \u0005התחתון]\u0006 במקומו — הלא \u0003\"מעל\u0004 רגלו \u0003\"\u0004\u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא מעל\u0004 ל\u0003מעל!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כגון \u0003דקרעתיה לעילאי\u0004 \u0005[שקרעה את\u0006 המנעל \u0005העליון]\u0006 \u0003ושלפתיה לתתאי\u0004 \u0005[ושלפה את התחתון]\u0006 \u0003וקאי עילאי\u0004 \u0005[והעליון עומד]\u0006 עדיין ברגלו אף שהוא קרוע. והשאלה היא: \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 : האם \u0003חליצה בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא איכא\u0004 \u0005[והרי יש\u0006 כאן\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003גלויי כרעא בעינן, וליכא\u0004 \u0005[גילוי הרגל אנו צריכים, ואין\u0006 כאן\u0005],\u0006 שהרי עדיין הרגל מכוסה במנעל העליון הקרוע."],["\u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש דבר כגון זה]\u0006 שנועלים מנעל על גבי מנעל? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דחזיוה רבנן\u0004 \u0005[שראו חכמים]\u0006 את \u0003רב יהודה דנפק בחמשא זוזי מוקי לשוקא\u0004 \u0005[שיצא\u0006 פעם \u0005בחמישה זוגות נעליים,\u0006 כגון נעלי בית, זה על גבי זה \u0005לשוק].\u0006","ועוד הלכה \u0003אמר רב יהודה אמר רב: יבמה\u0004 קטנה \u0003שהגדילה\u0004 (שגדלה) \u0003בין האחין\u0004 של בעלה — \u0003מותרת לינשא לאחד מן האחין, ואין חוששין שמא\u0004 בזמן היותה שם \u0003חלצה סנדל לאחד מהן,\u0004 ונמצא שהיתה חלוצה מאז. ומדייקים: \u0003טעמא, דלא חזינן\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שאין אנו רואים]\u0006 שחלצה, \u0003הא חזינן\u0004 \u0005[הרי\u0006 אם \u0005אנו רואים]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שדינה כחלוצה.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין שנתכוון הוא\u0004 לשם חליצה \u0003ולא נתכוונה היא, בין שנתכוונה היא ולא נתכוון הוא — חליצתה פסולה, עד שיתכוונו שניהם כאחד!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 רב יהודה: \u0003אף על גב דחזינן\u0004 \u0005[אף על פי שרואים אנו]\u0006 שחלצה סנדל לאחד מהם — \u0003אין חוששין שמא כוונו\u0004 לשם חליצה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את הענין באופן אחר: \u0003טעמא, דלא חזינן\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שאין אנו רואים]\u0006 שחלצה, \u0003הא חזינן\u0004 \u0005[הרי\u0006 אם \u0005אנו רואים] —\u0006 \u0003חוששין\u0004 שדינה כחלוצה אפילו אם לא היתה כוונה מיוחדת לחליצה. \u0003ודקא תנא בעי\u0004 \u0005[ומה ששנה\u0006 ש\u0005צריך]\u0006 \u0003כוונה\u0004 בחליצה — \u0003הני מילי לאישתרויי לעלמא\u0004 \u0005[דברים אלה\u0006 אמורים כדי שתהא חליצה גמורה \u0005להתירה לכול],\u0006 \u0003אבל לאחין מיפסלא\u0004 \u0005[\u0006היא \u0005נפסלת]\u0006 אפילו בלא כוונה.","ועוד \u0003אמר רב יהודה אמר רב: סנדל התפור בפשתן,\u0004 שתפרו את חלקיו זה לזה בחוט פשתן — \u0003אין חולצין בו, שנאמר \"ואנעלך תחש\"\u0004 (יחזקאל טז, י) שהוא עור של חיה, משמע שנעל הוא דבר שעשוי כולו מעור. ומקשים: אם מ\"תחש\" אנו למדים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 נעל עשוי מעור של \u0003תחש\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004 ודוחים: \u0003\"נעל\" \"נעל\"\u0004 הכתובה בתורה כמה פעמים \u0003ריבה\u0004 שכל סוגי נעליים במשמע, ומכל עור שהוא.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"נעל\" \"נעל\" ריבה — אפילו כל מילי נמי\u0004 \u0005[כל דבר גם כן]\u0006 ייחשב לנעל, אפילו אינו עשוי כלל מעור! ומשיבים: \u0003אם כן\u0004 מה שנאמר \u0003\"תחש\" מאי אהני ליה\u0004 \u0005[מה הועיל לו],\u0006 אם לא נלמד מכאן דבר? אלא ודאי למדים מכאן שצריך שיהא כולו של עור.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מרב:\u0004 סנדל שעשאו כך: \u0003הוא של עור, ותריסיותיו\u0004 (החלקים המחזיקים את רצועותיו) \u0003של שער\u0004 כגון שנארגו משיער עזים, \u0003מהו\u0004 דינו לחליצה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי לא קרינן ביה\u0004 \u0005[האם אין אנו קוראים בו]\u0006 בסנדל כגון זה: \u0003\"ואנעלך תחש\",\u0004 שכיון שהוא עשוי מדבר הבא מן החי, הרי הוא כשר. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שכל הבא מן החי כשר, אפילו \u0003כולו של שער נמי\u0004 \u0005[גם כן]\u0006 יהיה כשר! ומשיבים: \u0003ההוא קרקא מקרי\u0004 \u0005[נעל בית נקרא]\u0006 ואינו קרוי \"נעל\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לשמואל: ממאי דהאי\u0004 \u0005[מניין שזה]\u0006 הכתוב \u0003\"וחלצה נעלו מעל רגלו\"\u0004 (דברים כה, ט) \u0003מישלף\u0004 \u0005[לשלוף]\u0006 \u0003הוא — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחלצו את האבנים אשר בהן הנגע\"\u0004 (ויקרא יד, מ), שפירושו — יוציאו אותן ממקומן.","\u0003ואימא זרוזי\u0004 \u0005[ואמור\u0006 לשון \u0005חיזוק]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"החלצו מאתכם אנשים לצבא\"\u0004 (במדבר לא, ב), כלומר, יתחזקו מאתכם אנשים ויבואו לצבא! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 המשמעות העיקרית היא — הוצאת דבר ממקומו, כלומר, \u0003שלופי מביתא לקרבא\u0004 \u0005[יציאה מן הבית אל הקרב].\u0006","ומקשים, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"יחלץ עני בעניו\"\u0004 (איוב לו, טו), שלכאורה מובנו שהעני יתחזק בעניו. שאם היתה הכוונה להוציאו מהעוני שלו — היה צריך לומר \u0003\"מ\u0004 עניו \u0003\"\u0004! ומשיבים: כך צריך לפרש — \u0003בשכר עניו\u0004 (\"בעניו\") \u0003יחלצו\u0004 ויוציאנו \u0003מדינה של גיהנם.\u0004","ועוד הקשה: \u0003אלא הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 \u0003\"חנה מלאך ה' סביב ליראיו ויחלצם\"\u0004 (תהלים לד, ח), שלכאורה הכוונה היא: יחזקם! ומשיבים: כך יש לפרש — \u0003בשכר\u0004 שהם \u0003יראיו — יחלצם מדינה של גיהנם.\u0004","והקשה עוד: \u0003אלא הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 \u0003\"ועצמתיך יחליץ\"\u0004 (ישעיהו נח, יא), \u0003ואמר ר' אלעזר: זו מעולה שבברכות, ואמר רבא\u0004 שכוונתו: \u0003זרוזי גרמי\u0004 \u0005[חיזוק עצמות],\u0006 ומשתמע מכאן שלחליצה יש משמעות של חיזוק! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003משמע הכי ומשמע הכי\u0004 \u0005[משתמע,\u0006 שזה \u0005כך, ומשתמע\u0006 שזה \u0005כך].\u0006 אלא, \u0003דהכא, אי סלקא דעתך\u0004 \u0005[שכאן, אם עולה בדעתך]\u0006 לומר ש\u0003זרוזי\u0004 \u0005[חיזוק]\u0006 \u0003הוא, אם כן, לכתוב רחמנא\u0004 \u0005[שתאמר התורה]\u0006 \u0003\"וחלצה נעלו ברגלו\",\u0004 כלומר, תחזק את הנעל ברגלו.","ומשיבים: \u0003אי כתב רחמנא\u0004 \u0005[אילו אמרה התורה]\u0006 \u0003\"ברגלו\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003\"ברגלו\" — אין\u0004 \u0005[כן],\u0006 \u0003בשוקו — לא,\u0004 שאם נקטעה כף רגלו שוב אינה יכולה לחלוץ, לכן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"מעל רגלו\"\u0004 ללמד ש\u0003אפילו בשוקו\u0004 שהיא על רגלו חולצת. ומשיבים: \u0003אם כן לכתוב רחמנא\u0004 \u0005[שתאמר התורה]\u0006 \u0003\"במעל רגלו\".\u0004 אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעל רגלו\" — שמע מינה מישלף\u0004 \u0005[למד מכאן\u0006 כי \u0005שליפה]\u0006 \u0003הוא.\u0004","אגב כך מספרים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לרבן גמליאל:\u0004 אתם, בני ישראל, הנכם \u0003עמא דחלץ ליה מריה מיניה\u0004 \u0005[עם שחלץ לו אדוניו ממנו],\u0006 שה' עזב אותו כיבם שחלץ ליבמתו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בצאנם ובבקרם ילכו לבקש את ה' ולא ימצאו חלץ מהם\"\u0004 (הושע ה, ו).","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שוטה, מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"חלץ להם\",\u0004 שהיתה כאן חליצה? \u0003\"חלץ מהם\" כתיב\u0004 \u0005[נאמר],\u0006 כביכול שהם חלצו לו, \u0003ואילו\u0004 ב\u0003יבמה\u0004 ש\u0003חלצו לה אחין — מידי מששא אית ביה\u0004 \u0005[וכי ממש יש בו]?\u0006 אף כאן הכוונה שישראל עזבו את ה' ואין בעזיבה זו ממש.","שנינו שאם חלץ \u0003באנפיליא — חליצתה פסולה.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שה\u0003אנפיליא לאו\u0004 \u0005[לא]\u0006 כ\u0003מנעל הוא?\u0004","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]:\u0006 \u0003אין התורם,\u0004 המוציא חלק מן השקלים שנדבו ישראל מן הלשכה ונותן לתוך סלים כדי שישתמשו בהם, \u0003נכנס לא בפרגוד חפות\u0004 (מעיל שיש בו תפר כפול) \u0003ולא באנפיליא, ואין צריך לומר\u0004 שאינו נכנס \u0003במנעל וסנדל, לפי שאין נכנסין במנעל וסנדל לעזרה.\u0004 ותיקנו כן, כדי שלא יבואו לחשוד בתורם שמא הכניס מן הכסף לתוך התפר או לתוך האנפיליא. ומכל מקום משמע מלשון המשנה שאנפיליה איננה בכלל מנעל, שהרי מותר להיכנס בה למקדש כשאין חשד.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ששנו: \u0003אחד מנעל וסנדל ואנפיליא לא יטייל בהן לא מבית לבית ולא ממטה למטה\u0004 ביום הכיפורים, משום איסור נעילת הסנדל, הרי שאנפיליה נחשבת לנעל!","\u0003אמר אביי:\u0004 שם בהלכות יום הכיפורים מדובר באנפיליה \u0003דאית ביה כתיתי\u0004 \u0005[שיש בה סמרטוטים]\u0006 \u0003ו\u0004אסור הדבר \u0003משום תענוג,\u0004 ביום שמצווים בו על העינוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ומשום תענוג בלא\u0004 נעילת \u0003מנעל ביום הכפורים מי אסירי\u0004 \u0005[האם אסורים\u0006 דברים\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר רב הונא כריך סודרא אכרעיה ונפיק\u0004 \u0005[היה כורך סודר על רגליו ויוצא]\u0006 ביום הכיפורים כדי שלא ינזקו רגליו, משמע שאין איסור בלבישת דבר על הרגל, כל שאיננו מנעל! \u0003אלא אמר רבא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמרו שאנפיליה דינה כנעל — הרי זה \u0003באנפיליא של עור, כאן\u0004 שאין חושבים אותה למנעל — \u0003באנפיליא של בגד.\u0004","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שיש לחלק, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה ששנינו ב\u0003יום הכפורים\u0004 על מה ששנינו ב\u0003יום הכפורים\u0004 עצמו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יטייל אדם בקורדקיסין\u0004 (נעלי בית) \u0003בתוך ביתו\u0004 ביום הכיפורים, \u0003אבל מטייל הוא באנפילין בתוך ביתו\u0004 — משמע שאנפיליה מותרת, והרי שנינו שאסורה! \u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד מכאן]\u0006 כי \u0003כאן באנפיליא של עור\u0004 — אסורה משום נעל, \u0003כאן — באנפיליא של בגד\u0004 — מותר. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: חלצה במנעל הנפרם\u0004 שנפתחו תפריו אלא \u0003שחופה\u0004 עדיין \u0003את רוב הרגל,\u0004 או \u0003בסנדל הנפחת\u0004 שנפתח חלק מסולייתו, \u0003שמקבל\u0004 עדיין \u0003את רוב הרגל,\u0004 או \u0003בסנדל של שעם\u0004 (פקק) \u0003ו\u0004כן \u0003של סיב\u0004 מן העץ, או חלצה \u0003בקב הקיטע\u0004 (רגל עץ של קטוע רגל), \u0003במוק\u0004 (נעל לבד), \u0003בסמיכת הרגלים\u0004 שעושה הקיטע לרגליו כעין כיסוי, שאיננו נעל ממש לשים אליו את גדמי רגליו, או \u0003באנפיליא של עור, ו\u0004כן \u0003החולצת מן הגדול,\u0004 כלומר, שהיה היבם גדול,"],["\u0003בין\u0004 שהיה היבם \u0003עומד, בין יושב, בין מוטה\u0004 (נשען), \u0003והחולצת מן הסומא\u0004 (העיוור) — בכל אלה \u0003חליצתה כשרה. אבל\u0004 אם חלצה \u0003במנעל הנפרם\u0004 (שנקרע) עד \u0003שאין חופה את רוב הרגל,\u0004 או \u0003בסנדל הנפחת\u0004 (השבור) \u0003שאינו מקבל את רוב הרגל, ובסמיכת הידים\u0004 שעושה קיטע לעצמו גם בידיו מעין נעלי עור, כדי לגרור את עצמו בעזרתן, \u0003ובאנפיליא של בגד, וחולצת מן הקטן\u0004 — בכל אלה \u0003חליצתה פסולה.\u0004","ומעירים: דעה זו, ש\u0003קב הקיטע\u0004 נחשב כנעל, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא] —\u0006 שיטת \u0003ר' מאיר היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הקיטע יוצא\u0004 בשבת \u0003בקב שלו,\u0004 שהוא כנעל של אדם אחר, שאינו מקפיד על טיב החומר שממנו עשויה הנעל, אלו \u0003דברי ר' מאיר. ר' יוסי אוסר,\u0004 כיון שסבור שאין הקב נחשב כנעל.","אך בהמשך נאמר ש\u0003באנפיליא של בגד\u0004 החליצה פסולה, אם כן \u0003אתאן לרבנן\u0004 \u0005[באנו ל\u0006שיטת \u0005חכמים],\u0006 כר' יוסי, החולקים על ר' מאיר, שסבורים שאין נעל אלא מעור!","\u0003אמר אביי\u0004 ליישב את הסתירה: \u0003מדסיפא רבנן, רישא נמי רבנן\u0004 \u0005[מ\u0006כיון \u0005שסופה\u0006 של המשנה כדברי \u0005חכמים, תחילתה גם כן\u0006 כדברי \u0005חכמים],\u0006 \u0003ורישא\u0004 \u0005[ותחילתה]\u0006 שהתיר בקב הקיטע, הרי זה \u0003במחופה עור\u0004 שיש בו כעין נעל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אם כן, לדעתך יש להסיק: \u0003אבל\u0004 אם \u0003אין\u0004 הקב \u0003מחופה עור מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003פסול, אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סוף]\u0006 \u0003באנפיליא של בגד\u0004 שהוא נושא רחוק יותר, \u0003ליפלוג בדידה\u0004 \u0005[שיחלק ב\u0006הלכה זו \u0005עצמה]\u0006 ויאמר: \u0003במה דברים אמורים — במחופה עור, אבל אין מחופה עור — פסול!\u0004","\u0003אלא אמר רבא\u0004 שיש ליישב את הסתירה באופן אחר: \u0003מדרישא\u0004 \u0005[מ\u0006כיון \u0005שתחילתה]\u0006 כדברי \u0003ר' מאיר, סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 כדברי \u0003ר' מאיר,\u0004 ולדעתו אין צורך שהנעל תהיה מעור דווקא, וההבדל בין קב לאנפיליא הוא זה: \u0003האי\u0004 \u0005[זה],\u0006 הקב — \u0003מגין\u0004 (מגן) על הרגל, \u0003והאי\u0004 \u0005[וזה] —\u0006 \u0003לא מגין\u0004 על הרגל, שהרי אין לו סוליה קשה. ואין נעל אלא זו המגינה על הרגל.","כיון שהבאנו ברייתא זו מביאים מה ש\u0003אמר אמימר: האי מאן דחליץ\u0004 \u0005[מי שחולץ]\u0006 ליבמה, \u0003צריך למדחסיה לכרעיה\u0004 \u0005[ללחוץ את רגלו]\u0006 בקרקע, וכך תחלוץ לו היבמה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין עומד בין יושב בין מוטה\u0004 ומוטה אינו יכול בקלות ללחוץ רגלו! ומשיבים לו: \u0003אימא\u0004 \u0005[אמור]\u0006 והוסף על הברייתא: \u0003ולעולם\u0004 אין החליצה מתקיימת בכל המצבים הללו אלא \u0003דדחיס לכרעיה\u0004 \u0005[\u0006כ\u0005שלוחץ את רגלו]\u0006 בארץ.","\u0003ואמר אמימר\u0004 עוד בענין זה: \u0003האי מאן דמסגי על ליחתא דכרעיה, לא חליץ\u0004 \u0005[מי שהולך על אחורי רגליו,\u0006 שרגלו הפוכה, \u0005אינו חולץ].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סמוכות הרגלים,\u0004 כלומר, מי שאינו יכול להלך על כפות רגליו ושם סמוכות על ברכיו והולך עליהן, ושוקיו נגררים מאחור, אפשר לחלוץ בהן, \u0003לאו דחליץ בה איהו\u0004 \u0005[\u0006האם \u0005אין\u0006 הכוונה \u0005שחולץ בהן הוא,\u0006 הקיטע הזה\u0005]\u0006 בסמוכות הללו? משמע שאף רגל עקומה כזו נחשבת כרגל! ומשיבים: \u0003לא,\u0004 הכוונה היא \u0003דיהיב ליה\u0004 \u0005[ש\u0006הוא \u0005נותן\u0006 אותה, את הסמוכות הללו\u0005]\u0006 \u0003לאחר\u0004 שרגלו כתיקונה \u0003וחליץ\u0004 \u0005[וחולץ],\u0006 שאותו אדם רשאי לחלוץ בסמוכות אלה, כי גם אלה נחשבות לנעל, אבל הוא עצמו שרגלו עקומה אינו יכול לחלוץ.","\u0003אמר רב אשי: למאי דקאמר\u0004 \u0005[ל\u0006פי \u0005מה שאמר]\u0006 \u0003אמימר — לאו\u0004 \u0005[אין]\u0006 \u0003בר אובא חליץ\u0004 \u0005[חולץ]\u0006 \u0003ולאו\u0004 \u0005[ואין]\u0006 \u0003בר קיפוף חליץ\u0004 \u0005[חולץ]\u0006 ששני אלה היו ספדנים מפורסמים בדורו של רב אשי, ורגליהם נתעקמו עד שלא יכלו להלך על כפות רגליהם.","שנינו במשנה שמי שנחתכו רגליו \u0003מן הארכובה\u0004 (הברך) \u0003ולמטה,\u0004 וחלצו לו — חליצתו כשירה. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו לענין עליה לרגל, נאמר: \"שלוש \u0003רגלים\u0004 תחוג לי בשנה\" (שמות כג, יד) — ומכאן דורשים שצריך לעלות לירושלים ברגל ממש — \u0003פרט לבעלי קבין,\u0004 משמע שרגל־תותבת (\"קב\") אינה קרויה רגל!","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בענין חליצה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004וחלצה נעלו \u0003מעל רגלו\"\u0004 (דברים כה, ט), ולכן אנחנו מפרשים שלא רק ברגלו — בכף רגלו ממש — אלא גם בחלק שמעל לו, כלומר, בשוק. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיכול לחלוץ גם מעל רגלו, אם נחתכו רגליו \u0003למעלה מן הארכובה נמי\u0004 \u0005[גם כן]\u0006 יחלוץ! ומשיבים, יש לדייק: \u0003מעל\u0004 רגלו, כלומר, מעל כף הרגל, \u0003ולא מעל\u0004 ל\u0003מעל,\u0004 מן הארכובה ולמעלה, בירך, שזה למעלה מן השוק.","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי איסתוירא עד ארעא נחית\u0004 \u0005[זו, עצם העקב, יורדת עד הארץ]\u0006 ומתחברת לכף הרגל, \u0003דאי סלקא דעתך מיפסק פסיק\u0004 \u0005[שאם עולה על דעתך\u0006 לומר שהיא \u0005פסוקה\u0006 וחלוקה\u0005],\u0006 ויש עצם אחרת שם, אם כן \u0003הוה ליה איהו\u0004 \u0005[הרי\u0006 נמצא שעצם הקרסול \u0005היא]\u0006 \u0003\"מעל\" ושוקא\u0004 \u0005[והשוק]\u0006 הוא \u0003מעל\u0004 ל\u0003מעל! אמר רב אשי: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003מיפסק פסיק\u0004 \u0005[\u0006שהוא \u0005מופסק\u0006 מן השוק\u0005],\u0006 בכל זאת, \u0003כל דבהדי כרעא\u0004 \u0005[שביחד עם\u0006 כף \u0005הרגל],\u0006 \u0003ככרעא דמי\u0004 \u0005[כרגל\u0006 הוא \u0005נחשב],\u0006 ומה שנקרא \"מעל רגלו\" זה השוק, ולא הקרסול.","שנינו במשנה שמי שנחתכו רגליו \u0003מן הארכובה ולמעלה\u0004 — החליצה פסולה. משמע שרגל נחשבת רק עד השוק בלבד, ואין הירך קרויה רגל. \u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב כהנא,\u0004 נאמר: \u0003\"ובשליתה היוצאת מבין רגליה\"\u0004 (דברים כח, נז), משמע שבין הרגלים הוא עד הירכיים, מקום יציאת הוולד! \u0003אמר אביי:\u0004 הכוונה היא מבין רגליה ממש, כי \u0003בשעה ש\u0004אשה \u0003כורעת לילד — נועצת עקביה בירכותיה, ויולדת\u0004 ונמצא הוולד נראה יוצא מבין הרגלים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנאמר במפיבושת בן שאול: \u0003\"\u0004ו\u0003לא עשה רגליו ולא עשה שפמו\"\u0004 (שמואל ב', יט, כה), שלא תיקן ולא טיפל בשיער שפמו ובשיער ערוותו, משמע שגם ירך קרויה רגל! ומשיבים: דבר זה הוא \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005]\u0006 שלא רצו להשתמש במפורש במילים לא יפות. ועוד מקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנאמר: \u0003\"ויבא שאול להסך את רגליו\"\u0004 (שמואל א' כד, ג), כלומר, לעשות צרכיו, משמע שגם ירכיים קרויות רגלים! ומשיבים: גם זו \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנאמר במלך מואב \u0003\"אך מסיך הוא\u0004 את \u0003רגליו בחדר המקרה\"\u0004 (שופטים ג, כד)! ומשיבים: גם כאן \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005]\u0006 היא. ועוד מקשים ממה שנאמר בשירת דבורה אודות יעל: \u0003\"בין רגליה\u0004 כרע נפל\u0003\"\u0004 (שם ה, כז), שפירשוהו במשמעות של בעילה, ואם כן משמע שירכיים קרויות רגלים! ומשיבים: גם שם \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005]\u0006 היא.","כיון שהוזכרה יעל, מביאים את המדרש בענין זה. \u0003אמר ר' יוחנן: שבע בעילות בעל אותו רשע\u0004 (סיסרא) \u0003באותו היום\u0004 את יעל, \u0003שנאמר: \"בין רגליה כרע נפל שכב בין רגליה כרע נפל באשר כרע שם נפל שדוד\"\u0004 (שם) שכל לשון \"כריעה\", \"נפילה\" או \"שכיבה\" היא רמז לבעילה. שרצתה להחלישו על ידי כך כדי שתוכל להורגו. ושואלים: ואיך עשתה יעל דבר זה? \u0003והא קא מתהניא\u0004 \u0005[והרי\u0006 היא היתה \u0005נהנית]\u0006 \u0003מעבירה! אמר ר' יוחנן משום\u0004 (משמו של) \u0003ר' שמעון בן יוחי: כל טובתן של רשעים,\u0004 שעושים דבר הגורם לכאורה הנאה —"],["\u0003רעה היא אצל צדיקים,\u0004 שהצדיק אינו נהנה כלל מטובה זו. וראיה לדבר, ממה \u0003שנאמר\u0004 בדברי ה' ללבן: \u0003\"השמר לך פן תדבר עם יעקב מטוב עד רע\"\u0004 (בראשית לא, כד) \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רע — לחיי\u0004 \u0005[לחיים,\u0006 בסדר\u0005],\u0006 שאנחנו מבינים שהזהיר אותו ה' שלא ידבר רע ליעקב, \u0003אלא טוב — אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא? אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003טובתן של רשעים רעה היא אצל צדיקים.\u0004","ושואלים: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בדברי לבן ליעקב יש צד מגונה ומאוס כאשר הוא מדבר איתו טובות, \u0003דלמא מדכר ליה שמא\u0004 \u0005[שמא יזכיר לו שם]\u0006 של \u0003עבודה זרה\u0004 בתוך דבריו, שאף שהוא מתכוון לטובה, הרי זה פוגע ביעקב. \u0003אלא הכא\u0004 \u0005[כאן],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003רעה איכא\u0004 \u0005[יש\u0006 בכך\u0005],\u0006 והרי נהנית היא?","ומשיבים: \u0003דקא שדי\u0004 \u0005[ש\u0006הוא \u0005מטיל]\u0006 \u0003בה זוהמא\u0004 \u0005[זוהמה],\u0006 שמזהם אותה בזרעו. וזוהמה זו עושה רושם במקבל אותה, שכך גם \u0003אמר ר' יוחנן: בשעה שבא נחש על חוה\u0004 (וכך פירשו \"הנחש השיאני\". בראשית ג, יג — לשון אישות), \u0003הטיל בה זוהמא\u0004 וזוהמה זו נשארה בבני האדם, ומזהמת את נפשם, ו\u0003ישראל שעמדו על הר סיני — פסקה זוהמתן\u0004 שניטלה מהם אותה זוהמה של נחש, \u0003גוים שלא עמדו\u0004 אז \u0003בהר סיני\u0004 במתן תורה — \u0003לא פסקה זוהמתן.\u0004","שנינו במשנה: אם \u0003חלצה במנעל שאינו שלו\u0004 — החליצה כשירה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"...וחלצה \u0003נעלו\u0004 מעל רגלו...\" (דברים כה, ט) — \u0003אין לי אלא\u0004 אם חלצה את \u0003נעלו\u0004 השייך לו, ואולם אם חלצה \u0003נעל של כל אדם\u0004 שהוא נעול בה, \u0003מנין\u0004 שעשתה כדין — \u0003תלמוד לומר: \"נעל\"\u0004 (\"וחלצה נעלו\") \u0003\"נעל\"\u0004 (\"חלוץ הנעל\". שם י) \u0003מכל מקום,\u0004 לרבות כל נעל.","ו\u0003אם כן, מה תלמוד לומר \"נעלו\",\u0004 המתייחס לו? — כוונתו \u0003\"נעלו\" — הראוי לו, פרט ל\u0004מנעל \u0003גדול שאין\u0004 הוא \u0003יכול להלוך בו, ופרט לקטן שאינו חופה\u0004 (מכסה) את \u0003רוב רגלו, ופרט לסנדל המסוליים ש\u0004יש לו סוליה בלבד ו\u0003אין לו עקב,\u0004 ואינו ראוי להלך בו.","מסופר: \u0003אביי הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב יוסף, אתאי\u0004 \u0005[באה]\u0006 \u0003יבמה לחלוץ. אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003הב ליה\u0004 \u0005[תן לו]\u0006 ליבם \u0003סנדלך\u0004 שיחלוץ בו, \u0003יהיב ליה סנדלא דשמאלא\u0004 \u0005[נתן לו\u0006 את \u0005הסנדל השמאלי],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אימר דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 שמותר בשל שמאל, הרי זה ב\u0003דיעבד,\u0004 אולם \u0003לכתחלה מי אמור\u0004 \u0005[האם אמרו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003סנדל שאין שלו נמי\u0004 \u0005[גם כן],\u0006 \u0003אימר דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 שאפשר לחלוץ בו ב\u0003דיעבד,\u0004 אולם \u0003לכתחלה מי אמור\u0004 \u0005[האם אמרו]\u0006 שמותר לחלוץ בשאינו שלו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003הכי קאמינא לך\u0004 \u0005[כך אני אמרתי לך,\u0006 לזאת היתה כוונתי\u0005]:\u0006 \u0003הב ליה ואקני ליה\u0004 \u0005[תן לו\u0006 את סנדלך ו\u0005הקנה לו\u0006 אותו לפי שעה\u0005]\u0006 שיהא שלו, ועל ידי כך ייעשה הדבר באופן שיהיה כשר לכתחילה.","שנינו במשנה שאם חלצה ב\u0003סנדל של עץ\u0004 — החליצה כשירה. ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר שמואל:\u0004 דעת \u0003ר' מאיר היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הקיטע יוצא בקב שלו\u0004 בשבת, אלו \u0003דברי ר' מאיר,\u0004 משמע שלדעתו הקב, רגל העץ, חשובה כנעל. ו\u0003ר' יוסי אוסר.\u0004 ואילו \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל אומר:\u0004 שכאן מדובר \u0003ב\u0004סנדל עץ ה\u0003מחופה עור, ו\u0004אם כן הלכה זו \u0003דברי הכל\u0004 היא, שגם ר' יוסי מסכים שזה קרוי סנדל.","\u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: סנדל המוסגר\u0004 שנראה בו נגע צרעת, אבל עדיין לא החליט הכהן שהוא טמא ממש, אלא שנמצא בשבוע של הסגר — \u0003לא תחלוץ בו\u0004 אשה, \u0003ואם חלצה — חליצתה כשרה. סנדל המוחלט\u0004 שפסקו שיש בו נגע צרעת — \u0003לא תחלוץ בו, ואם חלצה — חליצתה פסולה.\u0004 כיון שהסנדל עומד לשריפה, הרי זה כאילו הוא כבר שרוף, ואין בו ממש.","ואילו \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אחד סנדל המוסגר ואחד סנדל המוחלט — לא תחלוץ בו\u0004 לכתחילה, \u0003ואם חלצה\u0004 בו — \u0003חליצתה כשרה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003בית המוסגר\u0004 שנראה בו כנגע צרעת והסגירו את הבית עד שיתברר אם נגע הוא או לא — הרי הוא \u0003מטמא מתוכו,\u0004 שאם נוגעים בתוכו הוא מטמא, ואם היה זה בית ש\u0003מוחלט\u0004 כנגוע בצרעת — הרי הוא מטמא \u0003מתוכו ומאחוריו, וזה וזה מטמאין בביאה,\u0004 שאם בא אדם לתוך בית זה הרי הוא נטמא, אפילו כשאינו נוגע בקירות.","\u0003ואי סלקא דעתך כדמכתת דמי\u0004 \u0005[ואם עולה על דעתך\u0006 לומר שדבר שהוא מוחלט בצרעת \u0005נחשב כ\u0006אילו \u0005ש\u0006היה \u0005כתות\u0006 ושבור\u0005] —\u0006 \u0003והא בעינן\u0004 \u0005[והרי אנו צריכים]\u0006 שיתקיים בו: \u0003\"והבא אל הבית...\u0004 יטמא\u0003\"\u0004 (ויקרא יד, מו) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי לשיטה זו הבית נחשב כאילו לא היה קיים!","ומשיבים: \u0003שאני התם, דאמר קרא\u0004 \u0005[שונה שם, שאמר הכתוב]:\u0006 \u0003\"ונתץ את הבית\"\u0004 (שם, מה), ללמד ש\u0003אפילו בשעת נתיצה\u0004 עדיין הוא \u0003קרוי בית,\u0004 עד שייהרס ממש.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: \u0003מטלית שיש בו שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות, שיש בה נגע צרעת, \u0003אף על פי שאין בו\u0004 שיעור נפח \u0003כזית, כיון שנכנס רובה\u0004 של מטלית \u0003לבית טהור — טמאתהו\u0004 כדין מצורע. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר במטלית \u0003מוחלטת\u0004 בנגע צרעת, ומשמע שאנחנו מחשיבים את שיעורה, אפילו כשהיא מוחלטת ומיועדת לשריפה! ודוחים: \u0003לא,\u0004 מדובר פה במטלית \u0003מוסגרת.\u0004","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך\u0006 אתה מפרש, \u0005אמור\u0006 את \u0005סופה]\u0006 של אותה הברייתא: \u0003היו בה\u0004 במטלית שיעור \u0003כמה זיתים, כיון שנכנס ממנה כזית\u0004 (אפילו אם זה מיעוט המטלית) \u0003לבית טהור — טמאתהו,\u0004 ומעתה","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר במטלית \u0003מוחלטת — היינו דאיתקש\u0004 \u0005[הרי זה\u0006 משום \u0005שהוקש,\u0006 הושווה\u0005]\u0006 מצורע מוחלט \u0003למת,\u0004 וכיון שכך, כל כזית ממנה מטמא. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר במטלית \u0003מוסגרת, אמאי איתקש\u0004 \u0005[מדוע הוקש,\u0006 הושווה\u0005]\u0006 \u0003למת?\u0004 וכדי שתטמא צריך שתיכנס המטלית כולה או רובה!","ומשיבים: אכן, מדובר במטלית מוחלטת, ובכל זאת מחשיבים שיש בה שיעור, אולם \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 דין בגד שיש בו נגע, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושרף את הבגד\"\u0004 (שם יג, נב), לומר ש\u0003אפילו בשעת שריפה קרוי\u0004 עדיין \u0003בגד.\u0004","ושואלים: אם כן, \u0003וליגמר מיניה\u0004 \u0005[ונלמד ממנו]\u0006 גם לגבי סנדל ושאר דברים, שגם לאחר שהוחלט כנגוע בצרעת עדיין נשאר שמו עליו! ומשיבים: \u0003איסור מטומאה לא גמרינן\u0004 \u0005[לומדים אנו],\u0006 שהלכות טומאה שונות מהלכות איסור והיתר ואין ביניהן שוויון.","\u0003אמר רבא הלכתא\u0004 \u0005[הלכה]\u0006 היא: \u0003אחד סנדל המוסגר ואחד סנדל שמוחלט, ואחד סנדל של עבודה זרה,\u0004 כלומר, סנדל שמנעילים בו פסל של עבודה זרה — \u0003לא תחלוץ\u0004 בו אשה, \u0003ואם חלצה — חליצתה כשרה.\u0004 סנדל \u0003של תקרובת עבודה זרה,\u0004 שהביאו אותו כמתנה וקרבן לעבודה זרה,"],["\u0003ושל עיר הנדחת\u0004 שעומד לשריפה עם כל רכוש העיר, \u0003ו\u0004כן סנדל \u0003של זקן העשוי לכבודו,\u0004 כלומר, שהוא מיועד להלביש אותו במותו ואינו עשוי להילוך — \u0003לא תחלוץ\u0004 בו אשה, \u0003ואם חלצה — חליצתה פסולה\u0004 שאינו נחשב לנעל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 סנדל של \u0003זקן העשוי לכבודו\u0004 שאנחנו אומרים שאף על פי שזה סנדל ההולם את מידת הרגל אינו כשר לחליצה משום \u0003דלאו להילוכא עביד\u0004 \u0005[שאיננו עשוי ל\u0006שם \u0005הילוך]\u0006 בו, אלא רק להנעלה לאחר מיתה, אם כן סנדל \u0003דבי דינא\u0004 \u0005[של בית דין],\u0006 שהיה שמור בבית הדין סנדל מיוחד לחליצות, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו להילוכא עביד\u0004 \u0005[לא להילוך\u0006 הוא \u0005עשוי]\u0006 אלא רק לחליצה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש להבדיל: \u0003אילו\u0004 בכל זאת \u0003מסגי ביה שלוחא דבי דינא\u0004 \u0005[\u0006היה \u0005הולך בו שליח בית הדין],\u0006 \u0003מי קפיד עליה דיינא\u0004 \u0005[האם\u0006 היה \u0005מקפיד עליו הדיין]?\u0006 משמע שסנדל זה של בית הדין, שנועד לחליצה, אפשר להשתמש בו להליכה, מה שאין כן דבר הנועד למת שאסור להשתמש בו לכל שימוש אחר.","\u0003חלצה בלילה — חליצתה כשרה, ור' אלעזר פוסל.\u0004 חלצה \u0003ב\u0004רגל \u0003שמאל — חליצתה פסולה, ור' אלעזר מכשיר.\u0004","על אף האמור במשנה מציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005ב\u0006בעיה \u0005זו נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' אלעזר\u0005]\u0006 \u0003סבר\u0004 כי \u0003מקשינן\u0004 \u0005[מקישים,\u0006 משווים \u0005אנו]\u0006 דיני \u0003ריבים,\u0004 כלומר, דיני ממונות (וחליצה בכלל זה, שהרי יש בה צד ממון של תשלום כתובה לאלמנה) \u0003ל\u0004דיני \u0003נגעים,\u0004 וכפי שדיני נגעים אינם נידונים אלא ביום (כפי שנאמר בכתוב: \"וביום הראות בו בשר חי יטמא\". ויקרא יג, יד ועוד) — אף ריבים, כלומר, דינים אחרים, אינם נערכים אלא ביום. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר\u0004 ש\u0003לא מקשינן\u0004 \u0005[מקישים אנו]\u0006 \u0003ריבים לנגעים?\u0004","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לא מקשינן\u0004 \u0005[מקישים,\u0006 משווים \u0005אנו]\u0006 \u0003ריבים לנגעים, דאי מקשינן\u0004 \u0005[שאם\u0006 היינו באמת \u0005מקישים\u0006 לגמרי\u0005],\u0006 הרי אז, \u0003אפילו גמר דין בלילה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 היו עושים, ואנחנו יודעים שגומרים דיני ממונות בלילה, אף שיש להתחיל ביום דווקא, \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 לענין חליצה בלילה \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006בעיה \u0005זו נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר\u0005]\u0006 \u0003סבר\u0004 ש\u0003חליצה כתחלת דין דמיא\u0004 \u0005[נחשבת]\u0006 ותחילת דין עושים רק ביום, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר\u0004 ש\u0003חליצה כגמר דין דמיא\u0004 \u0005[נחשבת]\u0006 ולכן אפשר לעשותה גם בלילה.","מסופר: \u0003רבה בר חייא קטוספאה\u0004 (מאקטיספון) \u0003עבד עובדא\u0004 \u0005[עשה מעשה]\u0006 של חליצה \u0003במוק\u0004 (נעל־בית שאינה של עור), \u0003וביחידי,\u0004 שהוא היה הדיין היחידי, \u0003ובלילה. אמר שמואל\u0004 בליגלוג: \u0003כמה רב גובריה\u0004 \u0005[גדול כוחו]\u0006 של חכם זה \u0003דעביד כיחידאה\u0004 \u0005[שעשה כ\u0006דעת \u0005יחיד],\u0006 שבמעשה שעשה סמך על דברי יחידים, הדחויים מן ההלכה.","ושואלים: \u0003מאי קשיא\u0004 \u0005[מה\u0006 היה \u0005קשה לו]\u0006 לשמואל במעשה זה? \u0003אי\u0004 \u0005[אם]\u0006 מה שחלץ ב\u0003מוק,\u0004 הלא \u0003סתמא תניא\u0004 \u0005[סתם\u0006 ברייתא \u0005שנויה]\u0006 שכשר, ואין זו, איפוא, דעת יחיד. \u0003אי\u0004 \u0005[אם]\u0006 מה שחלץ ב\u0003לילה — סתמא תניא\u0004 \u0005[סתם\u0006 ברייתא \u0005שנויה]\u0006 שכשר.","\u0003אלא\u0004 מה שעשה כן כדיין \u0003יחידי קא קשיא ליה\u0004 \u0005[היה קשה לו]:\u0006 \u0003היכי עביד\u0004 \u0005[כיצד עשה]\u0006 \u0003ביחידי,\u0004 שהרי זו הלכה \u0003דיחידאה קתני לה\u0004 \u0005[שיחיד שנה אותה].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלצה בשנים או בשלשה ונמצא אחד מהן קרוב או פסול\u0004 — \u0003חליצתה פסולה. ור' שמעון ור' יוחנן הסנדלר מכשירים,\u0004 שהם סבורים שאף שלא נותרו אלא שנים כשרים, מכל מקום, לדעתם, חליצה בפני שניים כשרה. \u0003ומעשה באחד שחלץ בינו לבינה בבית האסורים\u0004 ולא היה שם דיין, \u0003ובא מעשה לפני ר' עקיבא והכשיר.\u0004","\u0003ואמר רב יוסף בר מניומי אמר רב נחמן: אין הלכה כאותו הזוג,\u0004 כר' שמעון ור' יוחנן הסנדלר, ואילו רבה בר חייא סמך דווקא על דעת היחיד של ר' עקיבא, המתיר לחלוץ ביחידי. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לא רק פרט זה הוא כדעת יחיד אלא \u0003כולהו נמי יחידאה קתני להו\u0004 \u0005[כולם גם כן יחיד שנה אותם].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל בר' יוסי: אני ראיתי את ר' ישמעאל בן אלישע שחלץ במוק, ביחידי, ובלילה.\u0004 משמע שדברים אלה הם דעתו בלבד, שלא כשאר החכמים.","שנינו במשנה שאם חלצה \u0003ב\u0004רגל \u0003שמאל חליצתה\u0004 פסולה, ור' אליעזר מכשיר. ושואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם\u0006 לשיטתם \u0005של חכמים]?\u0006 \u0003אמר עולא: ילפינן\u0004 \u0005[לומדים אנו]\u0006 בגזירה שווה של המילים \u0003\"רגל\"\u0004 (האמורה כאן) ו\u0003\"רגל\"\u0004 האמורה ב\u0003מצורע, מה להלן,\u0004 במצורע, \"רגל\" זו האמורה, היא של \u0003ימין\u0004 כמפורש שם (ויקרא יד, יד), \u0003אף כאן,\u0004 בחליצה, הכוונה לרגל \u0003ימין.\u0004","ושואלים: \u0003ו\u0004כי \u0003ר' אלעזר לא יליף\u0004 \u0005[לומד]\u0006 גזירה שווה זו של \u0003\"רגל\" \"רגל\" ממצורע? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: מנין לרציעה\u0004 של עבד נרצע \u0003שהיא\u0004 נעשית \u0003באזן הימנית\u0004 דווקא? \u0003נאמר כאן\u0004 בדיני נרצע \u0003\"אזן\", ונאמר להלן\u0004 בדיני צרעת \u0003\"אזן\", מה להלן\u0004 בצרעת, הכוונה לאוזן \u0003ימין,\u0004 כמפורש (שם), \u0003אף כאן\u0004 ברציעה הכוונה ודאי לאוזן \u0003ימין,\u0004 משמע שהוא לומד גזירה שווה ממצורע!","\u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: מוחלפת השיטה,\u0004 כלומר, צריך להחליף את הדעות במשנתנו, ולומר שר' אלעזר הוא הפוסל בשמאל.","\u0003רבא אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך],\u0006 כי המילים \u0003\"אזן\" \"אזן\" מופני\u0004 \u0005[מופנות,\u0006 מיותרות\u0005]\u0006 בפסוק, ללמדנו גזירה שווה זו, ואילו המלים \u0003\"רגל\" \"רגל\" — לא מופני\u0004 \u0005[מופנות],\u0006 שהרי בענין יבמה נצרכת המלה לעניינה, ולכן אין זו גזירה שווה גמורה.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 המילים \u0003לא מופני\u0004 \u0005[מופנות]\u0006 \u0003מאי פירכא איכא\u0004 \u0005[מה פירכה,\u0006 קושיה, \u0005יש\u0006 בדבר\u0005],\u0006 שהרי גזירה שווה המופנה רק מצד אחד, אם יש מקום לפירכה, להראות שאין הדינים דומים דוחים אותה, אך אם אין כל פירכה, גם גזירה שווה המופנה רק מצד אחד — גזירה שווה היא, ומה הפירכה כאן? ומסבירים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 להקשות\u0005]:\u0006 \u0003מה למצורע\u0004 שדינו ברגל ימין, משום שיש בו עוד דינים מיוחדים בטהרתו, \u0003שכן טעון\u0004 (הוא חייב, לשם טהרתו, שייזרק עליו מדם הקרבן), ב\u0003עץ ארז ואזוב ושני תולעת,\u0004 ולכן אפשר לומר שהקפידה תורה גם על רגל ימין, מה שאין כן בחליצה — שמא גם צד שמאל כשר.","\u0003חלצה ורקקה\u0004 כדין, \u0003אבל לא קראה\u0004 את מה שהיתה צריכה לומר — \u0003חליצתה כשרה. קראה ורקקה אבל לא חלצה — חליצתה פסולה. חלצה וקראה אבל לא רקקה — ר' אלעזר אומר: חליצתה פסולה, ר' עקיבא אומר: חליצתה כשרה.\u0004"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר,\u0004 הלא נאמר: \u0003\"ככה יעשה\u0004 לאיש אשר לא יבנה את בית אחיו\u0003\"\u0004 (דברים כה, ט), ו\"ככה\" לשון דיוק ועיכוב הוא, כלומר, שרק כך כשר. ונלמד מכאן כי \u0003כל דבר שהוא מעשה — מעכב. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא:\u0004 וכי אתה מביא \u0003משם ראיה?\u0004 הלא נאמר \u0003\"ככה יעשה לאיש\",\u0004 כלומר, \u0003כל דבר שהוא מעשה באיש,\u0004 דברים שעושים בגופו של האיש כגון החליצה, אבל היריקה שאיננה באיש אלא רק לפניו — איננה מעכבת.","ועוד בענין חליצה, \u0003החרש שנחלץ והחרשת שחלצה, ו\u0004כן הגדולה ש\u0003חולצת לקטן — חליצתה פסולה,\u0004 ואיננה מועילה לפטור. \u0003קטנה שחלצה — תחלוץ\u0004 שנית \u0003משתגדיל, ואם לא חלצה — חליצתה\u0004 הראשונה \u0003פסולה. חלצה בשנים\u0004 בפני שני דיינים, \u0003או ב\u0004פני \u0003שלשה, ונמצא אחד מהן קרוב או פסול\u0004 מצד אחר להיות דיין — \u0003חליצתה פסולה. ר' שמעון ור' יוחנן הסנדלר מכשירין. ומעשה באחד שחלץ בינו לבינה בבית האסורים,\u0004 שלא בנוכחות דיינים, \u0003ובא מעשה\u0004 זה \u0003לפני ר' עקיבא והכשיר.\u0004","על האמור במשנה \u0003אמר רבא: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 כי \u0003קריאה לא מעכבא\u0004 \u0005[מעכבת]\u0006 את חלות החליצה, ואף שלא קראה — אין הקריאה מעכבת, \u0003לפיכך, אלם ואלמת שחלצו — חליצתן כשירה.\u0004 שאף שלכתחילה צריך לומר דברים, מכל מקום אין הדיבור מעכב.","ומקשים: והלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חרש שנחלץ, והחרשת שחלצה, והחולצת מן הקטן — חליצתה פסולה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שהחליצה פסולה — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום\u0004 ש\u0003לא בני קרייה\u0004 \u0005[קריאה]\u0006 \u0003נינהו\u0004 \u0005[הם],\u0006 שאינם מסוגלים לקרוא את מה שאומרים בחליצה ומדובר בחרש שאינו מדבר, ואם כן רואים מכאן שקריאה מעכבת! ודוחים: \u0003לא,\u0004 הטעם בחרש וחרשת הוא \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003בני דעה נינהו\u0004 \u0005[הם],\u0006 וכיון שאין בהם דעת, אין מעשיהם נחשבים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אלם ואלמת נמי\u0004 \u0005[גם כן]\u0006 נאמר שאינם בני דעת! \u0003אמר רבא: אלם ואלמת בני דעה נינהו\u0004 \u0005[הם],\u0006 \u0003ו\u0004אין בהם חסרון אלא ש\u0003פומייהו\u0004 \u0005[פיהם]\u0006 \u0003הוא דכאיב להו\u0004 \u0005[שכואב להם],\u0006 כלומר, יש להם חסרון בכלי הביטוי, שאינם יכולים לדבר, אבל אין זה חסרון בדעתם, ולכן ראויים הם לחלוץ.","וחוזרים ומקשים: \u0003והא אמרי דבי\u0004 \u0005[והרי אומרים\u0006 חכמים מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי\u0004 שחרש וחרשת פסולים \u0003לפי שאינו ב\"אמר\"\u0004 הוא (\"ועמד ואמר לא חפצתי לקחתה\". דברים כה, ח), ולא בכלל \u0003\"ואמרה\"\u0004 היא (\"ואמרה מאן יבמי להקים לאחיו שם בישראל\". שם ז), ולא משום חסרון דעת! \u0003אלא\u0004 יש לחזור מדברים אלה ולומר אחרת: \u0003כי אתמר\u0004 \u0005[כאשר,\u0006 מה, \u0005שנאמר]\u0006 בשם \u0003רבא\u0004 — \u0003אסיפא אתמר\u0004 \u0005[על סופה\u0006 של המשנה \u0005נאמר],\u0006 ששנינו: \u0003חרש שנחלץ, והחרשת שחלצה, והחולצת מן הקטן — חליצתה פסולה.\u0004","\u0003אמר רבא: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר],\u0006 כלומר, כיון שאפשר להסיק מכאן ש\u0003קרייה מעכבא\u0004 \u0005[\u0006ש\u0005קריאה מעכבת],\u0006 \u0003לפיכך אלם ואלמת שחלצו — חליצתן פסולה. ו\u0004צריך להסביר כך: \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 ששנינו בה בראשה שקריאה אינה מעכבת, ועם זאת חליצה של מי שאינו יכול לקרוא פסולה היא — יש להבינה \u0003כ\u0004שיטת \u0003ר' זירא.\u0004","ש\u0003אמר ר' זירא: כל הראוי לבילה,\u0004 כלומר, קרבן מנחה, שצריך לבלול אותו בשמן, והוא ראוי מבחינת הכמות שיבללו אותו — \u0003אין בילה מעכבת בו,\u0004 שאם לא בלל — לא פסל. \u0003וכל שאין ראוי לבילה,\u0004 כגון שיש כמות מרובה מדי, שאינה יכולה להיבלל — \u0003בילה מעכבת\u0004 בו ופסול. ומכאן למדים הלכה כללית, שיש דברים שעשייתם בפועל איננה מעכבת כל עוד הם ראויים ומסוגלים לכך, ורק אם אינם ראויים — הרי זה מעכב. וגם בענייננו, אף שקריאה אינה מעכבת, מכל מקום חליצת אילם פסולה, משום שאינו מסוגל כלל לקריאה.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 מארץ ישראל \u0003לאבוה\u0004 \u0005[לאביו]\u0006 של \u0003שמואל\u0004 את ההוראה: \u0003יבמה\u0004 כיון \u0003שרקקה — תחלוץ\u0004 ולא תתייבם. ומעירים: \u0003מכלל\u0004 הדברים אתה למד \u0003דאיפסלא\u0004 \u0005[שנפסלה]\u0006 \u0003לה\u0004 על כל פנים \u0003מ\u0004ן ה\u0003אחין,\u0004 שאף שרקיקה בלבד איננה מועילה כדי לפוטרה, מכל מקום יפה כוחה של הרקיקה כדי לפסול אותה לאחים, ולכן תחלוץ ולא תתייבם.","ושואלים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 הלכה זו\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא שיטת \u0003ר' עקיבא, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה במקום מצוה\u0004 של חליצה, שבהקשר כזה צוותה התורה לרקוק, \u0003דאיכא למימר מידי דהוה\u0004 \u0005[שיש\u0006 מקום \u0005לומר שהדבר\u0006 דומה \u0005הוא]\u0006 ל\u0003אימורים\u0004 (החלב ושאר החלקים העולים למזבח), \u0003דכי ליתנהו\u0004 \u0005[שכאשר אינם\u0006 נמצאים כלל\u0005],\u0006 שאבדו מן העולם — \u0003לא מעכבי\u0004 \u0005[אינם מעכבים]\u0006 את הקרבן, והמקריב יוצא ידי חובה בזריקת הדם בלבד, והכהנים מקבלים ממנו את חלקם,","\u0003וכי איתנהו\u0004 \u0005[וכאשר\u0006 הם \u0005נמצאים]\u0006 ונטמאו, או אירע בהם פסול אחר — \u0003מעכבי\u0004 \u0005[\u0006הרי הם \u0005מעכבים]\u0006 ואין הכהנים זוכים בחלקם עד שיוקטרו האימורים, ובכל זאת","\u0003אמר ר' עקיבא\u0004 שהרקיקה \u0003לא מעכבא\u0004 \u0005[מעכבת]\u0006 את החליצה, וסבור שאם לא רקקה, נפטרת בחליצה בלבד, וכיון שהוא סבור שאין הרקיקה חשובה, וכי ברקיקה זו בלבד \u0003מאחין איפסלא\u0004 \u0005[נפסלה\u0006 מייבום \u0005לאחים]?\u0006","\u0003ואלא\u0004 תאמר שהלכה זו \u0003ל\u0004שיטת \u0003ר' אלעזר,\u0004 שרקיקה מעכבת —","\u0003והא\u0004 \u0005[והרי]\u0006 לשיטתו חליצה ורקיקה \u0003שני דברים המתירין נינהו\u0004 \u0005[הם],\u0006 \u0003ו\u0004כלל הוא בדיני קרבנות: \u0003שני דברים המתירין — אין מעלין\u0004 ומקדשים את הקרבן \u0003זה בלא זה.\u0004 וכיוצא בו אינו מועיל בחליצה, אם רקקה בלבד, שהרי עשתה רק דבר אחד משני דברים שיש לעשותם!","\u0003אלא\u0004 יש לומר שהלכה זו \u0003כ\u0004שיטת \u0003רבי\u0004 היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כבשי עצרת\u0004 שהם קרבן שלמים מיוחד, הבא בחג השבועות עם שתי הלחם — \u0003אין מקדשין\u0004 את \u0003הלחם אלא בשחיטה,\u0004 ששחיטת הכבשים גורמת שיתקדש הלחם.","\u0003כיצד?\u0004 אם \u0003שחטן\u0004 את הכבשים הללו \u0003לשמן, וזרק דמן לשמן — קדש הלחם,\u0004 ואם \u0003שחט שלא לשמן,\u0004 כגון שאמר שמתכוון לשם קרבן אחר, \u0003ו\u0004אפילו \u0003זרק\u0004 לאחר מכן את הדם \u0003לשמן — לא קדש הלחם,\u0004 ואם \u0003שחטן לשמן וזרק דמן שלא לשמן — קדוש ואינו קדוש,\u0004 כלומר, קדוש במקצת, אלו \u0003דברי רבי.\u0004","\u0003ר' אלעזר בר' שמעון אומר: לעולם אינו קדוש\u0004 כלל \u0003עד שישחוט לשמן ויזרוק דמן לשמן.\u0004 ואם כן שיטת רבי היא שאף על פי שהקדושה חלה על הלחם על ידי שחיטה וזריקה, אם השחיטה בלבד היתה כראוי — יש בה כוח מספיק כדי להחיל קדושה מסויימת. וכן בענין החליצה, שאף שיש צורך ברקיקה וחליצה, אף רקיקה בלבד מועילה כדי לפסול את היבמה מן האחים.","על סיכום זה של הדברים שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' עקיבא\u0004 כי \u0003רקיקה\u0004 לעצמה \u0003לא פסלה\u0004 \u0005[פוסלת]\u0006 את היבמה מן האחים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חלצה ולא\u0004"],["\u0003רקקה ולא קראה — חליצתה כשירה,\u0004 ואם \u0003רקקה ולא חלצה ולא קראה — חליצתה פסולה. קראה ולא רקקה ולא חלצה — אין כאן בית מיחוש.\u0004 כלומר, אין בכך כלום ואין בכך משום חליצה.","ונברר, \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא כדעת \u0003ר' אליעזר,\u0004 וכי \u0003חלצה ולא רקקה ולא קראה חליצתה כשירה? והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אליעזר:\u0004 הכתוב \u0003\"ככה יעשה\"\u0004 מלמד, שכ ל\u0003דבר שהוא מעשה מעכב,\u0004 וכיון שלא רקקה, הרי זה מעכב! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהוא כדעת \u0003ר' עקיבא, וקתני\u0004 \u0005[ושנה]\u0006 שם בסוף הברייתא \u0003רקקה ולא חלצה ולא קראה — חליצתה פסולה.\u0004 ונברר, \u0003למאן\u0004 \u0005[למי]\u0006 היא פסולה?","\u0003אילימא לעלמא\u0004 \u0005[אם תאמר לכל]\u0006 להתירה לכל אדם, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שחליצתה פסולה! שהלא \u0003מי הויא\u0004 \u0005[האם היתה]\u0006 בכלל \u0003חליצה, דאישתריא לעלמא\u0004 \u0005[שתותר לכול]?\u0006 \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא שפסולה גם \u0003לאחין,\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שגם ר' עקיבא סבור שרקיקה זו פוסלת.","ושואלים: \u0003ול\u0004שיטת \u0003ר' עקיבא\u0004 שהדבר המעכב בחליצה הוא רק מה שנעשה באיש עצמו, \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003רקיקה ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003קרייה\u0004 (קריאה), שאם שתיהן אינן מעכבות, מדוע אם רקקה ולא חלצה הרי זו פסולה לאחים, ואם קראה ולא חלצה אין כאן בית מיחוש?","ומשיבים: \u0003קרייה, דאיתא\u0004 \u0005[קריאה, שישנה]\u0006 במהלך הייבום \u0003בין בתחלה\u0004 לפני החליצה \u0003בין בסוף — לא מיחלפא ליה\u0004 \u0005[אינה מתחלפת לו]\u0006 לאדם בחלוצה ממש, שיודע שאולי קראה ולא הגיעה לידי חליצה. אבל \u0003רקיקה,\u0004 ש\u0003בתחלה ליתא\u0004 \u0005[איננה]\u0006 \u0003ולבסוף איתא\u0004 \u0005[ישנה],\u0006 שכן כך הוא הסדר, שקודם חולצת ואחר כך רוקקת — \u0003מיחלפא ליה\u0004 \u0005[מתחלפת לו]\u0006 לאדם באשה שחלצו לה כדין, \u0003ו\u0004אם יתירו אותה להתייבם לאחים \u0003אתו למישרי\u0004 \u0005[יבואו להתיר]\u0006 גם \u0003חלוצה\u0004 גמורה \u0003לאחין.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 כי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 לאביו של שמואל: \u0003יבמה שרקקה\u0004 לפני החליצה — \u0003תחלוץ, ואינה צריכה לרוק פעם אחרת. כי ההיא דאתיא לקמיה\u0004 \u0005[כמו אותה\u0006 אשה \u0005שבאה לפני]\u0006 \u0003ר' אמי\u0004 לחליצה, כאשר \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ר' אבא בר ממל קמיה\u0004 \u0005[לפניו]\u0006 באותו מעמד. \u0003רקקה\u0004 אותה אשה \u0003מקמי דתחלוץ\u0004 \u0005[לפני שחלצה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: חלוץ לה,\u0004 כלומר, אמור לה שתחלוץ, \u0003ושרי לה תיגרא\u0004 \u0005[והתר\u0006 את \u0005עסקיה]\u0006 ופטור אותה מבית הדין, שאינה צריכה עוד דבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא: והא בעינן מירק\u0004 \u0005[הרי אנו צריכים\u0006 בחליצה \u0005לירוק]!\u0006 ענה לו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רקקה לה\u0004 כבר. אמר לו ר' אבא: \u0003ותירוק\u0004 פעם נוספת, \u0003ומה בכך?\u0004 ענה לו: \u0003נפיק מיניה חורבא\u0004 \u0005[\u0006יכול ש\u0005יצא מזה חורבן,\u0006 נזק\u0005],\u0006 \u0003דאי אמרת תיהדר\u0004 \u0005[שאם אומר אתה\u0006 ש\u0005תחזור]\u0006 \u0003ותירוק, אמרי\u0004 \u0005[\u0006יהיו אנשים \u0005אומרים]\u0006 כי \u0003רקיקה קמייתא\u0004 \u0005[ראשונה]\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה מששא\u0004 \u0005[ממש]\u0006 ומותרת לאחים, \u0003ואתי למישרי\u0004 \u0005[ויבואו להתיר]\u0006 גם \u0003חלוצה\u0004 שרקקה אחרי החליצה \u0003לאחין.\u0004 שכשיראו אותה יורקת בפעם הראשונה יאמרו שוודאי חלצה קודם לכן.","וחזר והקשה: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 לעשות המעשים \u0003כסדרן,\u0004 שקודם תהיה חליצה ואחר כך רקיקה! ענה לו: \u0003כסדרן לא מעכבא\u0004 \u0005[מעכב].\u0006 \u0003הוא\u0004 ר' אבא בר ממל \u0003סבר: דחויי קא מדחי ליה\u0004 \u0005[מדחה\u0006 הוא \u0005אותו]\u0006 בתירוצים דחוקים כדי להצדיק את דבריו, אבל אינם מבוססים כל כך. \u0003נפק, דק ואשכח\u0004 \u0005[יצא\u0006 מבית המדרש ו\u0005דקדק\u0006 בדברים \u0005ומצא]\u0006 כדברי ר' אמי, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין שהקדים חליצה לרקיקה, בין שהקדים רקיקה לחליצה — מה שעשה עשוי.\u0004","אגב כך מביאים סיפור הקשור לנושא זה: \u0003לוי נפק לקרייתא\u0004 \u0005[יצא לכפרים]\u0006 ללמד תורה לאנשים. \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 כמה שאלות: \u0003גידמת,\u0004 שנקטעו ידיה \u0003מהו\u0004 הדין, האם יכולה היא \u0003שתחלוץ?\u0004 וכן \u0003יבמה שרקקה\u0004 לא רוק אלא \u0003דם, מהו\u0004 הדין, האם החליצה כשירה? וכן שאלו את פירוש הכתוב: \u0003\"אבל אגיד לך את הרשום בכתב אמת\"\u0004 (דניאל י, כא) — \u0003מכלל\u0004 הדברים אפשר להסיק לכאורה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כתב\u0004 בשמים \u0003שאינו אמת?\u0004","\u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 כל תשובה לשאלות הללו. \u0003אתא שאיל בי מדרשא\u0004 \u0005[בא\u0006 ו\u0005שאל\u0006 ב\u0005בית המדרש],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בתשובה לשאלה הראשונה: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"וחלצה ביד\"?\u0004 מכאן, שיכולה לחלוץ בכל דרך. \u0003ומי כתיב\u0004 \u0005[והאם נאמר]\u0006 \u0003\"וירקה רוק\"?\u0004 — הלא נאמר רק \"וירקה\". ולכן גם ביריקת דם, החליצה כשירה.","ובענין הפסוק: \u0003\"אבל אגיד לך\u0004 את \u0003הרשום בכתב אמת\",\u0004 שאתה שואל, \u0003וכי יש כתב שאינו אמת?\u0004","\u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן — בגזר דין שיש עמו שבועה,\u0004 דבר כזה קרוי \"כתב אמת\", שאינו בטל לעולם. \u0003כאן — בגזר דין שאין עמו שבועה,\u0004 שייתכן שיתבטל כאשר ישתנו התנאים.","ו\u0003כ\u0004דברי \u0003רב שמואל בר אמי.\u0004 ש\u0003אמר רב שמואל בר אמי אמר ר' יונתן: מנין לגזר דין שיש עמו שבועה שאינו מתקרע — שנאמר: \"\u0004ו\u0003לכן נשבעתי לבית עלי אם יתכפר עון בית עלי בזבח ובמנחה עד עולם\"\u0004 (שמואל א' ג, יד), ללמד, שכיון שהיתה שבועה בדבר — אין גזר הדין בטל אפילו יביאו קרבנות כפרה.","אגב הזכרת אותו פסוק מביאים מה ש\u0003אמר רבה: בזבח ובמנחה אינו מתכפר, אבל מתכפר הוא בדברי תורה. אביי אמר: בזבח ובמנחה אינו מתכפר, אבל מתכפר בגמילות חסדים.\u0004 מספרים: \u0003רבה ואביי\u0004 עצמם \u0003מדבית עלי קאתו\u0004 \u0005[באו],\u0006 \u0003רבה\u0004 ש\u0003עסק\u0004 בעיקר \u0003בתורה\u0004 — \u0003חיה ארבעין שנין\u0004 \u0005[חי ארבעים שנה],\u0006 \u0003אביי\u0004 ש\u0003עסק,\u0004 לשיטתו, גם \u0003בתורה ו\u0004גם \u0003בגמילות חסדים — חיה שיתין שנין\u0004 \u0005[חי שישים שנה],\u0006 שהאריכו ימים יותר מן הרגיל בבית עלי.","וכיוצא בו מסופר בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משפחה אחת היתה בירושלים שהיו\u0004 בניה \u0003מתים כבן שמנה עשרה שנה. באו\u0004 בני המשפחה \u0003והודיעו את רבן יוחנן בן זכאי\u0004 שכך קורה להם. \u0003אמר להם: שמא ממשפחת עלי אתם, שנאמר: \"וכל מרבית ביתך ימותו אנשים\"\u0004 (שם ב, לג), כלומר, מיד בהגיעם לבגרות שלימה, להיקרא \"אנשים\", ואם כן, יש לכם רק עצה אחת — \u0003לכו ועסקו בתורה ותחיו. הלכו ועסקו בתורה וחיו,\u0004 שהיו מאריכים ימים יותר, \u0003והיו קורין אותן \"משפחת יוחנן\" על שמו,\u0004 על שם העצה שנתן להם.","ולענין גזר דין שאינו נקרע \u0003אמר רב שמואל בר אוניא אמר רב: מנין לגזר דין של צבור שאינו נחתם?\u0004 ותוהים: \u0003אינו נחתם?! והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כי אם תכבסי בנתר ותרבי לך ברית נכתם עונך לפני\"\u0004 (ירמיהו ב, כב), משמע שאין עוד תקנה לעוון הזה!","\u0003אלא\u0004 כך צריך לומר: \u0003מנין שאפילו\u0004 אם \u0003נחתם מתקרע\u0004 על ידי תשובה — \u0003שנאמר: \"\u0004כי \u0003מי... כה' אלהינו בכל קראנו אליו\"\u0004 (דברים ד, ז), \u0003ו\u0004לכאורה \u0003הכתיב\u0004 \u0005[והרי נאמר]\u0006 בפסוק אחר: \u0003\"דרשו ה' בהמצאו\u0004 קראוהו בהיותו קרוב\u0003\"\u0004 (ישעיהו נה, ו), משמע שלא בכל זמן הוא קרוב ונענה! ויש לתרץ: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003ביחיד\u0004 צריך לדרוש את ה' בהימצאו, שלא בכל זמן הוא נמצא ונענה לקוראיו, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בציבור,\u0004 שהוא נמצא בכל עת שהציבור קוראים אליו (\"בכל קראנו אליו\").","ושואלים: \u0003יחיד,\u0004 \u0003אימת\u0004 \u0005[מתי]\u0006 הוא הזמן שה' קרוב אליו? \u0003אמר רב נחמן אמר רבה בר אבוה: אלו עשרה ימים שבין ראש השנה ליום הכפורים.\u0004","ובהמשך לשאלות ששאלו את לוי, \u0003שלחו ליה\u0004 \u0005[לו]\u0006 מארץ ישראל \u0003לאבוה\u0004 \u0005[לאביו]\u0006 של \u0003שמואל\u0004 פסק הלכה: \u0003יבמה שרקקה דם תחלוץ, לפי שאי אפשר לדם\u0004 שייצא מן הפה \u0003בלא צחצוח\u0004 (משהו) \u0003רוק,\u0004 ויוצא ידי חובה ברוק זה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003יכול, יהא דם היוצא מפיו ו\u0004כן \u0003מפי האמה\u0004 (אבר המין) של זב \u0003טמא,\u0004 ככל דבר שנובע מן הזב (\"מעינותיו\") כגון: רוקו ומי רגליו וכיוצא בהם — \u0003תלמוד לומר: \"זובו טמא\"\u0004 (ויקרא טו, ב), ללמד, שרק זובו וכיוצא בו טמא, \u0003ואין דם היוצא מפיו\u0004 או \u0003מפי האמה טמא, אלא טהור.\u0004 ומכאן שיכול לצאת דם מן הפה בלי רוק. שהרי אילו כדבריהם, שבהכרח יש בכל דם רוק, הלא היה צריך להיות טמא מחמת הרוק!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן,\u0004 בענין חליצה, שאמרנו שלא יכול לצאת דם בלי רוק הרי זה \u0003במוצצת,\u0004 שהיא מנסה למצוץ את הרוק הנמצא בפיה ולירקו, ואז יש משהו רוק בפה, ואילו \u0003כאן,\u0004 בזב, מדובר \u0003ב\u0004דם שהיה \u0003שותת\u0004 ממנו מעצמו, ואז ייתכן שלא יהיה בו רוק כלל.","שנינו במשנה ש\u0003חרש שנחלץ\u0004 או חלץ — החליצה פסולה, וכן שהחולצת לקטן חליצתה פסולה."],["\u0003אמר רב יהודה אמר רב: זו דברי ר' מאיר,\u0004 שחליצה זו יש בה ממש, אלא שהיא פסולה ואין בה כדי להתירה לשוק, \u0003אבל חכמים אומרים: אין חליצת קטן כלום.\u0004","שנינו במשנה: \u0003קטנה שחלצה\u0004 — תחלוץ משתגדיל, ואם לא עשתה כן — חליצתה פסולה. \u0003אמר רב יהודה אמר רב: זו דברי ר' מאיר,\u0004 ש\u0003אמר: \"איש\" כתוב בפרשה\u0004 (\"ואם לא יחפוץ האיש\". דברים כה, ז), משמע — מבוגר, \u0003ומקשינן\u0004 \u0005[ומקישים,\u0006 משווים \u0005אנו]\u0006 \u0003אשה לאיש,\u0004 שגם האשה צריכה להיות בוגרת בזמן החליצה.","\u0003אבל חכמים אומרים:\u0004 אמנם \u0003\"איש\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בפרשה,\u0004 ומשמע גדול דווקא, אבל \u0003אשה\u0004 החולצת, כיון שלא נאמר שם \"אשה\" אלא \"יבמה\" סתם הרי זה \u0003בין גדולה בין קטנה.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה החולקים על ר' מאיר? ומשיבים: שיטת \u0003ר' יוסי היא.\u0004 ומביאים מעשה שממנו למדים שדבר זה הוא דעת ר' יוסי. ש\u0003ר' חייא ור' שמעון בר\u0004 (בנו של) \u0003רבי הוו יתבי\u0004 \u0005[היו יושבים]\u0006 מחוץ לבית המדרש ועסקו בתורה. \u0003פתח חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003ואמר: המתפלל, צריך\u0004 בזמן התפילה, \u0003שיתן עיניו למטה,\u0004 לכיוון ארץ ישראל, משום \u0003שנאמר: \"והיו עיני ולבי שם כל הימים\"\u0004 (מלכים א', ט, ג), כלומר, שהשכינה היא בארץ ישראל, וצריך לכוון עיניו לארץ הקודש.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר,\u0004 שצריך שיתן \u0003עיניו למעלה,\u0004 לכיוון השמים, משום \u0003שנאמר: \"נשא לבבנו אל כפים\u0004 אל אל בשמים\" (איכה ג, מא). \u0003אדהכי אתא\u0004 \u0005[בינתיים בא]\u0006 \u0003ר' ישמעאל בר' יוסי לגבייהו\u0004 \u0005[אצלם].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003במאי עסקיתו\u0004 \u0005[במה עוסקים אתם]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בתפלה,\u0004 שאנחנו מתווכחים איך לעמוד בתפילה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כך אמר אבא,\u0004 ר' יוסי: \u0003המתפלל צריך שיתן עיניו למטה ולבו\u0004 יכוון \u0003למעלה, כדי שיתקיימו שני\u0004 ה\u0003מקראות הללו.\u0004","\u0003אדהכי\u0004 \u0005[בינתיים],\u0006 עד שהם משוחחים, \u0003אתא\u0004 \u0005[בא,\u0006 נכנס\u0005]\u0006 \u0003רבי למתיבתא\u0004 \u0005[לישיבה]\u0006 והיו צריכים הכל להתיישב במקומותיהם הקבועים להם. \u0003אינהו דהוו קלילי, יתיבו בדוכתייהו\u0004 \u0005[הם שהיו קלים\u0006 בהליכתם, מיהרו ו\u0005ישבו במקומותיהם],\u0006 ואילו \u0003ר' ישמעאל בר' יוסי אגב יוקריה הוה מפסע ואזיל\u0004 \u0005[מתוך כובדו,\u0006 שהיה שמן מאוד, \u0005היה פוסע והולך\u0006 לאט\u0005],\u0006 כאשר כבר ישבו הכל במקומותיהם על הארץ, והיה צריך לעבור מעל ראשיהם של היושבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אבדן\u0004 (אבא יודן) שהיה תלמידו ושמשו של רבי: \u0003מי הוא זה שמפסע על ראשי עם קדוש!\u0004 שהדבר נראה כזלזול בישראל שהוא פוסע מעל ראשיהם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני ישמעאל בר' יוסי שבאתי ללמוד תורה מרבי. אמר ליה\u0004 \u0005[לו]\u0006 אבדן: \u0003וכי אתה הגון ללמוד תורה מרבי\u0004 שבגלל זה אתה מזלזל באחרים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי משה היה הגון ללמוד תורה מפי הגבורה\u0004 (הקדוש ברוך הוא)? אלא ודאי שאין הכרח שיהא התלמיד חשוב כמו רבו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי משה אתה? אמר ליה\u0004 ר' ישמעאל: \u0003וכי רבך אלהים הוא?\u0004 על קטע זה במעשה \u0003אמר רב יוסף: שקליה\u0004 \u0005[קיבל]\u0006 \u0003רבי\u0004 כאן \u0003למטרפסיה\u0004 \u0005[את גמולו]\u0006 על ששתק כל אותו זמן ולא מיחה בתלמידו על שביזה את ר' ישמעאל, ומהו הגמול — \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 ר' ישמעאל לאבדן: \u0003\"רבך\" ולא\u0004 אמר \u0003\"רבי\"\u0004 שנראה הדבר כאילו אינו מקבל עליו את מרותו.","\u0003אדהכי אתיא\u0004 \u0005[בינתיים באה]\u0006 \u0003יבמה לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבי,\u0004 שהיתה קטנה סמוך לבגרותה, וחלצו לה, ולא היה ברור אם החליצה כשירה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לאבדן: פוק בדקה\u0004 \u0005[צא\u0006 ו\u0005בדוק אותה]\u0006 אם כבר הגיעה לבגרות. \u0003לבתר דנפק\u0004 \u0005[לאחר שיצא]\u0006 אבדן, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל\u0004 לרבי: \u0003כך אמר אבא\u0004 בענין חליצת קטנה: \u0003\"איש\" כתוב בפרשה, אבל אשה — בין גדולה בין קטנה,\u0004 חליצתה כשרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לאבדן: \u0003תא, לא צריכת\u0004 \u0005[בוא, אין אתה צריך]\u0006 לבדוק, \u0003כבר הורה זקן\u0004 (ר' יוסי) בענין זה, ויש לנו כבר הלכה פסוקה שאין צורך בבדיקה. \u0003קמפסע אבדן ואתי\u0004 \u0005[היה אבדן פוסע ובא]\u0006 מעל ראשי האנשים כדי לחזור למקומו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל בר' יוסי: מי שצריך לו עם קדוש — יפסע על ראשי עם קדוש, מי שאין צריך לו עם קדוש,\u0004 שהרי אין כבר צורך בבדיקה, \u0003היאך יפסע על ראשי עם קדוש?\u0004","\u0003אמר ליה רבי לאבדן: קום בדוכתיך\u0004 \u0005[עמוד במקומך]\u0006 ואל תלך יותר! \u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003באותה שעה נצטרע אבדן\u0004 כעונש על שהעליב את ר' ישמעאל בר' יוסי, \u0003וטבעו שני בניו\u0004 שהיו נשואים זה לא מכבר, \u0003ומאנו שתי כלותיו\u0004 שהיו נשואות לאותם בנים וביטלו את הנישואין. \u0003אמר רב נחמן בר יצחק: בריך רחמנא דכספיה\u0004 \u0005[ברוך ה' שבייש אותו]\u0006 את \u0003אבדן בהאי עלמא\u0004 \u0005[בעולם הזה],\u0006 ולא ייענש עוד לעולם הבא, שנמחלו כל עוונותיו על ידי יסורים אלה.","\u0003אמר ר' אמי: מדבריו של ברבי\u0004 (האיש הגדול, ר' יוסי), \u0003נלמוד: קטנה חולצת\u0004 אפילו כשהיא \u0003ב\u0004גיל ה\u0003פעוטות\u0004, כבת שש ושבע. \u0003רבא אמר:\u0004 אינה חולצת \u0003עד שתגיע לעונת נדרים,\u0004 כבת אחת עשרה, שיש בה דעת עד שמסוגלת להבין משמעות של נדר. אולם מסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 פסוקה\u0005]:\u0006 אינה חולצת \u0003עד שתביא שתי שערות.\u0004","שנינו במשנה: אם \u0003חלצה בשנים,\u0004 או בשלושה, ונמצא אחד מהם פסול — ר' שמעון ור' יוחנן הסנדלר מכשירים. \u0003אמר רב יוסף בר מניומי אמר רב נחמן: אין הלכה כאותו הזוג\u0004 שהכשיר. ושואלים: \u0003והא\u0004 \u0005[והרי\u0006 כבר\u0005]\u0006 \u0003אמר רב נחמן\u0004 אותה הלכה \u0003חדא זימנא\u0004 \u0005[פעם אחת].\u0006 ש\u0003אמר רב יוסף בר מניומי אמר רב נחמן: חליצה בשלשה,\u0004 ומכאן נלמד שאי אפשר בפחות מכך!","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 שני הדברים להיאמר, \u0003דאי איתמר הך קמייתא\u0004 \u0005[שאילו נאמרה\u0006 רק \u0005זו הראשונה],\u0006 \"חליצה בשלושה\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לכתחלה, אבל\u0004 ב\u0003דיעבד\u0004 יספיקו \u0003אפילו תרי\u0004 \u0005[שניים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003אין הלכה כאותו הזוג\u0004 ובשניים חליצתה פסולה אפילו בדיעבד. \u0003ו\u0004להיפך: \u0003אי אשמועינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 רק ש\u0003אין הלכה כאותו הזוג, אלא כתנא קמא, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שרק ב\u0003דיעבד\u0004 נאמרו הדברים שכשרה בשלושה, \u0003אבל לכתחילה ליבעי\u0004 \u0005[שיצטרכו]\u0006 \u0003חמשה,\u0004 כדעת ר' יהודה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","מסופר במשנה ש\u0003מעשה שחלצו\u0004 בינו לבינה. ושואלים: \u0003בינו לבינה מי ידענא\u0004 \u0005[האם אנו יודעים]?\u0006 הרי לא היתה עדות בדבר, ומה מועילה חליצה כזאת? \u0003אמר רב יהודה אמר שמואל: ו\u0004צריך להוסיף ש\u0003עדים\u0004 היו \u0003רואין אותו מבחוץ,\u0004 אבל לא השתתפו במעשה עצמו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים בבית המדרש שאלה בהבנת לשונה של משנתנו: האם ה\u0003מעשה\u0004 היה \u0003שחלצו בינו לבינה אבראי\u0004 \u0005[בחוץ]\u0006 במקום אחר, \u0003ובא מעשה\u0004 זה \u0003לפני ר' עקיבא\u0004 כאשר היה הוא אסור \u0003בבית האסורין, או דלמא\u0004 \u0005[שמא]\u0006 \u0003מעשה שחלצו בינו לבינה\u0004 כשהיו היבם והאשה \u0003בבית האסורין,\u0004 ואותו מעשה בא לפני ר' עקיבא? \u0003אמר רב יהודה אמר רב: בבית האסורין היה מעשה\u0004 החליצה, \u0003ו\u0004גם \u0003לבית האסורין בא מעשה\u0004 כשהיה ר' עקיבא במאסר."],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חליצה מוטעת\u0004 — \u0003כשרה.\u0004 ושואלים: \u0003אי זו היא חליצה מוטעת? אמר ריש לקיש: כל שאומרים לו\u0004 ליבם שאיננו בקי בהלכה: \u0003חלוץ\u0004 לה, \u0003ובכך אתה כונסה,\u0004 כלומר, על ידי זה אתה נושאה לאשה. שאף שלא התכוון כלל לפוטרה, חליצה זו מועילה, ופוטרת אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן, אני שונה: בין שנתכוון הוא\u0004 לפוטרה \u0003ולא נתכוונה היא\u0004 להיפטר מזיקתו, \u0003בין שנתכוונה היא ולא נתכוון הוא — חליצתה פסולה, עד שיתכוונו שניהם כאחד, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 שבמקרה כגון זה, שאינו מתכוון כלל לפוטרה, תהא \u0003חליצתה כשירה?!\u0004","\u0003אלא\u0004 חליצה מוטעית היא \u0003כל שאומרים לו: \"חלוץ לה על מנת שתתן לך מאתים זוז\",\u0004 שגם אם לא תתן — החליצה כשירה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כר' יוחנן: \u0003חליצה מוטעת\u0004 — \u0003כשירה. אי זו היא חליצה מוטעת — כל שאומרים\u0004 לו: \u0003\"חלוץ לה על מנת שתתן לך מאתים זוז\".\u0004","\u0003ומעשה באשה אחת שנפלה לפני יבם שאין הגון לה, ואמרו לו: \"חלוץ לה על מנת שתתן לך מאתים זוז\",\u0004 ולא נתנה לו לאחר מכן כלום, \u0003ובא מעשה\u0004 זה \u0003לפני ר' חייא והכשירה.\u0004","ומסופר עוד: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006איש \u0005אחד שבא לפני]\u0006 \u0003ר' חייא בר אבא\u0004 בענין ייבום, ובאו היבם והיבמה. \u0003אמר לה\u0004 ר' חייא ליבמה: \u0003בתי, עמודי!\u0004 כי מתחילים עכשיו לדון, ועל בעלי הדין לעמוד. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003ישיבתה זו היא עמידתה,\u0004 כלומר, עדיף לה שלא תעמוד ולא תתייבם. \u0003אמר לה\u0004 ליבמה: \u0003ידעת ליה\u0004 \u0005[מכירה את אותו]\u0006 את היבם הזה, ויודעת משום מה רוצה הוא בך? \u0003אמרה ליה: אין\u0004 \u0005[כן],\u0006 \u0003ממונא הוא דחזא לה וקבעי למיכליה מינה\u0004 \u0005[ממון הוא שראה אצלה,\u0006 כלומר, אצלי, \u0005ורוצה לאכול,\u0006 לקחת, \u0005אותו ממנה]\u0006 ולכן הוא רוצה לייבם.","\u0003אמר לה:\u0004 וכי \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לך\u0004 הדבר? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 אכן איני רוצה בכך. וכיון שכך, רצה שיפטור היבם את האשה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ליבם: \u0003חלוץ לה, ובכך אתה כונסה\u0004 (נושאה לאשה), שרצה להטעות אותו שיחלוץ. ואכן כך עשה היבם. \u0003לבתר\u0004 \u0005[לאחר]\u0006 ש\u0003חלץ לה, אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא ליבם: \u0003השתא, מינך אפסלא לה\u0004 \u0005[\u0006מ\u0005עתה, ממך\u0006 היא \u0005נפסלה]\u0006 לעולם, שכיון שחלצת לה חליצה כל שהיא, הרי שוב אינך מותר בה, ואין לך איפוא מה להפסיד, לכן \u0003חלוץ לה\u0004 עוד \u0003חליצה מעלייתא\u0004 \u0005[מעולה,\u0006 הגונה\u0005],\u0006 \u0003כי היכי דתישתרי לעלמא\u0004 \u0005[כדי שתהיה מותרת לעולם,\u0006 לאחרים\u0005].\u0006","מסופר: \u0003בת חמוה\u0004 \u0005[חמיו],\u0006 גיסתו של \u0003רב פפא נפלה\u0004 לייבום \u0003לפני יבם שאין הגון לה,\u0004 שרצה לנושאה לאשה. \u0003אתא\u0004 \u0005[בא]\u0006 המקרה \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]\u0006 אביי ליבם: \u0003חלוץ לה, ובכך אתה כונסה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא:\u0004 וכי \u0003לא סבר לה מר\u0004 \u0005[אין אדוני סבור]\u0006 \u0003להא\u0004 \u0005[לזו]\u0006 ש\u0003אמר ר' יוחנן\u0004 שדבר זה איננו מועיל כלל? אמר לו: \u0003ואלא היכי אימא ליה\u0004 \u0005[איך אומר לו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 כפי שהציע ר' יוחנן עצמו — \u0003חלוץ לה על מנת שתתן לך מאתים זוז.\u0004 אמר כך אביי ליבם, ועשה הוא כדבריו וחלץ לה. \u0003לבתר\u0004 \u0005[לאחר]\u0006 ש\u0003חלץ לה, אמר לה\u0004 אביי לגיסתו של רב פפא: \u0003זיל הב ליה\u0004 \u0005[לכי\u0006 ו\u0005תני לו],\u0006 שהרי הבטחת לו מאתיים זוז. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא בשבילה: \u0003משטה אני בך עבדה ליה\u0004 \u0005[עשתה לו],\u0006 כלומר, לא התכוונה לכך ברצינות, ואין זו התחייבות שאפשר לגבותה.","שכן \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 ברייתא\u0005]\u0006 מעין זו: \u0003הרי שהיה\u0004 אדם \u0003בורח מבית האסורין,\u0004 וכמובן ממהר להימלט מן המקום, \u0003והיתה מעברא\u0004 (מעבורת) \u0003לפניו,\u0004 לעבור את הנהר, וצריך לעבור בה ובעל המעבורת איננו רוצה או איננו ממהר, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 האסיר לבעל המעבורת: \u0003טול\u0004 (קח) \u0003דינר והעבירני,\u0004 וזה סכום הרבה יותר גדול ממה שהיה צריך לשלם — \u0003אין לו\u0004 לאותו אדם שהעבירו \u0003אלא שכרו\u0004 הרגיל, ופטור מלשלם מה שהבטיח יותר.","\u0003אלמא אמר ליה\u0004 \u0005[מכאן\u0006 שיכול \u0005לומר לו]\u0006 לאיש כזה \u0003משטה אני בך,\u0004 ולא היתה זו התחייבות ממשית — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכולה היא לומר לו \u0003משטה אני בך,\u0004 ולכן פטורה מלשלם את מאתיים הזוז. שמע אביי דברים אלה, והסכים להם. אבל התפעל מחריפותו של רב פפא, שהיה אז צעיר לימים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא: \u0003אבוך היכא\u0004 \u0005[אביך היכן\u0006 הוא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במתא\u0004 \u0005[בעיר]\u0006 הוא; \u0003אימך היכא\u0004 \u0005[אמך, היכן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במתא\u0004 \u0005[בעיר].\u0006 וחשב אביי שמפני שהוריו של רב פפא נמצאים בסמוך לו ומספקים לו כל צרכיו, והוא אינו מעורב בעסקים, יכול הוא לעסוק בתורה בנחת ולהצליח בה כל כך. \u0003יהיב בהו עיניה\u0004 \u0005[נתן\u0006 אביי \u0005בהם את עיניו]\u0006 מתוך הרגשה של צער ותרעומת (לפי שאביי עצמו היה יתום ועני בצעירותו), \u0003ושכיבן\u0004 \u0005[ומתו]\u0006 שניהם, אביו ואמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חליצה מוטעת — כשרה. גט מוטעה — פסול. חליצה מעושית,\u0004 כלומר, שעושים אותה בכפייה — \u0003פסולה, גט מעושה — כשר.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]\u0006 בענין גט מעושה, \u0003אי\u0004 \u0005[אם]\u0006 כפו אותו עד ש\u0003אמר \"רוצה אני\"\u0004 לגרשה — \u0003אפילו חליצה נמי\u0004 \u0005[גם כן]\u0006 תהיה מועילה, אף שתחילתה היתה בכפייה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אמר \"רוצה אני\" — גט נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 מועיל בכפייה!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003חליצה מוטעת — לעולם כשר, וגט מוטעה — לעולם פסול. חליצה מעושית וגט מעושה — זימנין\u0004 \u0005[לפעמים]\u0006 \u0003כשר וזימנין\u0004 \u0005[ולפעמים]\u0006 \u0003פסול.\u0004 כיצד? \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר \"רוצה אני\",\u0004 אפילו אם אמר זאת בגלל כפייה — מועיל. \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא אמר \"רוצה אני\"\u0004 — אינו מועיל.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר בכמה קרבנות \u0003\"יקריב אתו\"\u0004 (ויקרא א, ג) — \u0003מלמד שכופין אותו\u0004 להקריב מה שנתחייב בו. \u0003יכול בעל כרחו\u0004 לגמרי, וכגון שנוטלים לצורך זה מרכושו בלי רצונו — \u0003תלמוד לומר: \"לרצנו\"\u0004 (שם). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתיישבים שני הדברים? — \u0003כופין אותו\u0004 בעונשים או בקנסות \u0003עד שיאמר \"רוצה אני\". וכן אתה מוצא בגיטי נשים\u0004 שאי אפשר לכתוב גט במקומו של הבעל, אבל \u0003כופין אותו עד שיאמר \"רוצה אני\",\u0004 וכותב גט ונותן לה מרצונו.","\u0003אמר רבא אמר רב סחורה אמר רב הונא: חולצין אף על פי שאין מכירין.\u0004 כלומר, אף שאין לפני בית הדין עדות גמורה שאכן אלה הם היבם והיבמה, אם רוצים אנשים לעשות חליצה — אין צריכים לבדוק אחריהם. וכן \u0003ממאנין,\u0004 אם באה אשה למאן בבעלה — ממאנת, \u0003אף על פי שאין מכירין\u0004 ואין יודעים שילדה זו היא אכן אשתו של האיש שממאנת בו.","\u0003לפיכך, אין כותבין גט חליצה\u0004 (שטר המאשר את קיום החליצה) \u0003אלא אם כן מכירין, ואין כותבין גט מיאון אלא אם מכירין,\u0004 והטעם לכך: \u0003דחיישינן\u0004 \u0005[שחוששים אנו]\u0006 \u0003לבית דין טועין,\u0004 שמא יהיה בית דין שלא יידע ששטר כזה איננו הוכחה גמורה שנעשה הדבר כדין, ושהנחלצת אכן חלצה מיבמה, והממאנת היתה אמנם אשתו. אלא צריך לבדוק אחר כך שוב כדי להתיר נשים אלה לאחרים, ולכן אין כותבים שטר אלא אם כן מכירים, כדי שבית הדין שבא להתירם יוכל לסמוך על השטר.","\u0003ורבא דידיה\u0004 \u0005[\u0006משל \u0005עצמו]\u0006 \u0003אומר\u0004 להיפך: \u0003אין חולצין אלא אם כן מכירין, ואין ממאנין אלא אם כן מכירין. לפיכך, כותבין גט חליצה אף על פי שאין מכירין,\u0004 שכיון שראו עדים שעשו חליצה — ודאי בדק כבר בית הדין את הדבר כראוי, \u0003ו\u0004לפיכך, \u0003כותבין גט מיאון אף על פי שאין מכירין, ולא חיישינן\u0004 \u0005[ואיננו חוששים]\u0006 \u0003לבית דין טועין\u0004 שמא עשה הבית דין הראשון בלא להכיר."],["\u0003מצות חליצה\u0004 כך היא נעשית: \u0003בא הוא ויבמתו לבית דין, והן,\u0004 החכמים שבבית הדין, \u0003משיאין לו עצה ההוגנת לו,\u0004 אם לייבם או לחלוץ, \u0003שנאמר: \"וקראו לו זקני עירו ודברו אליו\"\u0004 (דברים כה, ח), \u0003ו\u0004אם החליטו לחלוץ, \u0003היא אומרת: \"מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי\"\u0004 (שם ז), \u0003והוא אומר: \"לא חפצתי לקחתה\"\u0004 (שם ח). \u0003ובלשון הקדש היו אומרים\u0004 דברים אלה ולא בשפה אחרת. אחר כך \u0003\"ונגשה יבמתו אליו לעיני הזקנים וחלצה נעלו מעל רגלו וירקה בפניו\"\u0004 (שם ט), וצריך שיהיה זה \u0003רוק הנראה לדיינים. \"וענתה ואמרה ככה יעשה לאיש אשר לא יבנה את בית אחיו\"\u0004 (שם). \u0003עד כאן היו מקרין\u0004 (מקריאים) להם את מה שעליהם לומר.","","\u0003וכשהקרא\u0004 פעם \u0003ר' הורקנוס תחת האלה בכפר עיטם, וגמר\u0004 להקריא \u0003את כל הפרשה, הוחזקו,\u0004 כלומר, נעשה מנהג, \u0003להיות גומרין\u0004 את \u0003כל הפרשה.\u0004 ואומרים: \u0003\"ונקרא שמו בישראל בית חלוץ הנעל\"\u0004 (שם, י). \u0003מצוה\u0004 זו, לומר \"בית חלוץ הנעל\", היא \u0003בדיינים, ולא מצוה בתלמידים,\u0004 כלומר, שאר הנמצאים במקום. \u0003ר' יהודה אומר: מצוה על כל העומדים שם לומר \"חלוץ הנעל\".\u0004","\u0003אמר רב יהודה, מצות חליצה\u0004 כך סדרה: \u0003קוראה\u0004 היא (\"מאן יבמי\" וגו'), \u0003ו\u0004אחר כך \u0003קורא\u0004 הוא (\"לא חפצתי לקחתה\"), \u0003וחולצת, ורוקקה\u0004 (יורקת), \u0003וקוראה\u0004 (\"ככה ייעשה\" וגו'). ושואלים: \u0003מאי קמשמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? הלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא!\u0004 ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שאמנם \u0003מצוה הכי\u0004 \u0005[כך]\u0006 היא, אבל היא אינה בכלל חובה מעכבת, \u0003ואי אפיך\u0004 \u0005[ואם הפך]\u0006 את הסדר, \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, אף שלא עשה כראוי.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בין שהקדים חליצה לרקיקה, ובין שהקדים רקיקה לחליצה — מה שעשה עשוי.\u0004","\u0003אמר אביי\u0004 בפרטי דינים אלה: \u0003האי מאן דמקרי\u0004 \u0005[מי שמקריא]\u0006 ליבם וליבמה את \u0003גט\u0004 (נוסח) \u0003חליצה,\u0004 ש\u0003לא ליקרי לדידה\u0004 \u0005[יקריא לה]\u0006 \u0003\"לא\" לחודיה\u0004 \u0005[לעצמו]\u0006 \u0003ו\"אבה יבמי\" לחודיה\u0004 \u0005[לעצמו],\u0006 מפני שאופן קריאה כזה \u0003משמע\u0004 שהוא קורא: \u0003אבה יבמי. אלא\u0004 יקריא ברציפות \u0003\"לא אבה יבמי\",\u0004 כדי שכוונת הדברים תהא ברורה.","\u0003ולא ליקרי לדידיה\u0004 \u0005[יקריא לו,\u0006 ליבם\u0005]\u0006 \u0003\"לא\" לחודיה\u0004 \u0005[לעצמו]\u0006 ואחר כך \u0003\"חפצתי\" לחודיה\u0004 \u0005[לעצמו],\u0006 שכן באופן זה \u0003משמע\u0004 מדבריו \u0003\"חפצתי לקחתה\", אלא\u0004 יקריא בבת אחת \u0003\"לא חפצתי לקחתה\". רבא אמר: אפסוקי מילתא\u0004 \u0005[הפסקת דבר]\u0006 בלבד \u0003היא, ואפסוקי מילתא\u0004 \u0005[והפסקה\u0006 ב\u0005דבר]\u0006 אחד שלם (שהוא בעצם רק הפסקת נשימה בלבד) \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל צד חשש.","מסופר: \u0003רב אשי אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב כהנא דקמצטער ומקרי\u0004 \u0005[שהוא\u0006 \u0005מצטער,\u0006 מתייגע, \u0005ומקריא]\u0006 \u0003לה\u0004 ליבמה אחת, שתאמר \u0003\"לא אבה יבמי\"\u0004 בבת אחת, כיון שהיבמה לא הבינה והיתה משבשת את הדברים, והוא רצה שתגיד את שלוש המילים כאחת, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: וכי \u0003לא סבר ליה מר להא\u0004 \u0005[האם אין אדוני סבור לזה]\u0006 שאמר \u0003רבא,\u0004 שדבר זה אינו מעכב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 למרות שחלק רבא על אביי בענין \"לא חפצתי לקחתה\", \u0003מודה רבא ב\"לא אבה יבמי\",\u0004 שקריאה זו היא עיקר הענין, ודבר זה צריכה היא לומר כראוי. ועוד \u0003אמר אביי: האי מאן דכתב גיטא דחליצתא\u0004 \u0005[מי שכותב שטר חליצה] —\u0006 \u0003ליכתוב הכי\u0004 \u0005[שיכתוב כך]:\u0006 \u0003אקרינוה לדידה\u0004 \u0005[הקראנו לה]\u0006 \u0003מן \"מאן יבמי\" עד \"אבה יבמי\", ואקרינוהו לדידיה\u0004 \u0005[והקראנו לו]\u0006 \u0003מן \"לא\" עד \"לקחתה\", ואקרינוה לדידה\u0004 \u0005[והקראנו לה]\u0006 \u0003מן \"ככה\" ועד \"חלוץ הנעל\".\u0004","","\u0003מר זוטרא\u0004 היה \u0003משרטט\u0004 אותה, שהיה עושה שורות בקלף כמו שכותבים תורה, \u0003וכתיב לכולא\u0004 \u0005[וכותב את כל]\u0006 ה\u0003פרשה,\u0004 כדי שתהיה לנגד עיני המשתתפים במעמד החליצה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר אידי: והא\u0004 \u0005[והרי]\u0006 דבר זה \u0003לא ניתן ליכתב\u0004 לעצמו! שהתורה ניתנה להיכתב רק בשלימותה, ואסור לכתוב חלקים מן התורה כשאין מצוה לכותבם לעצמם. \u0003ו\u0004מעירים: אף על פי כן \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003מר זוטרא,\u0004 שכיון שיש כאן צד מצוה ואינו כותב לשם פרשה מיוחדת לעצמה — מותר לכתוב.","\u0003אמר אביי:\u0004 אם \u0003רקקה\u0004 היבמה, \u0003וקלטתו\u0004 (סחבה אותו) \u0003הרוח\u0004 ולא הגיע הרוק אל מול פני היבם — \u0003לא עשתה ולא כלום. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"וירקה בפניו\"\u0004 (שם ט) \u0003בעינן\u0004 \u0005[צריכים אנו].\u0006 \u0003הלכך\u0004 \u0005[על כן],\u0006 אם \u0003הוא ארוך\u0004 (גבוה) \u0003והיא גוצה\u0004 (נמוכת קומה) ו\u0003קלטתהו הרוח — איכא\u0004 \u0005[יש,\u0006 מתקיים\u0005]\u0006 \u0003\"בפניו\",\u0004 שהרי מרגע שיצא הרוק מפיה, היה זה מול היבם (\"בפניו\"). אבל \u0003היא ארוכה והוא גוץ — בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד דמטי להדי אפיה והדר אזיל\u0004 \u0005[שיבוא\u0006 הרוק \u0005אל מול פניו ואחר כך ילך]\u0006 ברוח. ואם היתה גבוהה ממנו והרוק ניתק מפיה ועף ברוח לפני שהגיע לגובה פניו — לא יצאה ידי חובה.","\u0003אמר רבא: אכלה תומא\u0004 \u0005[שום]\u0006 \u0003ורקתה\u0004 (ירקה), \u0003אכלה גרגישתא\u0004 (אדמה), סוג חימר שהיו לועסים לרפואה, \u0003ורקתה\u0004 (ירקה) בגלל כך — \u0003לא עשתה ולא כלום,\u0004 שאין זו קרויה יריקה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"וירקה\" מעצמה בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 שהרי היא יורקת רק בגלל דבר אחר שגורם לה להצטברות רוק בפה. \u0003ואמר רבא: צריכי דייני למיחזי רוקא כי נפיק מפומא\u0004 \u0005[צריכים הדיינים לראות\u0006 את \u0005הרוק כאשר\u0006 הוא \u0005יוצא מפי]\u0006 ה\u0003יבמה\u0004 ולא די בעובדה שירקה רוק על הארץ. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לעיני הזקנים... וירקה\",\u0004 ללמד שהיריקה צריכה להיות לעיני הזקנים.","שנינו במשנה על מה שנאמר \u0003\"ונקרא שמו בישראל בית חלוץ הנעל\" — מצוה בדיינין\u0004 וכו' \u0003ולא בתלמידים. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: פעם אחת היינו יושבים לפני ר' טרפון, ובאתה\u0004 (באה) \u0003יבמה לחלוץ, ואמר לנו\u0004 ר' טרפון, \u0003ענו כולכם: \"חלוץ הנעל\", \"חלוץ הנעל\", \"חלוץ הנעל\"\u0004",""],["\u0003בית שמאי אומרים: אין ממאנין אלא ארוסות\u0004 בלבד, \u0003ובית הלל אומרים: ארוסות ו\u0004גם \u0003נשואות.\u0004","\u0003בית שמאי אומרים:\u0004 הממאנת יכולה למאן \u0003בבעל, ולא ביבם.\u0004 שאם מת בעלה ונפלה לייבום לפני היבם, צריכה להמתין עד שתגדל ותחלוץ. \u0003ובית הלל אומרים:\u0004 יכולה היא למאן \u0003בבעל וביבם.\u0004","\u0003בית שמאי אומרים:\u0004 המיאון צריך להיות דווקא \u0003בפניו\u0004 של הבעל. \u0003ובית הלל אומרים:\u0004 יכול הוא להיעשות \u0003בפניו ושלא בפניו. בית שמאי אומרים:\u0004 המיאון צריך להיעשות דווקא \u0003בבית דין. ובית הלל אומרים: בבית דין ושלא בבית דין.\u0004","\u0003אמרו להם בית הלל לבית שמאי: ממאנת,\u0004 כל עוד ש\u0003היא קטנה,\u0004 ו\u0003אפילו ארבע וחמש פעמים,\u0004 אם חזרו והשיאוה לאחר אחרי שמיאנה בראשון. \u0003אמרו להם בית שמאי: אין בנות ישראל הפקר\u0004 לעבור כך מאיש לאיש, \u0003אלא ממאנת\u0004 פעם אחת בלבד, \u0003וממתנת עד שתגדיל, ותמאן, ותנשא.\u0004","\u0003אמר רב יהודה אמר שמואל: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי\u0004 שנשואה אינה יכולה למאן — \u0003לפי שאין תנאי בנשואין.\u0004 שאם אדם מקדש אשה בתנאי מסויים ואחר כך נושא אותה לאשה, אף על פי שהתנאי של הקידושין לא התקיים — הנישואין תקפים. מפני שאנו אומרים שכשנושא אדם אשה, מפני חיבת הביאה הוא מוחל על התנאים הללו ומוותר עליהם. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003נשואה\u0004 קטנה \u0003תמאן,\u0004 יש חשש שיראו זאת כתנאי במבוגרת, ו\u0003אתי למימר\u0004 \u0005[\u0006ו\u0005יבואו לומר]\u0006 ש\u0003יש תנאי בנשואין.\u0004","ושואלים: ואם לא נישאה ממש, כלומר, לא נבעלה, אלא רק \u0003נכנסה לחופה ולא נבעלה\u0004 שהיא נחשבת כבר כנשואה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אז אין לענין זה כל שייכות עם בעיית תנאי בנישואין! ומשיבים לבית שמאי — \u0003לפי שאין תנאי\u0004 אפילו \u0003בחופה,\u0004 שמפני חיבת החופה הוא מוחל ומבטל את התנאי.","ושואלים עוד: אם \u0003מסר האב\u0004 את בתו \u0003לשלוחי הבעל\u0004 לנישואין שהיא נחשבת כנשואה, עוד לפני החופה, ועם כל זה אין לחשוש, כיון שעדיין לא נמסרה לו עצמו, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חילקו חכמים],\u0006 ובכל מקרה שהיא נחשבת נשואה קבעו שאין מקום לתנאי בנישואין, וממילא גזרו גם שאין מיאון.","\u0003ובית הלל,\u0004 מה טעמם: \u0003מידע ידעי\u0004 \u0005[יודעים\u0006 הכל\u0005]\u0006 ש\u0003נישואי קטנה\u0004 רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003נינהו\u0004 \u0005[הם],\u0006 ולכן אין למדים מהם לענין נישואי גדולה. \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי לפי שאין אדם עושה בעילתו בעילת זנות.\u0004 שאם בא על הקטנה ואחר כך בטלו הנישואין מעיקרם על ידי המיאון, נמצא שביאתו היא בגדר בעילת זנות.","ושואלים: אם \u0003נכנסה לחופה ולא נבעלה\u0004 עדיין, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על כך? שהרי שם אין טעם זה קיים! ומשיבים: \u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 לבעל \u0003דתיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 \u0003חופה דאיסורא\u0004 \u0005[של איסור],\u0006 שהרי אם מתבטלים הנישואין במיאון, נמצא שהיה בחופה עם אשה שלא היתה מותרת לו. ושואלים: ואם \u0003מסר האב\u0004 את בתו הקטנה \u0003לשלוחי הבעל מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חילקו חכמים].\u0006 \u0003ובית הלל\u0004 מה משיבים הם לטעמם של בית שמאי — \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 כאן גם \u0003קדושין ו\u0004גם \u0003כתובה — לא אתו למימר\u0004 \u0005[יבואו לומר]\u0006 ש\u0003בעילתו בעילת זנות.\u0004","\u0003רב פפא אמר: טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי משום פירי\u0004 \u0005[פירות]\u0006 נכסיה, ו\u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית הלל\u0004 גם כן \u0003משום פירי\u0004 \u0005[פירות]\u0006 הנכסים. ומסביר: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי משום פירי\u0004 \u0005[פירות],\u0006 כלומר, \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שה\u0003נשואה תמאן,\u0004 הרי הבעל של אותה קטנה \u0003שמיט ואכיל להו מינה\u0004 \u0005[ישמוט ויאכל אותם ממנה],\u0006 ש\u0003סוף סוף למיפק קיימא\u0004 \u0005[להוציא\u0006 היא \u0005עומדת],\u0006 שהרי בכל עת רשאית היא למאן ולצאת ממנו, ובינתיים, עד שהיא ממאנת בו, הוא יאכל כמה שיוכל. \u0003ובית הלל\u0004 אומרים: \u0003אדרבה\u0004 (להיפך), \u0003כיון דאמרת\u0004 \u0005[שאתה אומר]\u0006 \u0003תמאן,\u0004 שהיא רשאית למאן — \u0003אשבוחי משבח להו\u0004 \u0005[משביח\u0006 הוא \u0005אותם]\u0006 את נכסיה, \u0003סבר דאי\u0004 \u0005[סבור\u0006 הוא \u0005שאם]\u0006 \u0003לא\u0004 יעשה כן, \u0003עייצי\u0004 \u0005[ייעצו]\u0006 \u0003לה קרוביה\u0004 למאן בו, \u0003ומפקי לה מיניה\u0004 \u0005[ויוציאו אותה ממנו].\u0006","\u0003רבא אמר: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003בית שמאי: שאין אדם טורח בסעודה\u0004 של נישואין \u0003ומפסידה.\u0004 ואם תהא לה רשות למאן אף לאחר נישואין — לא ירצה לשאת קטנה ולשאת בכל הוצאות החתונה, כאשר לא ברור לו שהיא נשארת עימו. \u0003ובית הלל\u0004 סבורים: \u0003תרוייהו ניחא להו\u0004 \u0005[שניהם נוח להם]\u0006 בנישואין, אפילו אם אחר כך יתבטלו, \u0003כדי דליפוק עלייהו קלא\u0004 \u0005[שייצא עליהם קול,\u0006 שם\u0005],\u0006 של \u0003אישות,\u0004 ששניהם מעוניינים מטעמים שונים שייחשבו אנשים נשואים.","שנינו במשנה, \u0003בית שמאי אומרים:\u0004 ממאנת \u0003בבעל\u0004 ולא ביבם, ובית הלל אומרים: בבעל וביבם. \u0003אמר ר' אושעיא: ממאנת\u0004 היבמה הקטנה \u0003למאמרו\u0004 של היבם, שאם עשה בה מאמר יכולה היא לעקור אותו על ידי מיאון, \u0003ואינה ממאנת לזיקתו,\u0004 שלפני שעשה בה מאמר אינה יכולה לומר שהיא ממאנת להיות יבמתו, ולעקור בכך את הזיקה. \u0003אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אושעיא\u0004 — הוא סבור כך: \u0003מאמר\u0004 שבמהותו הוא \u0003מדעתה,\u0004 שהרי אין אשה מתקדשת אלא מדעתה — \u0003מציא עקרא\u0004 \u0005[יכולה\u0006 היא \u0005לעקור]\u0006 אותו, ואולם \u0003זיקה,\u0004 ש\u0003בעל כרחה\u0004 היא באה לה, ואינה תלויה בהסכמתה, \u0003לא מציא עקרא\u0004 \u0005[אינה יכולה לעקור].\u0006","ושואלים: \u0003והרי ביאה\u0004 של יבם שהיא \u0003בעל כרחה,\u0004"],["\u0003ומציא עקרא\u0004 \u0005[ויכולה לעקור]!\u0006 שהרי יכולה היא למאן ביבם כפי שממאנת בבעל. \u0003אלא\u0004 כך צריך לומר: \u0003ביאה ומאמר\u0004 ש\u0003הוא\u0004 היבם \u0003קעביד\u0004 \u0005[עושה]\u0006 בה — \u0003מציא עקרא\u0004 \u0005[יכולה\u0006 היא \u0005לעקור],\u0006 ואילו \u0003זיקה, דרחמנא רמא עלה\u0004 \u0005[שהתורה הטילה עליה]\u0006 ואינה תלויה ברצונו של אדם — \u0003לא מציא עקרא\u0004 \u0005[אינה יכולה לעקור].\u0006 ואילו \u0003עולא אמר:\u0004 הקטנה \u0003ממאנת אף לזיקתו\u0004 של היבם. \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 כלומר, כיצד היא עושה זאת — לא על ידי ביטול הזיקה, שהרי דבר שציוותה התורה אין לה כוח לעקור, אלא במיאון זה \u0003נישואי קמאי קא עקרא\u0004 \u0005[\u0006את ה\u0005נישואין\u0006 ה\u0005ראשונים היא\u0006 \u0005עוקרת],\u0006 שמגלה דעתה שאינה רוצה בנישואיה עם הבעל, וכיון שנעקרים נישואין אלה, ממילא אינה זקוקה לאחיו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לעולא\u0004 ממה ששנינו: \u0003כל\u0004 קטנה שהיא עבור היבם איסור ערוה, \u0003שיכולה למאן ולא מיאנה — צרתה חולצת ולא מתייבמת. ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? \u0003תמאן השתא\u0004 \u0005[עכשיו]\u0006 \u0003ותעקרינהו לנישואי קמאי\u0004 \u0005[ותעקור\u0006 בכך \u0005את הנישואין הראשונים]\u0006 מעיקרם, ונמצא שלא היתה הצרה כלל צרת ערוה, \u0003ותתייבם צרתה!\u0004 ומשיבים: \u0003צרת ערוה שאני\u0004 \u0005[שונה],\u0006 שלא יועיל הדבר מפני גזירת חכמים. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר יחזקאל\u0004 ברייתא זו: \u0003מיאנה בבעל — מותרת לאביו,\u0004 שהנישואין בטלו ואין היא יותר כלתו. מיאנה \u0003ביבם — אסורה לאביו.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 שהוא סבור שמכיון ש\u0003בשעת נפילה\u0004 שלה לייבום הריהי \u0003נראית ככלתו\u0004 ולא היה מובן לאנשים שהמיאון שלה שלאחר מכן יעקור את הנישואין הראשונים שלה, גזרו שלא ישאנה עוד, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 צריך לומר כיון ש\u0003בשעת נפילה נראית כצרת בתו,\u0004 ואף שמעיקר הדין ביטל המיאון את האיסור מעיקרו, גזרו משום מראית העין.","\u0003אמר רב: מיאנה ב\u0004יבם \u0003זה — אסורה לזה\u0004 לאחיו. \u0003מידי דהוה\u0004 \u0005[כמו ש\u0006הדין \u0005הוא]\u0006 ביחס ל\u0003בעלת הגט,\u0004 כלומר, יבמה שנתן לה אחד מן היבמים גט, ו\u0003בעלת הגט, לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003כיון דאיתסרא\u0004 \u0005[שנאסרה]\u0006 \u0003לה לחד\u0004 \u0005[לאחד],\u0006 לזה שנתן לה גט, \u0003איתסרא להו לכולהו\u0004 \u0005[נאסרה להם לכולם],\u0006 \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה].\u0006","\u0003ושמואל אמר: מיאנה בזה — מותרת לזה, ולא דמיא\u0004 \u0005[ואינה דומה]\u0006 \u0003לבעלת הגט.\u0004 כי \u0003בעלת הגט, הוא דקא עביד\u0004 \u0005[\u0006זה ש\u0005הוא שעושה]\u0006 \u0003בה\u0004 מעשה זה של גט, ובזה הוא אוסר אותה גם על אחיו, ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 כשממאנת ביבם, \u0003היא קעבדא ביה\u0004 \u0005[\u0006ש\u0005עושה בו]\u0006 מעשה, \u0003דאמרה\u0004 \u0005[שאומרת]:\u0006 \u0003\"לא רעינא בך ולא צבינא בך\u0004 \u0005[איני חפצה בך ואיני רוצה בך]\u0006\u0003\",\u0004 ומלשון זו של מיאון משמע: \u0003בך הוא דלא רעינא\u0004 \u0005[שאין אני חפצה],\u0006 \u0003הא בחברך רעינא\u0004 \u0005[הרי,\u0006 אבל, \u0005בחברך חפצה אני].\u0006","\u0003רב אסי אמר: מיאנה ב\u0004יבם \u0003זה — מותרת אפילו לו,\u0004 אם תתחרט. ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003כ\u0004שיטת \u0003ר' אושעיא סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 ר' אושעיא: \u0003אינה ממאנת לזיקתו,\u0004 וכיון שכך, הזיקה עדיין קיימת ולא התבטלה על ידי המיאון, ולכן הוא מותר בה. ודוחים: \u0003בחד יבם\u0004 \u0005[ביבם אחד]\u0006 שלא היו לו אחים, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003דמציא עקרא\u0004 \u0005[ש\u0006היא \u0005יכולה לעקור\u0006 את הזיקה\u0005]\u0006 וכעולא, ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003בשני יבמין עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003אין מיאון לחצי זיקה,\u0004 וכיון שהיא ממאנת ביבם אחד בלבד, אין המיאון הזה מבטל את הזיקה, ומאחר שהזיקה קיימת היא מותרת אף לזה שמיאנה בו.","מספרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: מיאנה בזה מותרת לאחין, ולא הודו לו.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי]\u0006 הם אלה ש\u0003לא הודו לו? אמר אביי: רב\u0004 הוא זה שלא הודה לו. \u0003רבא אמר: ר' אושעיא\u0004 הוא זה שלא הודה לו, שהרי סבור הוא שאין מיאון עוקר את הזיקה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אסי\u0004 הוא זה שלא הודה לו, שהרי לרב אסי היא מותרת אף לזה שמיאנה בו.","שנינו במשנה, ש\u0003בית שמאי אומרים: בפניו,\u0004 בפני הבעל בלבד, היא ממאנת. ובית הלל אומרים אפילו שלא בפניו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו להן בית הלל לבית שמאי: והלא\u0004 מעשה היה ב\u0003פישון הגמל\u0004 (נוהג הגמלים) ש\u0003מיאנה אשתו שלא בפניו,\u0004 משמע שאפשר לעשות כן! \u0003אמרו להן בית שמאי לבית הלל: פישון הגמל במדה כפושה\u0004 (גרועה) \u0003מדד,\u0004 שהיה אוכל מפירות נכסי אשתו יתר על המידה ולא נהג בה כראוי, ו\u0003לפיכך מדדו לו\u0004 חכמים \u0003במדה כפושה\u0004 (שאינה הגונה). והיתה זו עקירת הנישואין על ידי חכמים, ולא מיאון רגיל.","ושואלים: הלא \u0003מדקא אכיל פירי\u0004 \u0005[\u0006מ\u0005כיוון ש\u0006הוא היה \u0005אוכל פירות],\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר במקרה ש\u0003נשואה היא,\u0004 שהלא אין אכילת פירות בנכסי ארוסה, \u0003ו\u0004אם כן, \u0003האמרי\u0004 \u0005[הרי\u0006 ש\u0005אומרים]\u0006 \u0003בית שמאי\u0004 שה\u0003נשואה לא ממאנה\u0004 \u0005[אינה ממאנת]!\u0006 ומשיבים לדעת בית שמאי: \u0003תרי קיטרי עבדו ביה\u0004 \u0005[שני קשרים עשו בו],\u0006 כלומר, עשו בו שני דברים לרעתו שלא כרגיל: בזה שמיאנה שלא בפניו, ובזה שמיאנה כשהיא נשואה.","עוד שנינו במשנה, ש\u0003בית שמאי אומרים:\u0004 המיאון נעשה רק \u0003בפני בית דין,\u0004 ובית הלל אומרים: גם שלא בפני בית דין. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003החליצה והמיאונין — בשלשה.\u0004 ונברר: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 הסבור כך? \u0003אמר רבה:\u0004 כדעת \u0003בית שמאי היא,\u0004 שהם אומרים שמיאון הוא בבית דין דווקא. \u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שזו שיטת \u0003בית הלל.\u0004 וכיצד? \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית הלל אלא דלא בעינן\u0004 \u0005[שאיננו צריכים]\u0006 דווקא דיינים \u0003מומחין\u0004 במיאון, \u0003אבל\u0004 מכל מקום שיהיו במיאון \u0003שלשה\u0004 אנשים כשרים, שהם \"בית דין של הדיוטות\" \u0003בעינן\u0004 \u0005[צריכים אנו].\u0006","ו\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003בית שמאי אומרים:\u0004 מיאון נעשה \u0003בפני בית דין, ובית הלל אומרים: בפני בית דין ושלא בפני בית דין. ואלו ואלו מודים שצריך\u0004 מכל מקום שיהיו \u0003שלשה. ר' יוסי בר יהודה ור' אלעזר בר' שמעון מכשירין בשנים. אמר רב יוסף בר מניומי אמר רב נחמן: הלכה כאותו הזוג.\u0004","שנינו במשנה ש\u0003בית שמאי אומרים: תמאן,\u0004 ותמתין עד שתגדיל, ותמאן ותינשא לאחר. ושואלים: למה לה למאן פעם נוספת? \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003מיאנה חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003אמר שמואל:\u0004 הכוונה היא \u0003עד שתגדיל ותאמר: \"רוצה אני במיאונים הראשונים\",\u0004 שמא התחרטה בינתיים.","\u0003עולא אמר: תרתי קתני\u0004 \u0005[שני\u0006 דברים \u0005שנה\u0006 כאן\u0005]:\u0006 \u0003או שתמאן ותגדיל ותיארס,\u0004 ולא תתארס כשהיא קטנה כדי שלא תמאן שוב, \u0003או שתמאן ותנשא לאלתר\u0004 (מיד), ואז לא תוכל למאן — לבית שמאי שסוברים שנשואה לא ממאנת.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006 לשיטת\u0005]\u0006 \u0003עולא, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"עד שתגדיל ותנשא\",\u0004 כלומר, עד שתגדיל או עד שתינשא. \u0003אלא ל\u0004דברי \u0003שמואל — הלא \"עד שתגדיל ותאמר\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 סגנון זה לשיטתו.","\u0003אי זו היא קטנה שצריכה למאן — כל שהשיאוה אמה ואחיה לדעתה,\u0004 כלומר, מרצונה. אבל אם \u0003השיאוה שלא לדעתה — אינה צריכה למאן\u0004 כלל, ויוצאת אפילו בלא מיאון. \u0003ר' חנינא בן אנטיגנוס אומר: כל תינוקת\u0004 שהיא קטנה כל כך \u0003שאינה יכולה לשמור קידושיה — אינה צריכה למאן,\u0004 שלא תיקנו מיאון אלא לבת דעת במקצת.","\u0003ר' אלעזר אומר\u0004 כלל בדבר: \u0003אין מעשה קטנה כלום,\u0004 ונישואי קטנה בעצם אינם תופסים, \u0003אלא\u0004 דינה \u0003כ\u0004אילו היתה \u0003מפותה\u0004 על ידי הבעל. ולכן, \u0003בת ישראל\u0004 קטנה שהשיאוה אימה ואחיה \u0003לכהן — לא תאכל בתרומה\u0004 בשל נישואין אלו, כדרך שאוכלת כל בת ישראל גדולה הנשואה לכהן, ו\u0003בת כהן\u0004 קטנה הנשואה \u0003לישראל — תאכל בתרומה,\u0004 שהרי זה כאילו לא נישאה כלל.","\u0003ר' אליעזר בן יעקב אומר\u0004 כלל אחר: \u0003כל עכבה\u0004 (עיכוב) שיש בדבר זה \u0003שהיא\u0004 נגרמת \u0003מן האיש — כאילו היא אשתו, כל עכבה שאינה מן האיש — כאילו אינה אשתו.\u0004 וכאשר יבואר בגמרא.","\u0003אמר רב יהודה, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003בראשונה היו כותבין גט מיאון\u0004 בסגנון זה: \u0003\"לא רעינא ביה ולא צבינא ביה ולית אנא בעיא להתנסבא ליה\u0004 \u0005[אין אני חפצה בו ואין אני רוצה בו ואין אני רוצה להינשא לו]\u0006 \u0003\". כיון דחזו דנפיש דיבורא\u0004 \u0005[שראו שהורחב הדיבור]\u0006 בזה, \u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמים:"],["\u0003אתי לאיחלופי בגיטא\u0004 \u0005[יבואו להחליף\u0006 שטר זה \u0005בגט]\u0006 ושמא יטעה אדם ויתן גט בנוסח של מיאון. ולכן, \u0003תקינו הכי\u0004 \u0005[תיקנו\u0006 לכתוב \u0005כך]:\u0006 \u0003\"ביום פלוני מיאנה פלונית בת פלוני באנפנא\u0004 \u0005[בפנינו]\u0006\u0003\",\u0004 ולא יותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אי זהו מיאון? אמרה: \"אי אפשי\u0004 \u0005[איני רוצה]\u0006 \u0003בפלוני בעלי\",\u0004 או שאמרה: \u0003\"אי אפשי\u0004 \u0005[איני רוצה]\u0006 \u0003בקידושין שקידשוני אמי ואחי\". יתר על כן אמר ר' יהודה: אפילו\u0004 היתה \u0003יושבת באפריון\u0004 (כסא כלולות) \u0003והולכת מבית אביה לבית בעלה, ואמרה\u0004 בדרך: \u0003\"אי אפשי\u0004 \u0005[איני רוצה]\u0006 \u0003בפלוני בעלי\" — זהו מיאון.\u0004","\u0003יתר על כן אמר ר' יהודה: אפילו היו אורחין מסובין בבית בעלה והיא עומדת ומשקה עליהם\u0004 כמארחת, \u0003ואמרה להם: \"אי אפשי\u0004 \u0005[איני רוצה]\u0006 \u0003בפלוני בעלי\"\u0004 אף שייתכן שאומרת כך רק משום שהיא מתייגעת ברגע זה — בכל זאת ביטוי זה \u0003זהו\u0004 ה\u0003מיאון. יתר על כן אמר ר' יוסי בר יהודה: אפילו שיגרה\u0004 (שלח אותה) \u0003בעלה אצל חנוני להביא לו חפץ משלו, ואמרה: \"אי אפשי\u0004 \u0005[איני רוצה]\u0006 \u0003בפלוני בעלי\" — אין לך מיאון גדול מזה.\u0004","שנינו במשנה, \u0003ר' חנינא בן אנטיגנוס אומר: כל תינוקת\u0004 שהיא קטנה כל כך שאינה יכולה לשמור קידושיה — אינה צריכה למאן. \u0003אמר רב יהודה אמר שמואל: הלכה כר' חנינא בן אנטיגנוס. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003קטנה שלא מיאנה, ועמדה ונשאת\u0004 לאדם אחר. \u0003משום ר' יהודה בן בתירה אמרו: נישואיה הן הן מיאוניה,\u0004 שהרי בעצם נישואיה לאחר, גילתה דעתה שאינה רוצה בו, ודי בכך.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים שאלה זו: \u0003נתקדשה\u0004 לאחר, \u0003מהו?\u0004 האם צריכה גם מיאון, או די בקידושין לבד ואין עוד צורך במיאון? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לכך מהברייתא: \u0003קטנה שלא מיאנה ועמדה ונתקדשה\u0004 — \u0003משום\u0004 (בשם) \u0003ר' יהודה בן בתירה אמרו: קידושיה הן הן מיאוניה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003פליגי רבנן עליה\u0004 \u0005[האם חולקים חכמים עליו]\u0006 על \u0003ר' יהודה בן בתירה או לא\u0004 חולקים וכולם מסכימים לדבריו? ועוד: \u0003אם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 כי \u0003פליגי\u0004 \u0005[חלוקים\u0006 עליו\u0005],\u0006 האם חלוקים עליו \u0003בקידושין\u0004 בלבד, \u0003או אפילו בנישואין? ואם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר פליגי\u0004 \u0005[\u0006ש\u0005חלוקים]\u0006 \u0003אפילו בנישואין,\u0004 האם \u0003הלכה כמותו או אין הלכה כמותו? ואם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 ש\u0003הלכה כמותו,\u0004 האם רק \u0003בנישואין או אפילו בקידושין?\u0004","ומביאים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה ממה ש\u0003אמר רב יהודה אמר שמואל: הלכה כר' יהודה בן בתירה\u0004 בנישואין ובקידושין. ומכאן גם נלמד שמכיון שאמר \u0003הלכה\u0004 כמותו — \u0003מכלל\u0004 הדברים אתה למד \u0003דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים],\u0006 שאם לא כן לא היה צריך לומר שהלכה כמותו.","פתרנו איפוא חלק מן השאלות, \u0003ואכתי תיבעי לך\u0004 \u0005[ועדיין תישאל,\u0006 תסתפק \u0005לך]:\u0006 האם אומר ר' יהודה בן בתירה גם כאשר \u0003הוה נסיבא מעיקרא\u0004 \u0005[שהיתה נשואה מתחילה]\u0006 יוצאת בלא מיאון, ודי לה שנתקדשה לאחר, \u0003או דלמא מיקדשא\u0004 \u0005[שמא\u0006 שהיתה רק \u0005מקודשת\u0006 בלבד\u0005]\u0006 די לה בקידושיה לאחר, אבל אם היתה נשואה מתחילה צריכה מיאון ממש? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לכך ממעשה זה, \u0003דכלתיה\u0004 \u0005[שכלותיו]\u0006 של \u0003אבדן,\u0004 אבא יודן, \u0003אימרוד\u0004 \u0005[מרדו\u0006 בבעליהן\u0005],\u0006 \u0003שדר\u0004 \u0005[שלח]\u0006 \u0003רבי זוגי דרבנן למיבדקינהו\u0004 \u0005[זוג חכמים לבדוק אותן],\u0006 ולברר אם, ומה, יש לעשות לתיקון הדבר. \u0003אמרי להו נשי\u0004 \u0005[אמרו להן נשים]:\u0006 \u0003חזו גברייכו דקאתו\u0004 \u0005[ראו\u0006 את \u0005בעליכם ש\u0006הם \u0005באים].\u0006 \u0003אמרי להו\u0004 \u0005[אמרו,\u0006 השיבו \u0005להן]:\u0006 \u0003ניהוו גברייכו דידכו\u0004 \u0005[שיהיו\u0006 אלה \u0005בעלים שלכן].\u0006","\u0003אמר רבי: אין לך מיאון גדול מזה. מאי לאו דהוה נסיבא\u0004 \u0005[האם לא שהיו נשואות]\u0006 כבר? ודוחים: \u0003לא, דהוה מיקדשא קדושי\u0004 \u0005[שהיו מקודשות\u0006 בלבד\u0005]\u0006 אבל לא נשואות, ומכאן אין, איפוא, להוכיח מה הדין אילו היו נשואות. \u0003ו\u0004מסכמים: \u0003הלכה כר' יהודה בן בתירה\u0004 בכל ענין, \u0003ואפילו בנישואין דקמא\u0004 \u0005[של הראשון]\u0006 שאפילו אם היתה נשואה ממש לראשון, הנישואין בטלים על ידי זה שמתקדשת לאחר ואין עוד צורך במיאון.","שנינו במשנה ש\u0003ר' אלעזר אומר:\u0004 אין מעשה קטנה כלום, אלא דינה כמפותה. \u0003אמר רב יהודה אמר שמואל: חוזרני,\u0004 חוזר ובודק אני \u0003על כל צדדי חכמים\u0004 בעניינים אלה \u0003ולא מצאתי אדם שהשוה מדותיו\u0004 ונקט בקו מחשבה עקבי כל כך \u0003בקטנה כר' אלעזר. שעשאה ר' אלעזר כמטיילת עמו בחצר, ועומדת מחיקו\u0004 לאחר שבא עליה \u0003וטובלת\u0004 להיטהר \u0003ואוכלת בתרומה לערב\u0004 כשהיא בת כהן. כלומר, כאילו לא היה ביניהם כל קשר של נישואין.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אין מעשה קטנה כלום\u0004 ולכן לנישואיה אין תוקף, \u0003ו\u0004לכן קטנה שהשיאוה אימה ואחיה \u0003אין בעלה זכאי לא במציאתה, ולא במעשה ידיה, ולא בהפרת נדריה, ואינו יורשה\u0004 אם מתה, \u0003ו\u0004אם כהן הוא — \u0003אין מיטמא לה. כללו של דבר: אינה כאשתו לכל דבר, אלא שצריכה מיאון\u0004 כדי לצאת ממנו.","\u0003ר' יהושע אומר:\u0004 קטנה שהשיאוה אמה ואחיה, \u0003בעלה זכאי במציאתה, ובמעשה ידיה, ובהפרת נדריה, ויורשה\u0004 אם מתה, \u0003ומיטמא לה\u0004 אם כהן הוא. \u0003כללו של דבר: הרי היא כאשתו לכל דבר, אלא שיוצאה במיאון\u0004 ואינה צריכה גט.","\u0003אמר רבי: נראין דברי ר' אליעזר\u0004 יותר \u0003מדברי ר' יהושע, שר' אליעזר השוה מדותיו\u0004 ויש לו שיטה אחת \u0003בקטנה, ור' יהושע חלק.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 במה\u0005]\u0006 \u0003חלק?\u0004 אם תאמר בענין זה, ש\u0003אי\u0004 \u0005[אם]\u0006 \u0003אשתו היא — תיבעי\u0004 \u0005[תצטרך]\u0006 \u0003גט\u0004 ממנו.","אולם \u0003לר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לאו אשתו היא — מיאון נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך]!\u0006 ומשיבים: \u0003אלא בכדי תיפוק\u0004 \u0005[לריק,\u0006 בלי שום דבר, \u0005תצא]?!\u0006 הרי ודאי צריך מעשה כלשהו שיהיה בזה משום קביעה שהיא יוצאת ממנו לא כפרידה לשעה, אלא לעולם, ומיאון זה הוא כהודעה שהיא יוצאת, ודי בכך, ונמצא שאכן ר' אליעזר הוא המחזיק בשיטה אחת, שלפיה ובעקביותה אין כל תוקף בנישואי הקטנה — מה שאין כן ר' יהושע ששיטתו ביחס לקטנה אינה אחידה.","שנינו במשנה ש\u0003ר' אליעזר בן יעקב אומר:\u0004 כל עכבה שהיא מן האיש כאילו היא אשתו וכל עכבה שאינה מן האיש אינה אשתו. ושואלים על לשון סתומה זו: \u0003היכי דמי\u0004 \u0005[כיצד זה בדיוק]\u0006 \u0003עכבה שהיא מן האיש ו\u0004כיצד זה בדיוק \u0003עכבה שאינה מן האיש? אמר רב יהודה אמר שמואל:\u0004 אם באו לקטנה זו בעודה נשואה ו\u0003תבעוה\u0004 (והציעו לה) \u0003לינשא\u0004 לאחר, \u0003ואמרה\u0004 שאינה רוצה להינשא \u0003\"מחמת פלוני בעלי\" — זו היא עכבה שהיא מן האיש,\u0004 כי מסירובה משתמע שהיא רואה את עצמה עוד כאשתו. ואם אמרה שאיננה רוצה להינשא \u0003\"מחמת\u0004 שהאנשים שמציעים לי להינשא להם הם \u0003בני אדם שאינם מהוגנין לי\" — זו היא עכבה שאינה מן האיש,\u0004 ואינה קרויה אשתו.","\u0003אביי בר אבין ורב חנינא בר אבין דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אם האיש שהקטנה נישאה לו \u0003נתן לה גט\u0004 — \u0003זו היא עכבה שהיא מן האיש,\u0004 שעל ידי מתן הגט נראית היא כאשתו גמורה, ויש תוקף מסויים לנישואין אלה, \u0003ו\u0004לכן \u0003הוא אסור\u0004 מאז \u0003בקרובותיה, והיא אסורה בקרוביו\u0004 לעולם, \u0003ופסלה מן הכהונה\u0004 כגרושה. אולם אם \u0003מיאנה בו — זו היא עכבה שאינה מן האיש, ו\u0004לכן \u0003הוא מותר בקרובותיה, והיא מותרת בקרוביו, ולא פסלה מן הכהונה,\u0004 והרי זה כעקירת הנישואין מלכתחילה.","ומקשים: \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 במפורש \u0003לקמן\u0004 \u0005[לפנינו,\u0006 הלאה, במשנה הבאה\u0005]:\u0006 \u0003הממאנת באיש — הוא מותר בקרובותיה והיא מותרת בקרוביו, ולא פסלה מן הכהונה. נתן לה גט — הוא אסור בקרובותיה, והיא אסורה בקרוביו, ופסלה מן הכהונה,\u0004 ומשמע איפוא שהלכה זו אינה מה שאמר ר' אליעזר בן יעקב! ומשיבים: לא, שני הדברים הם בעצם דבר אחד, אלא \u0003פרושי קמפרש\u0004 \u0005[פירוש הוא\u0006 ש\u0005מפרש\u0006 התנא של המשנה\u0005]\u0006 את הכלל שאמר קודם ר' אליעזר בן יעקב בדרך סתומה.","\u0003הממאנת באיש — הוא מותר בקרובותיה\u0004 כגון באמה ובאחותה, \u0003והיא מותרת בקרוביו\u0004 כגון באביו או באחיו, \u0003ולא פסלה מן הכהונה,\u0004 שאינה נחשבת כגרושה. אולם אם \u0003נתן לה גט,\u0004 למרות שהנישואין היו רק מדברי סופרים — \u0003הוא אסור בקרובותיה, והיא אסורה בקרוביו, ופסלה מן הכהונה.\u0004","\u0003נתן לה גט\u0004 ואחר כן נמלך \u0003והחזירה\u0004 להיות אשתו, ואחר שחזרה לביתו \u0003מיאנה בו ונשאת לאחר, ונתארמלה או נתגרשה\u0004 מבעלה השני — \u0003מותרת לחזור לו.\u0004 שכיון שיצאה ממנו באחרונה על ידי מיאון, הרי זה מבטל את הגט שנתן קודם לכן, ודינה כממאנת שאינה נאסרת על בעלה הראשון בנישואין לאחר. אולם אם היה הסדר אחר: ש\u0003מיאנה בו\u0004 ויצאה מביתו \u0003ו\u0004אחר כך \u0003החזירה,\u0004 ובפעם הזו \u0003נתן לה גט ו\u0004לאחר מכן \u0003נשאת לאחר, ונתארמלה או נתגרשה\u0004 מן השני — \u0003אסורה לחזור לו,\u0004 ככל גרושה שנישאה לאחר."],["\u0003זה הכלל\u0004 לגבי מי שמיאנה ונישאה כמה פעמים: היה \u0003גט אחר מיאון\u0004 ונישאה לאחר — \u0003אסורה לחזור לו, מיאון אחר גט — מותרת לחזור לו.\u0004 ועיקר טעמו של דבר, שכיון שהיה מיאון אחר הגט, מוכיח הדבר שוב שנישואיה הראשונים לא תפסו מדין תורה, ועדיין קטנה היא, אבל כשיוצאת בגט, אין יודעים שקטנה היא, ועלול הדבר להכשיל אחרים במקרה דומה כשמדובר בגדולה.","\u0003הממאנת באיש ונשאת לאחר, וגירשה,\u0004 וחזרה ונישאה \u0003ל\u0004עוד אדם \u0003אחר ומיאנה\u0004 גם \u0003בו,\u0004 ושוב נישאה \u0003ל\u0004אדם \u0003אחר וגירשה, זה הכלל: כל\u0004 מי \u0003שיוצאה הימנו בגט — אסורה לחזור לו,\u0004 וזה שיוצאת הימנו \u0003במיאון — מותרת לחזור לו.\u0004","שנינו במשנה שאם נתן לקטנה גט והחזירה, וחזרה ומיאנה, מותרת לחזור אליו אף שנישאה בינתיים לאחר, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אתי\u0004 \u0005[בא]\u0006 \u0003מיאון ומבטל גט.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בסוף המשנה: \u0003הממאנת באיש ונשאת לאחר, וגירשה; לאחר, ומיאנה בו; לאחר, וגירשה; זה הכלל: כל שיצתה הימנו בגט — אסורה לחזור לו, במיאון — מותרת לחזור לו. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003מיאון דחבריה\u0004 \u0005[של חבירו]\u0006 \u0003ובטיל גיטא דידיה\u0004 \u0005[ומבטל\u0006 את \u0005הגט שלו],\u0006 שאם היה מבטל, היה המיאון עוקר את הנישואין של השני ומותרת לראשון שגירשה, שכל שלא נישאת לאחר, מותרת לחזור אליו.","\u0003אמר רב יהודה אמר שמואל: תברא\u0004 \u0005[שבורה]\u0006 היא המשנה הזו, כלומר, אינה לפי שיטה אחת ו\u0003מי ששנה זו לא שנה זו.\u0004","\u0003אמר רבא: ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבכך? \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יש לומר כך: \u0003מיאון דידיה\u0004 \u0005[שלו]\u0006 \u0003מבטל גט דידיה\u0004 \u0005[שלו],\u0006 \u0003מיאון דחבריה\u0004 \u0005[של חבירו]\u0006 \u0003לא מבטל גיטא דידיה\u0004 \u0005[\u0006את \u0005הגט שלו].\u0006 ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003מיאון דחבריה\u0004 \u0005[של חבירו]\u0006 ש\u0003לא מבטל גיטא דידיה\u0004 \u0005[\u0006את \u0005הגט שלו],\u0006 ומשיבים: יש סברה בדבר, \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003מכרת ברמיזותיו וקריצותיו\u0004 של בעלה הראשון, הריהו מרמז לה אפילו בלא דיבור מפורש, ויש לחשוש שמא \u0003אזל משבש ומייתי לה\u0004 \u0005[יילך\u0006 ו\u0005יטעה\u0006 אותה \u0005ויביא אותה\u0006 אליו\u0005],\u0006 שיגרום לה שתמאן בבעלה החדש, ותחזור אליו, ולכן תיקנו שלא תחזור לבעלה זה, אולם משום טעם זה \u0003מיאון דידיה נמי\u0004 \u0005[שלו גם כן]\u0006 \u0003לא ליבטל גיטא דידיה\u0004 \u0005[יבטל גט שלו],\u0006 \u0003דאיידי\u0004 \u0005[שמתוך]\u0006 ש\u0003מכרת ברמיזותיו וקריצותיו — אזיל משבש ומייתי לה\u0004 \u0005[יילך, יטעה\u0006 אותה \u0005ומביא אותה\u0006 אליו\u0005]\u0006 אחרי שנישאה לאחר!","ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כבר שבשא\u0004 \u0005[\u0006ניסה \u0005להטעותה]\u0006 \u0003ולא אישבשא\u0004 \u0005[הוטעתה].\u0006 כלומר, הרי כבר החזיר אותה אחרי הגירושין ושוב מיאנה בו, ואין לחשוש ששוב ירצה להחזיר אותה אליו.","\u0003אלא אי קשיא\u0004 \u0005[אם קשה]\u0006 ויש סתירה במשנתנו, הרי זה מ\u0003דחבריה אדחבריה קשיא\u0004 \u0005[מ\u0006מיאון \u0005שבחבירו על\u0006 מיאון \u0005שבחבירו קשה],\u0006 ששנינו: \u0003מיאנה בו והחזירה, נתן לה\u0004 לאחר מכן \u0003גט ונשאת לאחר, ונתארמלה\u0004 מאותו אדם \u0003או נתגרשה — אסורה לחזור לו.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003נתארמלה או נתגרשה\u0004 מן האחר, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003מיאנה\u0004 באחר — \u0003מותרת לחזור לו, אלמא אתי\u0004 \u0005[מכאן\u0006 ש\u0005בא]\u0006 \u0003מיאון דחבריה\u0004 \u0005[של חבירו]\u0006 \u0003ומבטל גיטא דידיה\u0004 \u0005[\u0006את \u0005הגט שלו].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו אחר כך: \u0003הממאנת באיש ונשאת לאחר וגירשה,\u0004 ונישאה \u0003לאחר ומיאנה בו, זה הכלל: כל\u0004 מי \u0003שיצתה ממנו בגט — אסורה לחזור לו,\u0004 יצאה \u0003במיאון — מותרת לחזור לו. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003מיאון דחבריה\u0004 \u0005[של חבירו]\u0006 \u0003ומבטל גיטא דידיה\u0004 \u0005[גט שלו]!\u0006","\u0003אמר ר' אלעזר\u0004 על כך: \u0003תברא\u0004 \u0005[שבורה]\u0006 היא המשנה, ו\u0003מי ששנה זו לא שנה זו. עולא אמר:\u0004 כאן במקרה האחרון מדובר \u0003כגון ששלשה בגיטין,\u0004 כלומר, שכבר נתנו לה גט שלוש פעמים, \u0003דמיחזיא\u0004 \u0005[ש\u0006היא \u0005נראית]\u0006 \u0003כגדולה,\u0004 מאחר שהיתה נשואה כבר כמה פעמים, שוב אין משגיחים במיאונה, והכל כבר מחליפים אותה בגדולה שנישאה.","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 שלו התכוון ר' אלעזר ששנה הלכה זו שבסיפא? — \u0003אמר רב יהודה אמר רב:\u0004 דבר זה אפשר לברר על פי המעשה שהיה. שאמרו, \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מימינו בכסף שתינו עצינו במחיר יבאו\"\u0004 (איכה ה, ד), הכוונה היא לדברי תורה הנמשלים למים שהושגו ונקנו בכסף. ומבארים: \u0003בשעת הסכנה\u0004 של גזירות השמד של רומי \u0003נתבקשה\u0004 פסיקת \u0003הלכה זו,\u0004 והיא: \u0003הרי שיצאה מראשון בגט ומשני במיאון, מהו שתחזור לראשון?\u0004","\u0003שכרו אדם אחד בארבע מאות זוז\u0004 לשליחות מסוכנת זו, \u0003ושאלו את ר' עקיבא\u0004 שהיה חבוש \u0003בבית האסורין\u0004 כמורד במלכות על שלימד תורה, \u0003ואסר.\u0004 שאלו \u0003את ר' יהודה בן בתירה בנציבין\u0004 שבבבל \u0003ואסר.\u0004","\u0003אמר ר' ישמעאל בר' יוסי. ל\u0004שאלה \u0003זו לא הוצרכנו,\u0004 שכן אם \u0003לאיסור כרת התרת,\u0004 שהרי על ידי מיאון נמצאת מתיר איסור אשת איש שהוא איסור כרת, ואם כן \u0003לאיסור לאו\u0004 \u0005[לא\u0006 תעשה\u0005]\u0006 של מחזיר גרושתו \u0003לא כל שכן\u0004 שמותר על ידי המיאון, שעוקר את הנישואין מעיקרם.","\u0003ברם\u0004 (אבל) \u0003כך שאלו: הרי היתה\u0004 קטנה \u0003אשת אחי אמו, שהיא שנייה\u0004 (לערוה) \u0003לו\u0004 ואסורה עליו מדברי סופרים, \u0003ונשאה אחיו מאביו ומת,\u0004 ונפלה לפניו כיבמה, \u0003מהו שתמאן השתא\u0004 \u0005[עכשיו]\u0006 \u0003ותעקרינהו\u0004 \u0005[ותעקור\u0006 עכשיו \u0005אותם]\u0006 את ה\u0003נישואין קמאי\u0004 \u0005[הראשונים]\u0006 שהיתה נשואה לאחי האם, ושוב אין היא בגדר ערוה, ואין צרתה איפוא צרת ערוה \u0003ותתייבם צרתה.\u0004 והשאלה היא: האם \u0003יש\u0004 תוקף ל\u0003מיאון לאחר מיתה\u0004 של הבעל, \u0003במקום מצוה\u0004 של ייבום, \u0003או לא?\u0004","ולשם כך \u0003שכרו שני בני אדם בארבע מאות זוז, ובאו ושאלו את ר' עקיבא בבית האסורין, ואסר.\u0004 שאלו \u0003את ר' יהודה בן בתירה בנציבין, ואסר.\u0004","\u0003אמר רב יצחק בר אשיאן: ומודה רב ש\u0004אף על פי שאין המיאון של חבירו מבטל את גיטו ואסורה לחזור אליו, מכל מקום \u0003מותרת לאחיו של זה שנאסרה עליו\u0004 על ידי גט ואינה נחשבת לצורך זה כגרושת אחיו, לפי שהמיאון ביטל את הגט כלפיו.","ותוהים: הלא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, שהרי הסברנו מהו הטעם שאסור לה לחזור כי \u0003הוא ניהו\u0004 \u0005[זה]\u0006 \u0003דמכרת\u0004 \u0005[שמכירה]\u0006 \u0003ברמיזותיו וקריצותיו, אבל אחיו לא,\u0004 ואצלו אין חשש שיטעה אותה למאן בבעלה! ועונים: אין זה פשוט כל כך כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליגזר האי אטו האי\u0004 \u0005[נגזור משום זה]\u0006 שתיאסר גם על האח, כאילו היא גרושת אחיו כדי שלא יבואו להתיר להינשא גם לאח שנתן גט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא גזרו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב יצחק בר אשיאן: כשם שאסורה לו\u0004 למגרש, \u0003כך אסורה לאחין\u0004 שלו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אינה מכרת בקריצותיהם ורמיזותיהם,\u0004 ומה טעם אסרוה? ומשיבים: \u0003גזירה\u0004 על \u0003אחיו אטו\u0004 \u0005[משום]\u0006 \u0003הוא\u0004 עצמו, שהרי אם יתירוה לאחים, יבואו להתירה גם לו עצמו אף שהיא אסורה לו.","\u0003המגרש את האשה והחזירה\u0004 (נשאה) ומת בלי בנים — \u0003מותרת ליבם.\u0004"],["\u0003ור' אלעזר אוסר. וכן המגרש את היתומה\u0004 הקטנה שהשיאו אותה אימה או אחיה \u0003והחזירה\u0004 ומת — \u0003מותרת ליבם. ור' אלעזר אוסר. קטנה שהשיאה אביה,\u0004 שנישואין אלה יש להם תוקף מן התורה \u0003ונתגרשה\u0004 עוד בהיותה קטנה — הרי דינה \u0003כיתומה בחיי האב,\u0004 ששוב אין זכות לאביה להשיא אותה, וכיון שקטנה היא, אינה יכולה להינשא נישואין גמורים. \u0003ו\u0004אם \u0003החזירה\u0004 בעלה בעודה קטנה ומת — \u0003דברי הכל אסורה ליבם.\u0004","\u0003אמר\u0004 החכם \u0003עיפה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר\u0004 שאוסר לייבם אשה שגירשה בעלה והחזירה — \u0003הואיל ועמדה עליו,\u0004 על היבם, \u0003שעה אחת באיסורא\u0004 \u0005[באיסור].\u0006 כי בשעה שגירש אחיו את האשה נאסרה זו ליבם משום גרושת אחיו (שכן אשת אח אסורה גם לאחר שבטל קשר הנישואין), וכיון שאז היתה אסורה עליו — שוב אין נישואי אחיו השניים יכולים להתירה. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לעיפה: אי הכי\u0004 \u0005[אם כך]\u0006 מטעם זה, \u0003חליצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך],\u0006 שהרי חל עליה איסור ערוה (אשת אח) ונעקרה חובת ייבום ממנה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 שר' אלעזר פוטרה אף מן החליצה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003משום ר' אלעזר אמרו: חולצת! אלא אמר עיפה: ר' אלעזר לא ידענא מאי טעמא\u0004 \u0005[איני יודע מה טעם\u0006 דבריו\u0005].\u0006","\u0003אמר אביי: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' אלעזר: מספקא ליה\u0004 \u0005[מסופק לו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מיתה מפלת,\u0004 כלומר, האם חיוב הייבום חל עם מיתת הבעל, והמצב בזמן המיתה הוא הקובע, \u0003אי\u0004 \u0005[או]\u0006 \u0003נשואין הראשונים מפילים,\u0004 ולפיהם נקבעת חובת הייבום. ולענייננו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מיתה מפלת — הא רמיא קמיה\u0004 \u0005[הרי\u0006 היא \u0005מוטלת לפניו]\u0006 \u0003לייבום,\u0004 שהיא אשת אחיו שמת בלא בנים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003נשואין הראשונים מפילים — הא\u0004 \u0005[הרי]\u0006 \u0003עמדה עליו שעה אחת באיסור\u0004 גרושת אחיו, ואז היתה צריכה להיות פטורה לגמרי. ומחמת ספק זה הריהו מצריכה חליצה בלא ייבום.","\u0003רבא אמר: לעולם פשיטא\u0004 \u0005[פשוט]\u0006 לו \u0003לר' אלעזר\u0004 ש\u0003מיתה מפלת, ומיהו\u0004 \u0005[ואולם]\u0006 \u0003הכל בקיאין בגירושין,\u0004 כלומר, הכל יודעים שאשה זו נתגרשה בזמנו, \u0003ואין הכל בקיאין בחזרה\u0004 שלה לבעלה לאחר מכן, ולכן יש חשש שאנשים יטעו ויחשבו שמותר לייבם את אשת אחיו שנתגרשה.","ותוהים: \u0003אדרבה\u0004 (להיפך), \u0003חזרה, כיון דיתבא תותיה\u0004 \u0005[שיושבת תחתיו],\u0006 \u0003אית ליה קלא\u0004 \u0005[יש לה קול],\u0006 והכל יודעים שהיא אשתו! ומשיבים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא עסקינן\u0004 \u0005[עוסקים אנו]\u0006 אפילו במקרה \u0003דאהדרה באורתא ושכיב בצפרא\u0004 \u0005[שהחזירה בערב ומת בבוקר],\u0006 ובמקרה זה וכיוצא בו אין הכל יודעים שהחזירה וסבורים שייבם את גרושת אחיו, ולכן גזר ר' אלעזר שאסורה.","\u0003רב אשי אמר: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' אלעזר,\u0004 ש\u0003גזר\u0004 על \u0003הני\u0004 \u0005[אלה]\u0006 שהתגרשו ואחר כך חזרו, \u0003משום\u0004 זו שהיא \u0003\"יתומה בחיי האב\"\u0004 שהתגרשה מבעלה \u0003והחזירה\u0004 כשהיא קטנה. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה בסופה]\u0006 של משנה זו: \u0003קטנה שהשיאה אביה ונתגרשה כיתומה בחיי האב, והחזירה — דברי הכל שאסורה ליבם.\u0004","ואם לצורך הלכה זו גופה — \u0003האי מאי למימרא\u0004 \u0005[זו מה\u0006 בא \u0005לומר\u0006 בה\u0005]?\u0006 הלא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! \u0003אלא לאו הא קא משמע לן\u0004 \u0005[\u0006האם \u0005לא זה השמיע לנו]\u0006 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אלעזר\u0004 ש\u0003גזר\u0004 על \u0003הנך\u0004 \u0005[אלה]\u0006 \u0003משום האי\u0004 \u0005[זה].\u0006 ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא הטעם.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אשי: מודים חכמים לר' אלעזר בקטנה שהשיאה אביה ונתגרשה — הרי היא כיתומה בחיי האב, ו\u0004אם \u0003החזירה — שאסורה ליבם, מפני שגירושיה\u0004 היו \u0003גירושין גמורין\u0004 מן התורה \u0003ואין חזרתה חזרה גמורה,\u0004 שכן היא עדיין קטנה, ואין בה נישואין מן התורה. משמע שגם ר' אלעזר מתייחס ליתומה בחיי האב וזו היתה סיבת גזירתו.","ומעירים: \u0003במה דברים אמורים — שגירשה כשהיא קטנה והחזירה כשהיא קטנה\u0004 עדיין, \u0003אבל\u0004 אם \u0003גירשה כשהיא קטנה והחזירה כשהיא גדולה, אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה ש\u0003החזירה כשהיא קטנה וגדלה אצלו\u0004 והתבגרה בעודה נשואה לו \u0003ומת,\u0004 הרי אז \u0003או חולצת או מתייבמת. משום ר' אלעזר אמרו: חולצת ולא מתייבמת,\u0004 שגזר בכל אשה משום יתומה בחיי האב שהחזירה כשהיא קטנה ומת לפני שגדלה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: צרתה\u0004 של יתומה שהחזירה, לדעת ר' אלעזר, \u0003מהו\u0004 דינה? האם נאמר כי מאחר שהיא נאסרת עליו משום ערוה (אשת אח שאין לה היתר), אף צרתה תיאסר כצרת ערוה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היא גופה\u0004 \u0005[עצמה]\u0006 מפני \u0003גזירה\u0004 בלבד היא אסורה, כפי שהסברנו, \u0003ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003וניגזור גזירה לגזירה?\u0004 וצרתה מותרת איפוא לייבום.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בנושא זה, \u0003משום ר' אלעזר אמרו: היא וצרתה חולצת.\u0004 ותחילה יש לתקן את הלשון \u0003היא וצרתה סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?!\u0006 מדוע צריכות שתי נשים מבית אחד לחלוץ? הרי חליצה של אחת פוטרת את השניה! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא: \u0003או היא או צרתה חולצת?\u0004 ודוחים: \u0003לאו תרוצי קמתרצת\u0004 \u0005[\u0006וכי \u0005אין אתה מתרץ\u0006 ומיישב את המשנה\u0005]\u0006 ומשנה בתוך כך את לשונה כדי ליישבה, אם כן \u0003תריץ הכי\u0004 \u0005[תרץ,\u0006 תקן אותה \u0005כך]:\u0006 \u0003היא\u0004 לעולם \u0003חולצת, צרתה — או חולצת או מתייבמת,\u0004 ואם כן אין להוכיח מכאן דבר.","\u0003שני אחין\u0004 ה\u0003נשואין לשתי אחיות קטנות, ומת בעלה של אחת מהן\u0004 ונפלה השניה לפניו לייבום — \u0003הלזו\u0004 היבמה \u0003תצא\u0004 ותיפטר מייבום \u0003משום אחות אשה.\u0004 שכן חובת הייבום במקרה זה היא רק מדברי סופרים וכן נישואיו של היבם עם אשתו הם מדברי סופרים. ומדברי סופרים היא אחות אשתו, ופטורה מייבום וחליצה. \u0003וכן שתי חרשות\u0004 דינן מבחינה זו כשתי קטנות, שכן נישואיהן הם מדברי סופרים כנישואי קטנות. אבל אם היו שני אחים נישואין לשתי אחיות, אחת \u0003גדולה ו\u0004אחת \u0003קטנה,\u0004 אם \u0003מת בעלה של קטנה — תצא הקטנה משום אחות אשה.\u0004","\u0003מת בעלה של גדולה\u0004 מה עושים אז? \u0003ר' אליעזר אומר: מלמדין את הקטנה שתמאן בו\u0004 ויתבטלו נישואיה לגמרי, ויוכל איפוא לייבם את הגדולה, שהיא יבמתו הגמורה מן התורה.","\u0003רבן גמליאל אומר: אם מיאנה\u0004 הקטנה מעצמה — \u0003מיאנה, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003תמתין\u0004 הקטנה \u0003עד שתגדיל\u0004 אצלו, ויהיו נשואיה מן התורה, \u0003ותצא הלזו\u0004 (היבמה) \u0003משום אחות אשה.\u0004","\u0003ר' יהושע אומר:\u0004 לא כן, ואם יארע כך, אז \u0003אי\u0004 (אוי) \u0003לו על אשתו, אי לו על אשת אחיו.\u0004 שכן במקרה כזה \u0003מוציא את אשתו בגט,\u0004 שמאחר שנישואיה הם רק מדברי סופרים — נעשית כצרה ליבמתו המוטלת לפניו לייבום מן התורה, \u0003ו\u0004את \u0003אשת אחיו\u0004 מוציא \u0003בחליצה,\u0004 ואינו יכול ליבמה, שכן היא אחות גרושתו מדברי סופרים.","על העצה שייעץ ר' אליעזר שילמדו אותה למאן שואלים: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 ללמד אותה למאן? \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003בר קפרא: לעולם ידבק אדם בשלשה דברים, ויתרחק משלשה דברים.\u0004 ומפרטים: \u0003ידבק בשלשה דברים: בחליצה\u0004 ולא בייבום, \u0003ובהבאת שלום, ובהפרת נדרים. ויתרחק משלשה דברים: מן המיאון, ומן הפקדונות,\u0004 שרצוי שלא יקבל, \u0003ומן הערבונות,\u0004 שלא יהיה ערב לחובות של אחרים! ומשיבים: אין זה קשה, \u0003מיאון\u0004 שיש בו משום \u0003מצוה\u0004 מטעם כלשהו, \u0003שאני\u0004 \u0005[שונה]\u0006 שהרי מיאון זה נעשה לשם קיום מצות ייבום באחותה.","\u0003גופא\u0004 \u0005[לגופו\u0006 של דבר\u0005]\u0006 שהבאנו, מבארים אותו לפרטיו. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: לעולם ידבק אדם בשלשה דברים: בחליצה\u0004 — דבר זה הוא \u0003כ\u0004דעת \u0003אבא שאול, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא שאול אומר: הכונס את יבמתו לשם נוי\u0004 משום שהיא יפה, או \u0003לשם אישות\u0004 שרוצה להיות נשוי לאשה זו, או \u0003לשם דבר אחר,\u0004 כגון ממון שיש לה — \u0003כאילו פוגע ב\u0004איסור \u0003ערוה, וקרוב בעיני להיות הולד ממזר.\u0004 ולכן מוטב שיחלוץ ולא יבוא לחטא זה.","וידבק \u0003בהבאת שלום — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בקש שלום ורדפהו\"\u0004 (תהלים לד, טו),"],["\u0003ואמר ר' אבהו: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 בגזירה שווה \u0003\"רדיפה\" \"רדיפה\"\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"בקש שלום ורדפהו\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"רדף צדקה וחסד ימצא חיים צדקה וכבוד\"\u0004 (משלי כא, כא), הרי שהרדיפה אחרי מעשים טובים אלה היא מצוה וכמו כן השלום הנלמד מהם בגזירה שווה. שישתדל \u0003בהפרת נדרים — כ\u0004דעת \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: הנודר\u0004 נדר — \u0003כאילו בנה במה\u0004 בזמן שבית המקדש קיים, שאסור לבנות במה לה' מחוץ לבית המקדש. \u0003והמקיימו\u0004 את הנדר הזה — \u0003כאילו הקריב עליה,\u0004 על במה זו, \u0003קרבן,\u0004 שהכפיל את חטאו. ולכן מוטב שישאל חכם ויתיר את הנדר.","\u0003ויתרחק משלשה דברים: מן המיאונין — דלמא גדלה ומיחרטא\u0004 \u0005[שמא תגדל ותתחרט]\u0006 ותחזור \u0003בה\u0004 ותיווכח שרק מפני ילדותה מיאנה בבעל ההגון לה. \u0003מן הפקדונות\u0004 — מדובר כאן \u0003בבר מתא\u0004 \u0005[בבן עיר],\u0006 כלומר, שהמפקיד והנפקד בני עיר אחת הם, \u0003דבייתיה כי בייתיה דמי\u0004 \u0005[שביתו\u0006 של הנפקד \u0005כביתו\u0006 של המפקיד \u0005נחשב],\u0006 והמפקיד עשוי בכל עת להיכנס לביתו של המחזיק בפיקדון ושמא יטול את פקדונו, ואחר כך יתבע אותו ממנו. \u0003מן הערבון\u0004 — מדובר פה \u0003בערבי שלציון,\u0004 כלומר, ערבות כזו שבה המלוה רשאי לתבוע מן הערב לפני שתובע מן הלווה.","ש\u0003אמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"רע ירוע כי ערב זר\u0004 ושונא תוקעים בוטח\u0003\"\u0004 (שם יא, טו), כוונתו: \u0003רעה אחר רעה תבא למקבלי גרים, ולערבי שלציון, ולתוקע עצמו לדבר הלכה.\u0004 ומבארים: \u0003מקבלי גרים — כ\u0004דעת \u0003ר' חלבו.\u0004 ש\u0003אמר ר' חלבו: קשים גרים לישראל כספחת בעור.\u0004","\u0003ערבי שלציון — דעבדי\u0004 \u0005[שעושים]\u0006 \u0003שלוף דוץ\u0004 \u0005[ונעץ],\u0006 כלומר, מוציאים את הלווה ותוקעים את הערב במקומו. \u0003תוקע עצמו לדבר הלכה\u0004 עניינו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: כל האומר\u0004 ש\u0003אין לו תורה — אין לו תורה.\u0004 ותוהים: אם אומר שאין לו תורה ואינו לומדה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא! \u0003אלא\u0004 יש לתקן ולומר כך: \u0003כל האומר\u0004 ש\u0003אין לו אלא תורה — אין לו אלא תורה.\u0004","ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט,\u0006 מובן מאליו הוא\u0005]!\u0006 שוודאי אינו מקבל שכר יותר ממה שעשה! \u0003אלא\u0004 הכוונה היא ש\u0003אפילו תורה אין לו. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב פפא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולמדתם ועשיתם\"\u0004 שהוא קיצור הכתוב \"ולמדתם אותם ושמרתם לעשותם\" (דברים ה, א), להשמיענו: \u0003כל שישנו בעשיה — ישנו בלמידה, כל שאינו בעשיה — אינו בלמידה,\u0004 והרוצה לעסוק רק בתורה בלא לקיימה — אף עיסוקו בתורה אינו נחשב לו כמצוה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם כדאמריתו מעיקרא\u0004 \u0005[כפי שאמרתם מתחילה]\u0006 ש\u0003כל האומר אין לו אלא תורה — אין לו אלא תורה,\u0004 ו\u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דקא מגמר לאחריני ואזלי ועבדי\u0004 \u0005[שהוא מלמד לאחרים ו\u0006הם \u0005הולכים ועושים].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אית ליה אגרא לדידיה\u0004 \u0005[יש לו שכר לעצמו],\u0006 שהרי גרם לאחרים שיעשו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שלא נתכוון ללמוד על מנת לעשות בעצמו — אינו מקבל שכר מצוה כאילו עשה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003תוקע עצמו לדבר הלכה,\u0004 הכוונה היא: \u0003בדיינא דאתי דינא לקמיה\u0004 \u0005[בדיין שבא דין לפניו],\u0006 \u0003וגמר\u0004 \u0005[ולמד,\u0006 קיבל\u0005]\u0006 \u0003הלכה\u0004 בענין דומה \u0003ומדמי מילתא למילתא\u0004 \u0005[ומדמה דבר לדבר],\u0006 \u0003ואית ליה רבה ולא אזיל משאיל\u0004 \u0005[ויש לו רב\u0006 במקום \u0005ואינו הולך לשאול]\u0006 מה הלכה למעשה במקרה זה, שצריך הדיין להיזהר מאד שלא יטעה בדינו.","ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: לעולם יראה דיין עצמו כאילו חרב מונחת לו בין יריכותיו,\u0004 שאם נוטה ימין ושמאל הרי הוא נפגע, \u0003ו\u0004כאילו \u0003גיהנם פתוחה לו מתחתיו, שנאמר: \"הנה מטתו שלשלמה ששים גברים סביב לה מגברי ישראל.\u0004 כולם אחוזי חרב מלומדי מלחמה איש חרבו על ירכו \u0003מפחד בלילות\"\u0004 (שיר השירים ג, ז-ח), והכוונה: \u0003מפחד של גיהנם שדומה ללילה.\u0004 ודורש פסוק זה על הדיינים (\"גבורי ישראל\") היושבים במקדש (\"מטתו\" של המלך שהשלום שלו).","שנינו במשנה ש\u0003רבן גמליאל אומר: אם מיאנה\u0004 אשתו הקטנה — מיאנה, ואם לא — ימתינו עד שתגדיל ותצא היבמה משום אחות אשתו. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אלעזר מרב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן גמליאל,\u0004 האם \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 כי \u0003קידושי קטנה מיתלא תלו\u0004 \u0005[תלויים\u0006 ועומדים הם\u0005],\u0006 \u0003וכי גדלה גדלי בהדה\u0004 \u0005[וכאשר\u0006 היא \u0005גדלה,\u0006 הקידושין כאילו \u0005גדלים איתה]\u0006 עד שבהגיעה לבגרות חלים הקידושין חלות גמורה, ו\u0003אף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא בעל\u0004 אותה לאחר שגדלה,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003המקדש אחות יבמה — נפטרה יבמה והלכה לה,\u0004 אפילו שזיקת היבמה קדמה, ודווקא בקידושין גמורים, ולכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעל\u0004 אותה לאחר שגדלה והתכוון בכך לקידושין גמורים — \u0003אין\u0004 \u0005[כן]\u0006 נפטרה היבמה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעל — לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רבן גמליאל, משום דקסבר\u0004 \u0005[שהוא סובר]\u0006 כי \u0003המקדש אחות יבמה נפטרה יבמה והלכה לה,\u0004 ולכן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעל\u0004 אותה כשגדלה — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעל — לא.\u0004","\u0003אמר רב ששת: אמינא\u0004 \u0005[אומר אני],\u0006 \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב, אמר להא שמעתא\u0004 \u0005[את ההלכה הזו]\u0006 שאיננה מבוררת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המקדש את הקטנה — קידושיה תלויין. מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תלויין\"? לאו כי גדלה גדלי בהדה\u0004 \u0005[האם אין\u0006 הכוונה \u0005שכאשר\u0006 היא \u0005גדלה,\u0006 הקידושין \u0005גדלים איתה]\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא בעל\u0004 אותה כשגדלה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן:\u0004 יש להבין את הענין אחרת ולדחות ראיה זו, שכן \u0003הא מילתא\u0004 \u0005[דבר זה],\u0006 קידושיה של ה\u0003קטנה, מיתלא תליא וקיימא\u0004 \u0005[תלוי ועומד],\u0006 כלומר, קידושיה הם ספק כל עוד היא קטנה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעל\u0004 אותה לאחר שגדלה — \u0003אין\u0004 \u0005[כן],\u0006 קידושיה קידושין, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעל\u0004 אותה כשגדלה — \u0003לא.\u0004 שכל עוד היא קטנה אין היא יודעת אם קידושיה יהיו קידושין גמורים \u0003דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003הוא עדיף מינאי\u0004 \u0005[ממני],\u0006 שיכול להוציא אותי בגט, \u0003ואנא עדיפנא מיניה\u0004 \u0005[ואני עדיפה ממנו],\u0006 שאני יכולה למאן בו. ולכן, כיון שהנישואין אינם מוחלטים משני הצדדים — אינם חלים.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם באמת \u0005סבור]\u0006 \u0003רב אי\u0004 \u0005[אם]\u0006 \u0003בעל\u0004 אותה כשגדלה — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעל — לא? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בשאלה זו: \u0003קטנה שלא מיאנה, והגדילה\u0004 תחת בעלה, \u0003ועמדה ונשאת\u0004 לאחר, \u0003רב אמר: אינה צריכה גט משני,\u0004 שכן הנישואין לשני לא חלו כלל, שהיא נשואה לראשון נישואין גמורים, \u0003ושמואל אמר: צריכה גט משני,\u0004 שלא ברור לו אם תפסו הנישואין לשני."]]};
